const now = () => new Date().toISOString();
const text = v => String(v ?? '').trim();
/** HTML-escape. `text()` normalises whitespace only and is also used for non-HTML fields
 *  (recipient address, subject), so escaping belongs at the HTML interpolation site. */
const h = v => String(v ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const lower = v => text(v).toLowerCase();
function taskKey(t){ return [t?.id,t?.taskId,t?.referenceId,t?.RefIDD,t?.Reference_ID,t?.AssignmentID,t?.DGOPID].map(text).filter(Boolean); }
export function findAcknowledgementTask(state=State.get(), key=''){
  const v=lower(key); if(!v) return null;
  return (state.tracking||[]).find(t=>taskKey(t).some(k=>lower(k)===v)) || null;
}
export function activeAcknowledgementKey(state=State.get()){
  const ctx=state.deepLinkContext||{}; return text(ctx.taskId||ctx.referenceId||state.selectedId||'');
}
export function selectTaskForAcknowledgement(state=State.get(), uiSelected=''){
  return findAcknowledgementTask(state, uiSelected) || findAcknowledgementTask(state, activeAcknowledgementKey(state)) || (state.tracking||[])[0] || null;
}

export function resolveAcknowledgementActor({profile=State.get().profile||{}, context=State.get().deepLinkContext||{}, form={}}={}){
  const email = text(form.actorEmail || form.email || context.actorEmail || context.userEmail || context.staffEmail || context.email || profile.email);
  const name = text(form.actorName || form.name || context.actorName || context.userName || context.displayName || context.name || profile.name || email);
  const persona = text(form.persona || form.role || context.persona || context.role || profile.persona || 'operator');
  const department = text(form.department || context.department || context.unit || profile.department || '');
  const phone = text(form.phone || context.phone || profile.phone || '');
  const source = form.actorEmail || form.email ? 'form' : (context.actorEmail || context.userEmail || context.staffEmail || context.email || context.name ? 'deeplink' : 'state-profile');
  return Object.freeze({ name, email, persona, department, phone, source });
}


export function assignedToForTask(task={}){
  return text(task.assignedTo || task.AssignedTo || task.assigneeEmail || task.assigned || '');
}
export function acknowledgementStatusForTask(task={}){
  return text(task.assignedToAcknowledgementStatus?.Value || task.AssignedToAcknowledgementStatus?.Value || task.acknowledgementStatus || task.ackStatus || (task.acknowledged ? 'Acknowledged' : 'Assigned')) || 'Assigned';
}
export function canActorAcknowledge(task, actor){
  const assignedTo = lower(assignedToForTask(task));
  const actorEmail = lower(actor?.email || actor?.actorEmail || '');
  return Object.freeze({ allowed: !!assignedTo && !!actorEmail && assignedTo === actorEmail, assignedTo, actorEmail, reason: !assignedTo ? 'task has no assignedTo email' : !actorEmail ? 'acknowledging user email is required' : assignedTo !== actorEmail ? `only assigned user ${assignedTo} may acknowledge` : '' });
}
export function buildAcknowledgementNotification(task, payload){
  const title = text(task.title || task.Title || 'Task');
  const assignedTo = assignedToForTask(task);
  const due = text(task.due || task.DueDate || task.dueDate || '');
  const priority = text(task.priority || task.Priority?.Value || task.Priority || '');
  const category = text(task.category || task.Category || '');
  // HTML-escape every interpolation. `text()` only trims, and several of these fields
  // originate in deep-link query parameters (config/deeplink.config.js preserveQueryParams
  // -> State.deepLinkContext -> resolveAcknowledgementActor), so raw interpolation let a
  // crafted link inject markup into an official acknowledgement email that the platform
  // itself sends to the assignee and CCs to the registry.
  const body = `<!doctype html><html><body style="font-family:Arial,sans-serif;background:#f4f4f4;padding:18px"><div style="max-width:640px;margin:auto;background:#fff;border-radius:8px;border:1px solid #e5e7eb;overflow:hidden"><div style="background:#05583B;color:#fff;padding:14px 18px;text-align:center"><h2 style="margin:0">Task Acknowledgment Confirmation</h2></div><div style="padding:16px"><p>Your task <b>${h(title)}</b> has been acknowledged by <b>${h(payload.actorName)}</b>.</p><table style="width:100%;border-collapse:collapse"><tr><th align="left">Reference</th><td>${h(payload.referenceId)}</td></tr><tr><th align="left">Category</th><td>${h(category)}</td></tr><tr><th align="left">Assigned To</th><td>${h(assignedTo)}</td></tr><tr><th align="left">Priority</th><td>${h(priority)}</td></tr><tr><th align="left">Due Date</th><td>${h(due)}</td></tr><tr><th align="left">Acknowledged Time</th><td>${h(payload.acknowledgedTime)}</td></tr><tr><th align="left">Acknowledged By</th><td>${h(payload.actorName)} &lt;${h(payload.actorEmail)}&gt;</td></tr></table></div><div style="padding:12px 16px;background:#f9fafb;color:#6b7280;font-size:12px">DGO Digital OPS acknowledgement evidence</div></div></body></html>`;
  return Object.freeze({ to: assignedTo, cc: 'dgsregistry@nitda.gov.ng', subject: `Task Acknowledged: ${title} (${payload.taskId})`, body, format:'html' });
}

export async function buildAcknowledgementPayload(task, {source='acknowledgment', actor=State.get().profile||{}, context=State.get().deepLinkContext||{}, form={}, at=now()}={}){
  if(!task) throw new Error('Acknowledgement task is required');
  const resolvedActor = resolveAcknowledgementActor({profile:actor, context, form});
  const taskId=text(task.id||task.taskId||context.taskId);
  const referenceId=text(task.referenceId||task.RefIDD||task.Reference_ID||context.referenceId||taskId);
  const base={
    operation: AcknowledgementFlowConfig.operation,
    mode: 'single',
    taskId,
    referenceId,
    acknowledgedTime: at,
    source,
    actor: { name: resolvedActor.name, email: resolvedActor.email, persona: resolvedActor.persona, department: resolvedActor.department, phone: resolvedActor.phone, capturedFrom: resolvedActor.source },
    actorName: resolvedActor.name,
    actorEmail: resolvedActor.email,
    actorPersona: resolvedActor.persona,
    actorDepartment: resolvedActor.department,
    actorPhone: resolvedActor.phone,
    actorCapturedFrom: resolvedActor.source,
    assignedTo: assignedToForTask(task),
    assignedToAcknowledgementStatus: acknowledgementStatusForTask(task),
    taskTitle: text(task.title||task.Title||''),
    category: text(task.category||task.Category||''),
    priority: text(task.priority||task.Priority?.Value||task.Priority||''),
    dueDate: text(task.due||task.DueDate||task.dueDate||''),
    route: 'acknowledgment',
    matchedParam: context.matchedParam||'',
    deepLinkSource: context.source||'',
    returnTo: context.returnTo||'',
    batchId: context.batchId||'',
    trackingId: context.trackingId||'',
    userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : '',
    notification: null,
    __confirmedByUI: true
  };
  const idempotencyKey = await Idempotency.key({operation: AcknowledgementFlowConfig.operation, ref: referenceId||taskId, actor:resolvedActor, payload:{taskId,referenceId,acknowledgedTime:at,source,actorEmail:resolvedActor.email}});
  const payload = {...base, idempotencyKey};
  payload.notification = buildAcknowledgementNotification(task, payload);
  return Object.freeze(payload);
}
export function validateAcknowledgementPayload(payload={}){
  const missing=AcknowledgementFlowConfig.requiredPayloadFields.filter(k=>!payload[k]);
  const errors=[];
  if(missing.length) errors.push('Missing acknowledgement payload field(s): '+missing.join(', '));
  if(!payload.actor?.email && !payload.actorEmail) errors.push('acknowledging user email is required');
  if(!payload.actor?.name && !payload.actorName) errors.push('acknowledging user name is required');
  if(payload.assignedTo && lower(payload.assignedTo) !== lower(payload.actorEmail)) errors.push('User Not Allowed: only the assigned user '+payload.assignedTo+' may acknowledge this task');
  return Object.freeze(errors);
}
export async function submitAcknowledgement(task, {source='acknowledgment', sync=true, context=State.get().deepLinkContext||{}, form={}}={}){
  const state=State.get(); const profile=state.profile||{};
  const payload=await buildAcknowledgementPayload(task,{source,actor:profile,context,form});
  const actorGate=canActorAcknowledge(task,payload.actor);
  if(!actorGate.allowed){ ReceiptLedger.record({type:'acknowledgement',taskId:payload.taskId,ref:payload.referenceId,status:'unauthorized',actorEmail:payload.actorEmail,actorName:payload.actorName,actorCapturedFrom:payload.actorCapturedFrom,source,payload,response:{reason:actorGate.reason}}); throw new Error('User Not Allowed: '+actorGate.reason); }
  const errors=validateAcknowledgementPayload(payload); if(errors.length) throw new Error(errors.join('; '));
  const already=lower(payload.assignedToAcknowledgementStatus)==='acknowledged' || !!task.acknowledged;
  if(!already){ const r=acknowledgeTask(State.get(), payload.taskId, payload.actorEmail, {surface:source}); if(r) State.patch(r.patch,{module:'acknowledgment',action:'ack:local',event:'audit:acknowledged-local',ref:payload.referenceId||payload.taskId}); }
  if(already){
    const receipt=ReceiptLedger.record({type:'acknowledgement',taskId:payload.taskId,ref:payload.referenceId,status:'already-acknowledged',actorEmail:payload.actorEmail,source,payload,attempts:0});
    return Object.freeze({ok:true,status:'already-acknowledged',payload,receipt,backend:null});
  }
  let backend=null, status='acknowledged';
  if(sync){
    try{
      backend=await DataClient.request(AcknowledgementFlowConfig.endpointAlias,payload,{retry:0,skipConfirmation:true});
      status='sent';
    }catch(error){
      OfflineActionQueue.enqueueAck(payload,error.message||'Acknowledgement backend sync failed');
      status='queued';
      backend={ok:false,error:error.message||String(error),queued:true};
    }
  }
  const receipt=ReceiptLedger.record({type:'acknowledgement',taskId:payload.taskId,ref:payload.referenceId,status,actorEmail:payload.actorEmail,source,payload,response:backend,attempts:status==='queued'?0:1,sentAt:status==='sent'?now():''});
  State.patch({runtime:{...(State.get().runtime||{}),lastAcknowledgement:{at:now(),status,taskId:payload.taskId,referenceId:payload.referenceId,actorEmail:payload.actorEmail,actorName:payload.actorName,actorCapturedFrom:payload.actorCapturedFrom,receiptId:receipt.receiptId}}},{module:'acknowledgment',action:'ack:receipt',event:'audit:acknowledgement-receipt',ref:payload.referenceId||payload.taskId});
  return Object.freeze({ok:true,status,payload,receipt,backend});
}
export async function retryQueuedAcknowledgements(){ return OfflineActionQueue.retryAckQueue(); }
export function acknowledgementHealth(){ const r=ReceiptLedger.stats(), q=OfflineActionQueue.summary(); return Object.freeze({receipts:r, queue:q, ready:true, endpoint:AcknowledgementFlowConfig.endpointAlias, operation:AcknowledgementFlowConfig.operation}); }
export function exportAcknowledgementReceipts(kind='json'){
  return kind==='csv' ? ReceiptLedger.exportCSV() : ReceiptLedger.exportJSON();
}

import { State } from './state.js';
import { AuditLog } from './audit-log.js';
import { toast } from './ui.js';
import { boundaryFor, ownsAction } from '../config/module-boundaries.config.js';
import { actionSpec } from '../config/action-ownership.config.js';
import { ensureCurrentUserActive, getCurrentUser } from './current-user.js';
import { ErrorClass } from './errors.js';
/* ─── Operator-facing failure copy ────────────────────────────────────────────────────────
 * This layer is the only place that reliably sees EVERY failed governed action, so it owns
 * the message an operator reads when one fails. It used to toast `error.message`, which is
 * written for whoever has to fix the platform, not for whoever pressed the button: an
 * unconfigured contract key surfaced as "AI_CHAT: Endpoint AI_CHAT is not configured" on a
 * registry officer's screen — the exact vocabulary audit finding I-07 bans, reintroduced by
 * the governance layer after every module's copy had been rewritten.
 *
 * core/errors.js offers ObsidianError, which carries a typed `errorClass` and `details` — but
 * NO user-safe message field; its `message` is developer text ("Closure gate failed.",
 * "Invalid lifecycle transition: x -> y"). So the class is used, the message never is: the
 * class selects a plain sentence about what the failure means for the record, and the action's
 * `label` from config/action-ownership.config.js names what was being attempted. An untyped
 * error simply gets the neutral consequence.
 *
 * The raw text is NOT lost. auditAction() below still records `error: error.message`
 * verbatim, and System Health, the Operator HUD and the pending-write queue still show it.
 * Only what reaches the toast changes. */
const FAILURE_OUTCOME = Object.freeze({
  [ErrorClass.VALIDATION_ERROR]: 'Some of what was entered was not accepted, so nothing was changed.',
  [ErrorClass.AUTH_ERROR]: 'Your sign-in does not carry the rights this needs, so nothing was changed.',
  [ErrorClass.SCOPE_ERROR]: 'This record is outside what you are allowed to act on, so nothing was changed.',
  [ErrorClass.DIRECTORATE_SCOPE_ERROR]: 'This record belongs to another directorate, so nothing was changed.',
  [ErrorClass.OTP_REQUIRED]: 'A one-time code is needed before this can go ahead, so nothing was changed.',
  [ErrorClass.OTP_VERIFICATION_FAILED]: 'The one-time code was not accepted, so nothing was changed.',
  [ErrorClass.IDEMPOTENCY_CONFLICT]: 'The same request is already going through, so it was not sent twice.',
  [ErrorClass.FLOW_UNAVAILABLE]: 'The registry could not be reached, so nothing was changed. Try again shortly.',
  [ErrorClass.FLOW_CONTRACT_ERROR]: 'The registry did not accept it, so nothing was changed.',
  [ErrorClass.DISPATCH_FAILED]: 'It has not gone out, and the record still shows it as waiting to be sent.',
  [ErrorClass.ARCHIVE_FAILED]: 'Nothing was filed away and the reference is still open.',
  [ErrorClass.CLOSURE_GATE_FAILED]: 'Work on this reference is still open, so it cannot be closed yet.',
  [ErrorClass.NO_ORPHAN_VIOLATION]: 'It would leave a record with nothing to belong to, so nothing was changed.',
  [ErrorClass.QUARANTINED_RECORD]: 'This record is held for review and cannot be changed at the moment.',
  [ErrorClass.UNKNOWN_ERROR]: 'Nothing was changed.',
});
const DEFAULT_OUTCOME='Nothing was changed.';
const DEFAULT_LABEL='complete that step';
/** The plain noun phrase for an action, for use inside a sentence. Never a raw action id. */
export function actionLabel(action){ return actionSpec(action)?.label || DEFAULT_LABEL; }
/** What the operator reads when a governed action fails. Never derived from error.message. */
export function actionFailureMessage(action, error){
  return `Could not ${actionLabel(action)}. ${FAILURE_OUTCOME[error?.errorClass] || DEFAULT_OUTCOME}`;
}
export function assertModuleAction(moduleName, action){
  const spec=actionSpec(action); const boundary=boundaryFor(moduleName);
  if(!boundary) throw new Error(`Unknown module boundary: ${moduleName}`);
  if(spec && spec.owner && spec.owner!==moduleName){
    const invokers=Array.isArray(spec.allowedInvokers)?spec.allowedInvokers:[];
    if(!invokers.includes(moduleName)) throw new Error(`Action ${action} is owned by ${spec.owner}, not ${moduleName}`);
  }
  if(!spec && !ownsAction(moduleName, action)) throw new Error(`Action ${action} is not registered for ${moduleName}`);
  return {spec,boundary};
}
export function auditAction(moduleName, action, meta={}){
  const actor=getCurrentUser(State.get()) || State.get().profile || {};
  const spec=actionSpec(action) || {};
  const event=meta.event || spec.audit || `audit:${moduleName}:${action}`;
  return AuditLog.record({ref:meta.ref||'', actor, event, entityType:meta.entityType||'', entityId:meta.entityId||'', meta:{module:moduleName, action, owner:spec.owner||moduleName, service:spec.service||'', backend:spec.backend||'', ...(meta.meta||{})}});
}
export async function executeOwnedAction(moduleName, action, runner, meta={}){
  ensureCurrentUserActive(`${moduleName}:${action}`);
  assertModuleAction(moduleName, action);
  auditAction(moduleName, action, {ref:meta.ref, meta:{stage:'started', ...(meta.meta||{})}});
  try { const result=await runner(); auditAction(moduleName, action, {ref:meta.ref, meta:{stage:'completed'}}); return result; }
  catch(error){
    // The audit trail keeps the raw technical detail verbatim — IT reads this, and System
    // Health, the Operator HUD and the pending-write queue surface it. The operator does not.
    auditAction(moduleName, action, {ref:meta.ref, meta:{stage:'failed', error:error.message}});
    /* One failure, one toast. This layer speaks by default because it is the only place that
       sees every failed governed action; a call site that can say something genuinely more
       useful — naming the reference, the recovery it just took, what is still outstanding —
       passes `notify:false` and takes responsibility for telling the operator itself. The
       opt-out is explicit at the call site rather than a time-window de-duplication in the
       toast helper: a window would hide two messages racing, not stop them being sent. */
    if(meta.notify!==false) toast?.(actionFailureMessage(action, error),'error');
    throw error; // The rethrow contract: callers still decide what to do about the failure.
  }
}
export function boundaryNotice(moduleName){ const b=boundaryFor(moduleName); if(!b) return ''; return `<section class="panel boundary-note"><div class="eyebrow">Module Authority</div><p><b>${b.role}</b></p><p class="meta">Owns: ${(b.owns||[]).join(', ')}</p><p class="meta">Does not own: ${(b.mustNotOwn||[]).join(', ')}</p></section>`; }

import { State } from './state.js';
import { PlatformProvisioning } from '../config/platform-provisioning.config.js';
import { executeOwnedAction, auditAction } from './action-authority.js';
import { DispatchService } from './dispatch-service.js';
import { ArchiveService } from './archive.js';
import { OtpService } from './otp-service.js';
export const ActionRuntime = Object.freeze({canRun, run, actionsFor});
export function actionsFor(moduleName){ return PlatformProvisioning[moduleName]?.actions||[]; }
export function canRun(moduleName, action){ return actionsFor(moduleName).includes(action); }
/* `options.notify:false` is forwarded to executeOwnedAction so a caller routed through here
   can take responsibility for the operator-facing failure message, exactly as a caller that
   invokes executeOwnedAction directly can. Additive and presentation-only: the provisioning
   gate below, the ownership check, the audit stages and the rethrow are unchanged, and a
   caller that passes nothing behaves exactly as before. */
export async function run(moduleName, action, payload={}, options={}){
  if(!canRun(moduleName, action)) throw new Error(`Action ${action} is not enabled for ${moduleName}`);
  return executeOwnedAction(moduleName, action, async()=>{
    const s=State.get();
    switch(action){
      case 'send-dispatch': return DispatchService.dispatchOutbound({...payload, actor:s.profile});
      case 'archive-reference': return ArchiveService.archiveReference(payload.ref, s.profile, payload.meta||{});
      case 'request-otp': return OtpService.requestOtp({...payload, actor:s.profile});
      case 'verify-otp': return OtpService.verifyOtp({...payload, actor:s.profile});
      default: auditAction(moduleName, action, {ref:payload.ref||payload.referenceId||'', meta:{payloadKeys:Object.keys(payload)}}); return {ok:true, module:moduleName, action, payload};
    }
  }, {ref:payload.ref||payload.referenceId||'', notify:options.notify});
}

// Canvas Activities parity service.
//
// Ports the Canvas forensic Activities logic (filter/sort, FastTrack queue payload,
// Reference_ID formulas, DGO DIGITAL OPS update semantics and attachment preview) into the
// Obsidian runtime as a frozen, side-effect-free service in the style of core/archive.js and
// core/dispatch-service.js. The `now` seam is injectable so contracts can pin the clock.
//
// This module owns *logic only*. It performs no network I/O, no State mutation and no audit
// writes — modules/activities.js drives it through executeOwnedAction()/WriteManager so
// ownership, audit and idempotency governance stays where the platform already enforces it.
import { ActivityParityConfig, DefaultActivityFilters, lifecycleSpec } from '../config/activity-parity.config.js';
import { ActionOwnership } from '../config/action-ownership.config.js';
import { ActivityLifecycleOperations } from '../config/dynamic-actions.config.js';
import { EndpointContracts } from '../config/endpoints.config.js';
import { createValidationError } from './errors.js';

const text = v => String(v ?? '').trim();
const norm = v => text(v).toLowerCase();
const pad2 = n => String(n).padStart(2, '0');

// Canvas activities arrive either raw (SharePoint choice columns: {Value}) or already
// normalised by core/domain.js (flat lowercase keys). Both shapes must resolve identically.
const choice = v => (v && typeof v === 'object' && 'Value' in v ? v.Value : v);
export const activityStatus = a => text(choice(a?.Status) ?? a?.status);
export const activityAssignmentStatus = a => text(choice(a?.AssignmentStatus) ?? a?.assignmentStatus);
export const activityAssignedTo = a => text(a?.AssignedTo ?? a?.assignedTo);
export const activityCategory = a => text(a?.Category ?? a?.category);
export const activityTitle = a => text(a?.Title ?? a?.title);
export const activityCreated = a => text(a?.Created ?? a?.created);
export const activityId = a => text(a?.ID ?? a?.id);

// Canvas date filters compare calendar days in the operator's own timezone (Today() is
// local), so a bare YYYY-MM-DD boundary is resolved to local start/end of day rather than UTC.
function toTime(value, { endOfDay = false } = {}) {
  const raw = text(value);
  if (!raw) return null;
  const dateOnly = /^(\d{4})-(\d{2})-(\d{2})$/.exec(raw);
  const t = dateOnly
    ? new Date(+dateOnly[1], +dateOnly[2] - 1, +dateOnly[3], endOfDay ? 23 : 0, endOfDay ? 59 : 0, endOfDay ? 59 : 0, endOfDay ? 999 : 0).getTime()
    : new Date(raw).getTime();
  return Number.isNaN(t) ? null : t;
}

// Canvas: `Text(DateAdd(Today(),1), "yyyymmdd")` — the reference date is *tomorrow*.
function referenceDatePart(now) {
  const d = new Date(now.getTime());
  d.setDate(d.getDate() + 1);
  return `${d.getFullYear()}${pad2(d.getMonth() + 1)}${pad2(d.getDate())}`;
}

export function defaultFilters() { return { ...DefaultActivityFilters }; }

// Canvas gallery filter chain + `SortByColumns(..., "Created", Descending)`.
export function filterActivities(activities = [], filters = {}) {
  const f = { ...DefaultActivityFilters, ...(filters || {}) };
  const from = toTime(f.dateFrom);
  const to = toTime(f.dateTo, { endOfDay: true });
  const search = norm(f.search);
  return (Array.isArray(activities) ? activities : []).filter(a => {
    const status = activityStatus(a);
    if (f.statusTab === 'Treated' && norm(status) !== 'treated') return false;
    if (f.statusTab === 'Not Treated' && norm(status) === 'treated') return false;
    if (f.assignedTo && norm(activityAssignedTo(a)) !== norm(f.assignedTo)) return false;
    if (f.category && norm(activityCategory(a)) !== norm(f.category)) return false;
    if (f.status && norm(status) !== norm(f.status)) return false;
    if (f.assignmentStatus && norm(activityAssignmentStatus(a)) !== norm(f.assignmentStatus)) return false;
    if (from !== null || to !== null) {
      const created = toTime(activityCreated(a));
      if (created === null) return false;
      if (from !== null && created < from) return false;
      if (to !== null && created > to) return false;
    }
    // Canvas uses StartsWith(), not a substring search.
    if (search && !norm(activityTitle(a)).startsWith(search)) return false;
    return true;
  }).sort((a, b) => (toTime(activityCreated(b)) ?? 0) - (toTime(activityCreated(a)) ?? 0));
}

export function filterOptions(activities = []) {
  const uniq = fn => [...new Set((activities || []).map(fn).filter(Boolean))].sort((a, b) => a.localeCompare(b));
  return {
    assignedTo: uniq(activityAssignedTo),
    category: uniq(activityCategory),
    status: uniq(activityStatus),
    assignmentStatus: uniq(activityAssignmentStatus)
  };
}

// Ported legacy `isSafeUrl` guard, carried over from the pre-R11 single-file app
// (`NITDA_Digital_Ops_Hub_patched.html`, catalogued in the retired
// dgo-ported-legacy-logic/v1 inventory): only absolute http(s) targets may reach an href
// or a preview frame — this blocks javascript:, data:, vbscript: and blob: payloads
// carried on attachment metadata.
export function isSafeUrl(value) {
  const raw = text(value);
  if (!raw) return false;
  try { return ActivityParityConfig.allowedAttachmentProtocols.includes(new URL(raw).protocol); }
  catch { return false; }
}

export function safeUrl(value) { return isSafeUrl(value) ? text(value) : ''; }

export function getAttachments(activity) {
  const list = activity?.Attachments ?? activity?.attachments;
  if (!Array.isArray(list)) return [];
  return list.map((att, index) => {
    const name = text(att?.Name ?? att?.name ?? att?.FileName) || `Attachment ${index + 1}`;
    return { id: text(att?.ID ?? att?.id) || String(index), name, url: safeUrl(att?.AbsoluteUri ?? att?.url ?? att?.Link), contentType: text(att?.ContentType ?? att?.contentType) };
  });
}

// Canvas attachment preview: PDF renders inline, everything else gets an explicit fallback.
export function getAttachmentPreviewModel(attachment) {
  if (!attachment) return null;
  const name = text(attachment.name ?? attachment.Name);
  const url = safeUrl(attachment.url ?? attachment.AbsoluteUri);
  const contentType = text(attachment.contentType ?? attachment.ContentType);
  const isPdf = /\.pdf$/i.test(name) || /pdf/i.test(contentType);
  const previewable = isPdf && !!url;
  return {
    name,
    url,
    isPdf,
    previewable,
    fallbackMessage: !url
      ? 'Preview blocked: this attachment has no safe http(s) location.'
      : isPdf ? '' : 'Preview not available for this file type. Download the attachment to open it.'
  };
}

// Canvas Patch() into the DGOFASTTRACK queue.
export function buildQueuePayload(type, activity, { now = () => new Date() } = {}) {
  const spec = lifecycleSpec(type);
  if (!spec) throw createValidationError(`Unsupported activity lifecycle action: ${type}`, { type });
  if (!activity) throw createValidationError('A selected activity is required.', { type });
  const today = now().toISOString();
  const sourceId = activityId(activity);
  return {
    Title: activityTitle(activity),
    'Activity Tracking ID': text(activity.RefIDD ?? activity.referenceId),
    StartDate: today,
    AttachmentLink: text(activity.AttachmentLink ?? activity.attachmentLink),
    AssignedBy: ActivityParityConfig.queueAssignedBy,
    RefIDD: sourceId,
    AssignedTo: ActivityParityConfig.queueAssignedTo,
    RefIDDN: Number(sourceId) || sourceId,
    Status: ActivityParityConfig.queueStatus,
    Priority: ActivityParityConfig.queuePriority,
    'Acknowledgement Due Date': today,
    DueDate: today,
    NVERSE: ActivityParityConfig.queueTag,
    Category: spec.category
  };
}

// Canvas: yyyymmdd(Today()+1) - <activity ID> - <suffix> - <queue record ID>.
export function buildReferenceId(type, activity, queueRecordId, { now = () => new Date() } = {}) {
  const spec = lifecycleSpec(type);
  if (!spec) throw createValidationError(`Unsupported activity lifecycle action: ${type}`, { type });
  return `${referenceDatePart(now())}-${activityId(activity)}-${spec.suffix}-${text(queueRecordId)}`;
}

// Canvas DGO DIGITAL OPS update: Status=Treated, AssignmentStatus=Assigned, and AssignedTo /
// Category copied from the queue (patch) record.
export function buildDgoPatch(queueRecord, activity = {}) {
  const { status, assignmentStatus } = ActivityParityConfig.dgoUpdate;
  return {
    status,
    assignmentStatus,
    assignedTo: queueRecord.AssignedTo,
