async function bootAnim(){ const ring=$('[data-ring]'), prog=$('[data-progress]'), steps=$('[data-steps]'), tip=$('[data-tip]'); const r=78, c=2*Math.PI*r; ring.setAttribute('stroke-dasharray',String(c)); let start=performance.now(), lastStep=-1, tipIdx=0; while(model.phase==='boot'){ const elapsed=performance.now()-start, pct=Math.min(100,Math.round(elapsed/C.bootDurationMs*100)); ring.setAttribute('stroke-dashoffset',String(c*(1-pct/100))); prog.textContent=pct+'%'; const step=Math.min(C.bootSteps.length-1,Math.floor(pct/100*C.bootSteps.length)); if(step!==lastStep){ lastStep=step; announce(C.bootSteps[step]||''); const done=C.bootSteps.slice(Math.max(0,step-3),step).map(s=>`<div class="wel-step"><span class="wel-check">✓</span><span>${esc(s)}</span></div>`).join(''); steps.innerHTML=done+`<div class="wel-step"><span style="animation:welSpin .9s linear infinite;display:inline-block">◌</span><b>${esc(C.bootSteps[step]||C.bootSteps.at(-1))}</b></div>`; }
 if(Math.floor(elapsed/2600)!==tipIdx){ tipIdx=Math.floor(elapsed/2600); tip.textContent=C.tips[tipIdx%C.tips.length]; }
 if(pct>=100) break; await sleep(80); } if(model.phase==='boot'){ await sleep(450); setPhase('login'); } }
setChannel(model.channel); trap=createFocusTrap(root,{ initialFocus:()=>activeLayer().querySelector('input:not([disabled]),button:not([disabled]),select:not([disabled])'), restoreFocusTo:opener, onEscape:()=>{ cleanup(); finish('skip'); } }); bootAnim(); }); }

import { State } from './state.js';
