function slaCompliance(tasks) { const withDue = tasks.filter(t => t.ack); if (!withDue.length) return null; const onTime = withDue.filter(t => t.acknowledged && (!t.ackedAt || new Date(t.ackedAt).getTime() <= new Date(t.ack + 'T23:59:59').getTime())); return Math.round((onTime.length / withDue.length) * 100); }
function ageDays(t) { const from = t.created || t.start || t.createdAt; if (!from) return null; return Math.max(0, Math.floor((Date.now() - new Date(from).getTime()) / 86400000)); }
function downloadText(filename, text, type='application/json'){ const blob=new Blob([text],{type}); const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=filename; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),1000); }
function copyText(text,label='Text'){ navigator.clipboard?.writeText(text).then(()=>toast(label+' copied','success')).catch(()=>downloadText(label.replace(/\s+/g,'-').toLowerCase()+'.txt',text,'text/plain')); }
