import { hydrateGovernance, actor, executeOwnedAction } from '../core/governed-actions.js';
import { head, kpis, esc, badge, toast, emptyFor, loadFlags, confirmAction, actionPreview,refCode} from '../core/ui.js';
import { UIState } from '../core/ui-state.js';
import { Entities } from '../core/entity-store.js';
import { ArchiveService } from '../core/archive.js';
import { State } from '../core/state.js';
import { filterItemsBySource, sourceFilterChips, sourceBadge } from '../core/source-views.js';
export async function mount(el){hydrateGovernance();render(el);}
function currentActor(){ return State.get().profile || actor(); }
function rows(){ const s=Entities.snapshot(); return (s.byRef||[]).map(([ref,b])=>({ref,open:Entities.canClose(ref),archived:!!Entities.getArchive(ref)})); }
/* I-21 — the tile band holds counts only. Whether a reference can be closed is a state, not a
   measure, so it stays in the table's own column where it can carry a pill and a reason.
   I-13 — "No references in this queue." stated a fact and stopped: the queue selector and the
   source chips are both filters, so an operator could not tell a filtered-out list from a
   platform that had closed everything, or from one that had never reached the registry.
   I-07 — "Immutable reference bundles, audit threads, retention evidence and reopen controls"
   and "Archive owns immutable closure evidence" describe the module to itself. I-02 — the
   screen that finds records is called "Lookup & Direct Action" in the sidebar, not "Lookup". */
function render(el){
  const stats=Entities.stats();
  const u=UIState.get('archive',{queue:'All',source:'all'});
  const allRows=rows();
  const sourceRows=filterItemsBySource(allRows,u.source||'all');
  const list=sourceRows.filter(r=>u.queue==='All'||(u.queue==='Ready'&&r.open.ok&&!r.archived)||(u.queue==='Blocked'&&!r.open.ok&&!r.archived)||(u.queue==='Archived'&&r.archived));
  const filtered=(u.queue&&u.queue!=='All')||(u.source&&u.source!=='all');
  const readyToClose=sourceRows.filter(r=>r.open.ok&&!r.archived).length;
  const table=list.length
    ? `<div class="tablewrap dgo-table-wrap"><table class="dgo-table"><thead><tr><th>Reference</th><th>Ready to close</th><th>Archived</th><th>Actions</th></tr></thead><tbody>${list.map(r=>`<tr><td>${sourceBadge(r)} ${refCode(r.ref)}</td><td>${badge(r.open.ok?'Ready':'Blocked',r.open.ok?'ok':'warn')}</td><td>${badge(r.archived?'Archived':'Active',r.archived?'ok':'')}</td><td><button class="btn ghost compact" data-ref="${esc(r.ref)}">Inspect</button></td></tr>`).join('')}</tbody></table></div>`
    : emptyFor({filtered,...loadFlags(State.get().runtime),noun:'references',clearAttr:'data-clear-filters'});
  el.innerHTML=`<div class="workspace">${head('Archive Evidence','Close a reference for good and keep the evidence of how it was closed.')}${kpis([['Archived',stats.archives],['References',sourceRows.length],['Quarantine',stats.quarantine],['Ready to close',readyToClose]])}${sourceFilterChips(u.source||'all','data-source-view',allRows)}<div class="toolbar"><span class="meta">Closing a reference here is final: its records and their history are kept as evidence and can no longer be edited. To find a record, use Lookup &amp; Direct Action.</span><select data-queue aria-label="Show references by closure readiness">${['All','Ready','Blocked','Archived'].map(x=>`<option ${x===u.queue?'selected':''}>${x}</option>`).join('')}</select><button class="btn ghost" data-refresh>Refresh</button></div><div class="split"><section class="panel"><div class="eyebrow panel-eyebrow">Archive a reference</div><form id="archive-form" class="grid"><label>Reference<input name="ref" required placeholder="REF-..." /></label><label class="wide">Why it is being closed<textarea name="summary" rows="3">Closed and ready for archive.</textarea></label><div class="wide"><button class="btn" data-archive>Archive this reference</button></div></form></section><section class="panel detail-col"><div class="eyebrow panel-eyebrow">References and whether they can be closed</div>${table}</section></div></div>`;
  el.querySelectorAll('[data-source-view]').forEach(b=>b.onclick=()=>{UIState.set('archive',{source:b.dataset.sourceView});render(el);});
  el.querySelector('[data-queue]').onchange=e=>{UIState.set('archive',{queue:e.target.value});render(el);};
  /* Archiving was the one consequential mutation on the platform with no confirmation step.
     "Inspect" fills the reference into this form, so closing a record for good was two clicks
     with nothing in between — and reopenArchive() does not undo it: it mints a *new* derived
     reference and leaves the original archived permanently. The dialog names the record, says
     the closure is permanent, and says plainly what reopening does and does not do. */
  el.querySelector('#archive-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));
    if(!await confirmAction({title:'Close this reference for good',body:`<p><b>${esc(d.ref)}</b></p><p>Archiving is permanent. Once closed, this reference and its records are kept as evidence and can no longer be edited.</p><p>Reopening later does not restore this reference — it creates a new one derived from it. This one stays archived.</p>${actionPreview({reference:d.ref,closureReason:d.summary},{payload:false})}`})) return;
    /* `notify:false` — this screen can say more than the governance layer can. The closure
       gate refuses for two different reasons and the operator's next move differs completely:
       a reference the register does not hold is a typing mistake, while a reference with open
       work is a queue to go and clear. ArchiveService throws a typed closure error carrying
       that reason, so name it, and name the reference. The raw text stays in the audit trail. */
    try{await executeOwnedAction('archive','archive-reference',()=>ArchiveService.archiveReference(d.ref,currentActor(),{closureSummary:d.summary}),{ref:d.ref,notify:false});toast(`${d.ref} is closed and its evidence is kept`,'success');render(el);}
    catch(err){toast(err?.details?.reason==='UNKNOWN_REFERENCE'
      ? `${d.ref} is not in the register, so there is nothing to close. Check the reference and try again.`
      : `${d.ref} cannot be closed yet — work on it is still open. The checks above show what is outstanding. Nothing was changed.`,'error');}};
  el.querySelector('[data-refresh]').onclick=()=>render(el);
  /* The arms of the I-13 contract, wired: clear the filters back to every reference, or ask
     the registry again. Without these the buttons emptyFor() renders would be decoration. */
  el.querySelectorAll('[data-clear-filters]').forEach(b=>b.onclick=()=>{UIState.set('archive',{queue:'All',source:'all'});render(el);});
  el.querySelectorAll('[data-retry-load]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const {requestSync}=await import('../core/data-loader.js');await requestSync({source:'archive',mode:'refresh'});toast('References reloaded from the registry','success');}catch{toast('The registry could not be reached — nothing was reloaded','error');}finally{b.disabled=false;}render(el);});
  el.querySelectorAll('[data-ref]').forEach(b=>b.onclick=()=>{const f=el.querySelector('#archive-form');f.ref.value=b.dataset.ref;f.ref.focus();});
}
export async function archiveReference(ref, closureSummary='Closed and ready for archive'){ return ArchiveService.archiveReference(ref,currentActor(),{closureSummary}); }

import { hydrateGovernance, executeOwnedAction } from '../core/governed-actions.js';
import { QueryStore } from '../core/query-store.js';
import { head, esc, confirmAction, toast, actionPreview } from '../core/ui.js';
import { invokeData } from '../core/api.js';
import { SupportService } from '../core/support-service.js';
import { SupportRoutingConfig } from '../config/support-routing.config.js';
let messages = [], sending = false;
export async function mount(el){hydrateGovernance();render(el); }
/* I-07 — this panel used to describe itself in the platform's own terms ("captures current
   route, selected reference, last error, pending writes and recent receipts for support
   triage") and then showed the operator a raw JSON dump. It now says, in the operator's
   words, what the support team will be able to see, and shows that as a readable list with
   the technical detail folded away behind actionPreview()'s disclosure. */
function supportPanel(){ const ctx=SupportService.buildContext(); return `<section class="panel"><h2>Ask the support team</h2><p class="meta">Your message goes to the support team together with the screen you are on, the record you have open, and anything that has recently failed — so they see what you see without you having to describe it.</p><div class="form-row"><select id="support-category" aria-label="What kind of help you need">${SupportRoutingConfig.categories.map(c=>`<option value="${c.id}">${c.label}</option>`).join('')}</select><input id="support-ref" placeholder="Reference or task number this is about" value="${esc(ctx.selectedId||'')}"></div><textarea id="support-message" rows="3" placeholder="Describe what you need — a reassignment, a date that looks wrong, something that will not save…"></textarea><div class="toolbar"><button class="btn" id="support-submit">Send support request</button></div><details><summary>What is sent with your request</summary>${actionPreview(ctx)}</details></section>`; }
function render(el) {
  /* I-13 — "Ask a question to get started." was a hint, not an empty state. A conversation has
     only one way of being empty (nothing has been asked in this session — it is not filtered
     and it is not a failed load), so this is the single-arm form of the contract: it names the
     cause, says where answers will appear, and carries one action that puts the cursor in the
     box. It is written out rather than taken from emptyFor() because emptyFor()'s nouns are
     records in a registry and these are questions in a session. */
  const emptyThread = `<div class="empty dgo-empty"><h2 class="dgo-empty__title">No questions asked yet</h2><p>Nothing has been asked in this session. Your questions and the answers appear here as a conversation.</p><p><button type="button" class="btn" data-ask-first>Ask a question</button></p></div>`;
  el.innerHTML = `<div class="workspace">${head('Assistant', 'Ask about correspondence, tasks and where work has got to. Only records you are allowed to see are used.')}
    <div class="panel"><div class="thread" id="asst-log">${messages.length ? messages.map(m => `<div class="msg ${m.role === 'user' ? 'mine' : ''}"><span class="who">${m.role === 'user' ? 'You' : 'Assistant'}</span>${esc(m.content)}</div>`).join('') : emptyThread}</div>
      <div class="form-row"><textarea id="asst-input" class="flex-1" rows="2" placeholder="Ask the assistant… (Ctrl+Enter to send)"></textarea>
      <button class="btn" id="asst-send" ${sending ? 'disabled' : ''}>${sending ? 'Sending…' : 'Send'}</button></div></div>${supportPanel()}</div>`;
  const input = el.querySelector('#asst-input'), send = el.querySelector('#asst-send');
  send.onclick = () => submit(el);
  el.querySelector('[data-ask-first]')?.addEventListener('click', () => el.querySelector('#asst-input')?.focus());
  el.querySelector('#support-submit')?.addEventListener('click', async()=>{ const category=el.querySelector('#support-category')?.value||'clarification'; const ref=el.querySelector('#support-ref')?.value||''; const message=el.querySelector('#support-message')?.value||''; if(!message.trim()) return toast('Write what you need help with first','error'); const catLabel=SupportRoutingConfig.categories.find(c=>c.id===category)?.label||category; if(!await confirmAction({title:'Send this to the support team', body:`<p>${esc(message)}</p><p class="meta">It goes to support as a ${esc(catLabel)} request${ref?`, about ${esc(ref)}`:''}. Nothing on this screen changes, and no record is updated — someone will come back to you.</p>`, confirmText:'Send request', cancelText:'Cancel'})) return; try{ await SupportService.submit({category,message,ref,taskId:ref}); toast('Support request sent','success'); }catch(e){ toast('Your support request could not be sent — try again in a moment','error'); } });
  input.onkeydown = e => { if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); submit(el); } };
  el.querySelector('#asst-log').scrollTop = el.querySelector('#asst-log').scrollHeight;
}
async function submit(el) {
  if (sending) return; const input = el.querySelector('#asst-input'); const text = (input.value || '').trim(); if (!text) return;
  /* I-07 — "This is sent to the AI_CHAT flow endpoint." named a service the operator has no
     relationship with. The dialog is where they decide, so it now says what leaves the screen
     and what it cannot reach. */
  if (!await confirmAction({ title: 'Send this question to the assistant', body: `<p>${esc(text)}</p><p class="meta">Your question is sent with a summary of the records you are allowed to see. Records you cannot open are not included, and nothing is changed by asking.</p>`, confirmText: 'Send question', cancelText: 'Cancel' })) return;
  messages.push({ role: 'user', content: text }); sending = true; render(el);
  try {
    const context = await QueryStore.dashboard().catch(()=>null);
    /* `notify:false` — this is the screen where the defect was reproduced: an unconfigured
       connection made the governance layer toast "AI_CHAT: Endpoint AI_CHAT is not
       configured" on top of the answer-line message below, twice over. The catch already
       writes the failure into the conversation, where the operator is looking, and points at
       the one screen that can explain it. Governance stays quiet so that is the only word. */
    const res = await executeOwnedAction('assistant','ask',()=>invokeData('AI_CHAT', { messages, scoped:true, context }),{notify:false, meta:{promptLength:text.length}});
    messages.push({ role: 'assistant', content: res?.reply || res?.message || (typeof res==='string'?res:'The assistant came back with no answer. Try asking in a different way.') });
    toast('Answer received','success');
    /* I-02 — the screen to check is named "System Health" in the sidebar, not "Diagnostics". */
  } catch (error) { messages.push({ role: 'assistant', content: 'The assistant could not answer just now, so nothing was returned. Try again — if it keeps failing, System Health shows whether the platform can reach its data.' }); toast('The assistant could not answer','error'); }
  sending = false; render(el);
}

// Briefs & Submissions — ported from the ECM Activity Hub under decision D6(b).
//
// An executive briefing pack: drafted by an officer, submitted for decision, approved or
// rejected. The lifecycle guard lives in core/executive-register.js so it is testable
// without a browser; this module is the workspace over it.
//
// The decide action is offered only on a SUBMITTED brief, and the underlying service refuses
// an illegal transition regardless — the Activity Hub applied any decision to any record, so
// a rejected brief could be re-decided and a draft approved without ever being submitted.

import { hydrateGovernance, executeOwnedAction } from '../core/governed-actions.js';
import { State } from '../core/state.js';
import { emptyFor, loadFlags, head, kpis, esc, badge, toast, confirmAction, fmtDateTime, mdBack, mdSwitch, resetDetailScroll } from '../core/ui.js';
import { requestSync } from '../core/data-loader.js';
import { UIState, pageSlice, pager } from '../core/ui-state.js';
import { audit } from '../core/enterprise-domain.js';
import { invoke } from '../core/api.js';
import { debouncedInput } from '../core/ui-interactions.js';
import { Briefs, BriefStates } from '../core/executive-register.js';

const THEMES = ['Digital Public Infrastructure', 'Cybersecurity', 'Innovation',
                'Capacity Building', 'Regulatory'];

export async function mount(el) { hydrateGovernance(); render(el); }

function render(el) {
  const s = State.get();
  const u = UIState.get('briefs', { q: '', status: 'All', page: 1, size: 20, selected: null, md: 'list', creating: false, deciding: '' });
  const all = s.briefs || [];
  const rows = all
    .filter(b => u.status === 'All' || b.status === u.status)
    .filter(b => !u.q || [b.title, b.theme, b.summary, b.raisedBy].some(v => String(v || '').toLowerCase().includes(u.q.toLowerCase())));
  const p = pageSlice(rows, u.page, u.size);
  const sel = all.find(b => b.id === u.selected);

  el.innerHTML = `<div class="workspace">
    ${head('Briefs & Submissions', 'Brief packs for decisions and ministerial submissions. Drafted, submitted, then approved or rejected.')}
    ${kpis([
      ['Total', all.length],
      ['Draft', all.filter(b => b.status === 'Draft').length],
      ['Awaiting decision', all.filter(b => b.status === 'Submitted').length],
      ['Approved', all.filter(b => b.status === 'Approved').length],
    ])}
    <div class="toolbar">
      <input data-q value="${esc(u.q)}" placeholder="Search title, theme, summary or author">
      <select data-status><option>All</option>${BriefStates.map(x => `<option>${esc(x)}</option>`).join('')}</select>
      <button class="btn" data-new>New brief</button>
    </div>
    ${u.creating ? createForm() : ''}
    <div class="split" ${mdSwitch(sel ? u.md : 'list')}>
      <div><div class="list-col">${p.rows.map(b => `
        <article class="list-item ${b.id === sel?.id ? 'active' : ''}" data-select="${esc(b.id)}">
          <div>${badge(b.status)}</div>
          <h4>${esc(b.title)}</h4>
          <div class="meta">${esc(b.theme || 'No theme')} · ${esc(b.raisedBy || 'Unattributed')}</div>
        </article>`).join('') || emptyFor({ filtered: !!(u.q || u.status !== 'All'), ...loadFlags(s.runtime), noun: 'briefs', createLabel: 'New brief', createAttr: 'data-new-brief' })}</div>${pager(p)}</div>
      <div class="detail-col panel-stack">${sel ? detail(sel, u) : '<section class="panel"><div class="empty dgo-empty"><h2 class="dgo-empty__title">No brief selected</h2><p>Choose a brief from the list to read it, submit it for decision, or record a decision on it.</p></div></section>'}</div>
    </div>
  </div>`;

  bind(el, s, u, all, sel);
}

function createForm() {
  return `<section class="panel"><form class="grid" data-create-form>
    <h3 class="wide">New brief</h3>
    <label class="wide">Title *<input name="title" required placeholder="What the brief is about"></label>
    <label>Theme<select name="theme">${THEMES.map(t => `<option>${esc(t)}</option>`).join('')}</select></label>
    <label class="wide">Summary<textarea name="summary" rows="3" placeholder="The decision being asked for, in a sentence or two."></textarea></label>
    <label class="wide">Background<textarea name="background" rows="3"></textarea></label>
    <label class="wide">Options considered<textarea name="options" rows="3"></textarea></label>
    <label class="wide">Risks<textarea name="risks" rows="2"></textarea></label>
    <label class="wide">Recommendation<textarea name="recommendation" rows="2"></textarea></label>
    <div class="wide form-row"><button class="btn">Save as draft</button><button type="button" class="btn ghost" data-cancel>Cancel</button></div>
  </form></section>`;
}

function detail(b, u) {
  const next = Briefs.nextStates(b);
  const field = (label, value) => value
    ? `<div class="dgo-stack dgo-stack--2"><span class="eyebrow">${label}</span><p>${esc(value)}</p></div>` : '';
  return `${mdBack('Back to briefs')}
  <section class="panel">
    <div class="eyebrow panel-eyebrow">Brief</div>
    <div class="status-strip">${badge(b.status)}${b.theme ? badge(b.theme) : ''}</div>
    <h2>${esc(b.title)}</h2>
    <dl class="detail-grid">
      <dt>Raised by</dt><dd>${esc(b.raisedBy || '—')}</dd>
      <dt>Created</dt><dd>${esc(fmtDateTime(b.createdAt))}</dd>
      ${b.submittedAt ? `<dt>Submitted</dt><dd>${esc(fmtDateTime(b.submittedAt))} by ${esc(b.submittedBy || '—')}</dd>` : ''}
      ${b.decidedAt ? `<dt>Decided</dt><dd>${esc(fmtDateTime(b.decidedAt))} by ${esc(b.decidedBy || '—')}</dd>` : ''}
    </dl>
    <div class="form-row">
      ${next.includes('Submitted') ? '<button type="button" class="btn" data-to="Submitted">Submit for decision</button>' : ''}
      ${next.includes('Approved') ? '<button type="button" class="btn" data-to="Approved">Approve</button>' : ''}
      ${next.includes('Rejected') ? '<button type="button" class="btn ghost" data-to="Rejected" style="color:var(--dgo-color-action-danger)">Reject</button>' : ''}
      ${next.length ? '' : '<p class="meta">This brief is closed. No further decision is possible.</p>'}
    </div>
  </section>
  ${u.deciding ? `<section class="panel"><form class="grid" data-decide-form>
    <h3 class="wide">${u.deciding === 'Approved' ? 'Approve' : 'Reject'} this brief</h3>
    <label class="wide">Decision note<textarea name="comments" rows="3" placeholder="What was decided, and why."></textarea></label>
    <div class="wide form-row"><button class="btn">Record decision</button><button type="button" class="btn ghost" data-decide-cancel>Cancel</button></div>
  </form></section>` : ''}
  <section class="panel">
    ${field('Summary', b.summary)}${field('Background', b.background)}
    ${field('Options considered', b.options)}${field('Risks', b.risks)}
    ${field('Recommendation', b.recommendation)}
    ${b.decisionComments ? field('Decision note', b.decisionComments) : ''}
  </section>`;
}

function bind(el, s, u, all, sel) {
  const st = el.querySelector('[data-status]'); if (st) { st.value = u.status; st.onchange = e => { UIState.set('briefs', { status: e.target.value, page: 1 }); render(el); }; }
  debouncedInput(el.querySelector('[data-q]'), v => { UIState.set('briefs', { q: v, page: 1 }); render(el); }, { refind: () => el.querySelector('[data-q]') });
  el.querySelectorAll('[data-select]').forEach(x => x.onclick = () => { UIState.set('briefs', { selected: x.dataset.select, md: 'detail' }); render(el); resetDetailScroll(el); });
  el.querySelector('[data-md-back]')?.addEventListener('click', () => { UIState.set('briefs', { md: 'list' }); render(el); });
  el.querySelectorAll('[data-page]').forEach(x => x.onclick = () => { UIState.set('briefs', { page: +x.dataset.page }); render(el); });
  el.querySelectorAll('[data-new],[data-new-brief]').forEach(b => b.addEventListener('click', () => { UIState.set('briefs', { creating: true }); render(el); }));
  el.querySelector('[data-cancel]')?.addEventListener('click', () => { UIState.set('briefs', { creating: false }); render(el); });
  /* I-13 — the list used to fall back to "No briefs in this queue.", a bare fact that reads the
     same whether the queue is clear, the filters exclude everything, or nothing ever loaded.
     emptyFor() separates the three; these are the handlers that make each one's action real.
     The old call passed `failed: !!runtime.lastError`, which core/data-loader.js never sets —
     it records a failed load on lastLoad.ok === false — so the "could not load" arm could not
     be reached. loadFlags() reads the flag that is actually written. */
  el.querySelectorAll('[data-clear-filters]').forEach(b => b.addEventListener('click', () => { UIState.set('briefs', { q: '', status: 'All', page: 1 }); render(el); }));
  el.querySelectorAll('[data-retry-load]').forEach(b => b.addEventListener('click', async () => {
    b.disabled = true;
    try { await requestSync({ source: 'briefs', mode: 'refresh' }); toast('Briefs reloaded from the registry', 'success'); }
    catch { toast('The registry could not be reached — nothing was reloaded', 'error'); }
    finally { b.disabled = false; }
    render(el);
  }));

  el.querySelector('[data-create-form]')?.addEventListener('submit', async e => {
    e.preventDefault();
    const d = Object.fromEntries(new FormData(e.target));
    let brief;
    try { brief = Briefs.create(d, s.profile.email); }
    catch (err) { return toast(err.reason === 'missing_title' ? 'A brief needs a title' : err.message, 'error'); }
    if (!await confirmAction({ title: 'Save this brief as a draft', body: `<p>${esc(brief.title)}</p>` })) return;

    await executeOwnedAction('briefs', 'create-brief', () => {
      State.patch({
        briefs: [brief, ...all],
        audit: [audit('Brief Created', 'brief', brief.id, { title: brief.title }, s.profile.email), ...s.audit],
      }, { module: 'briefs', action: 'briefs:create', ref: brief.id });
      invoke('DYNAMIC_ACTIONS', { action: 'upsert_record', module: 'DGCEO_Briefs', data: brief })
        .catch(() => toast('Saved locally; synchronization queued', 'error'));
    }, { ref: brief.id });

    UIState.set('briefs', { creating: false, selected: brief.id, md: 'detail' });
    toast('Brief saved as a draft', 'success');
    render(el);
  });

  el.querySelectorAll('[data-to]').forEach(b => b.onclick = () => {
    // Submitting needs no note; a decision does, so it opens the inline form instead.
    if (b.dataset.to === 'Submitted') return apply(el, s, all, sel, 'Submitted', '');
    UIState.set('briefs', { deciding: b.dataset.to });
    render(el);
  });
  el.querySelector('[data-decide-cancel]')?.addEventListener('click', () => { UIState.set('briefs', { deciding: '' }); render(el); });
  el.querySelector('[data-decide-form]')?.addEventListener('submit', e => {
    e.preventDefault();
    const d = Object.fromEntries(new FormData(e.target));
    apply(el, s, all, sel, u.deciding, d.comments || '');
  });
}

async function apply(el, s, all, sel, to, comments) {
  const label = to === 'Submitted' ? 'Submit this brief for decision'
              : `${to === 'Approved' ? 'Approve' : 'Reject'} this brief`;
  if (!await confirmAction({
    title: label,
    body: `<p>${esc(sel.title)}</p>` + (to === 'Submitted'
      ? '<p class="meta">It moves to the decision queue and can no longer be edited.</p>'
      : (comments ? `<p class="meta">${esc(comments)}</p>` : '<p class="meta">No decision note was given.</p>')),
  })) return;

  let next;
  try {
    next = Briefs.transition(sel, to, { comments, by: s.profile.email });
  } catch (err) {
    // The service is the authority on what is legal, not the buttons this page rendered.
    return toast(err.reason === 'illegal_transition'
      ? 'That is not a legal step for this brief' : err.message, 'error');
  }

  await executeOwnedAction('briefs', to === 'Submitted' ? 'submit-brief' : 'decide-brief', () => {
    State.patch({
      briefs: all.map(b => b.id === sel.id ? next : b),
      audit: [audit(`Brief ${to}`, 'brief', sel.id, { from: sel.status, to }, s.profile.email), ...s.audit],
    }, { module: 'briefs', action: `briefs:${to.toLowerCase()}`, ref: sel.id });
    invoke('DYNAMIC_ACTIONS', { action: 'transition_status', module: 'DGCEO_Briefs', ref: sel.id, status: to })
      .catch(() => toast('Recorded locally; synchronization queued', 'error'));
  }, { ref: sel.id });

  UIState.set('briefs', { deciding: '' });
  toast(`Brief ${to.toLowerCase()}`, 'success');
  render(el);
}

import { hydrateGovernance, executeOwnedAction } from '../core/governed-actions.js';
import { State } from '../core/state.js';import { AppConfig } from '../config/app.config.js';import { head,toast,confirmAction,esc,focusField,assignmentErrors,assignmentErrorField } from '../core/ui.js';import { invoke } from '../core/api.js';
import { UIState } from '../core/ui-state.js';import { ActionRuntime } from '../core/action-runtime.js';import { priorityOptions } from '../config/priority.config.js';
