function render(el){const s=State.get();const raw=Number(s.settings?.maxBulkAssign);const cap=Number.isInteger(raw)&&raw>0?raw:AppConfig.maxBulkAssign;const u=UIState.get('bulk-assignment',{otp:null,draft:null});let draft=AssignmentCascade.cascade({draft:u.draft||{},state:s});const cats=AssignmentCascade.categories(s), subs=AssignmentCascade.subcategories(draft.category,s), deps=AssignmentCascade.departments(s);el.innerHTML=`<div class="workspace">${head('Bulk Assignment','Give many records to the same officer at once, with one instruction and one set of dates.')}<section class="panel"><div class="eyebrow panel-eyebrow">Assign many records at once</div><p class="meta">Everything you set below is applied to every record you list. Choosing a category, subcategory or DSU fills in the assignee, dates and priority for you — change anything you need to. You will see a summary to check before anything is applied. Batches of more than ${OTP_THRESHOLD} records need a one-time code sent to your registered contact.</p><div class="form-row"><a class="btn ghost" href="#/single-assignment">Assignment Desk</a><a class="btn ghost" href="#/activities">Activities</a></div></section><form class="panel grid"><label class="wide">Activity IDs<textarea name="ids" rows="4" required placeholder="Paste IDs separated by comma, space or new line">${esc(u.draft?.ids||'')}</textarea><small class="meta">Required — one or more IDs of records already in the register, separated by commas, spaces or new lines. Every record you list gets the same assignment.</small></label><label>Category<select name="category" required><option value="">Select category</option>${cats.map(x=>`<option value="${esc(x.category)}" ${x.category===draft.category?'selected':''}>${esc(x.category)}</option>`).join('')}</select></label><label>Subcategory<select name="subcategory"><option value="">Select subcategory</option>${subs.map(x=>`<option value="${esc(x.subcategory)}" ${x.subcategory===draft.subcategory?'selected':''}>${esc(x.subcategory)}</option>`).join('')}</select></label><label>Category code<input name="categoryCode" value="${esc(draft.categoryCode||'')}"></label><label>Subcategory code<input name="subcategoryCode" value="${esc(draft.subcategoryCode||'')}"></label><label>Primary DSU<select name="dsu"><option value="">Select DSU</option>${deps.map(d=>`<option value="${esc(d.dsuKey)}" ${d.dsuKey===draft.dsu?'selected':''}>${esc(d.title||d.dsuKey)}</option>`).join('')}</select></label><label>Support DSU<select name="supportDsu"><option value="">Select support DSU</option>${deps.map(d=>`<option value="${esc(d.dsuKey)}" ${d.dsuKey===draft.supportDsu?'selected':''}>${esc(d.title||d.dsuKey)}</option>`).join('')}</select></label><label>Assigned To<input name="assignedTo" type="email" value="${esc(draft.assignedTo||'')}"><small class="meta">The officer’s email address — this is who receives every task in the batch.</small></label><label>Supporting Assignee<input name="supportingAssignee" type="email" value="${esc(draft.supportingAssignee||'')}"></label><label class="wide">CC recipients<input name="copy" type="text" value="${esc(draft.copy||'')}" placeholder="email1; email2"><small class="meta">Optional — everyone listed is copied on every assignment notice in this batch.</small></label><label>Start date<input name="startDate" type="date" value="${esc(draft.startDate||'')}"></label><label>Ack due<input name="ack" type="date" value="${esc(draft.ack||'')}"></label><label>Due date<input name="due" type="date" value="${esc(draft.due||'')}"></label><label>Priority<select name="priority">${priorityOptions(draft.priority||'normal')}</select></label><label>Maximum records per bulk assignment<input value="${esc(cap)}" readonly><small class="meta">Set in Administration. Lists longer than this are refused.</small></label><label class="wide">Instruction<textarea name="comments" rows="3" placeholder="Shared instruction for all selected records">${esc(draft.comments||'')}</textarea></label>${u.otp?`<label class="wide">One-time code<input name="otp" inputmode="numeric" autocomplete="one-time-code" placeholder="Enter the 6-digit code" required><small class="meta">Required — this batch has ${u.otp.count} records, more than the ${OTP_THRESHOLD} that can be assigned without confirmation. We sent a 6-digit code to your registered contact.</small></label>`:''}<div class="wide form-row"><button class="btn">${u.otp?'Check the code and continue':'Check and apply'}</button>${u.otp?'<button type="button" class="btn ghost" data-otp-cancel>Start over without the code</button>':''}</div></form></div>`;
  const form=el.querySelector('form'); const collect=()=>Object.fromEntries(new FormData(form)); const updateDraft=(changed='manual')=>{ const d={...collect(),ids:form.ids.value}; const next=AssignmentCascade.cascade({draft:d,state:State.get(),changed}); UIState.set('bulk-assignment',{...UIState.get('bulk-assignment'),draft:{...d,...next}}); render(el); };
  ['category','subcategory','dsu','supportDsu','priority'].forEach(n=>form.elements[n]?.addEventListener('change',()=>updateDraft(n))); form.querySelectorAll('input,textarea,select').forEach(x=>x.addEventListener('input',()=>UIState.set('bulk-assignment',{...UIState.get('bulk-assignment'),draft:{...collect(),ids:form.ids.value}}))); el.querySelector('[data-otp-cancel]')?.addEventListener('click',()=>{UIState.set('bulk-assignment',{...UIState.get('bulk-assignment'),otp:null});render(el)});
  /* Both one-time-code steps below pass `notify:false`. Neither is a failure the governance
     layer could describe correctly. When requesting a code fails, the batch does NOT stop —
     it falls back to confirming on this device and shows the operator the code, so "Could not
     send the one-time code. Nothing was changed." would contradict what just happened on
     screen. When verifying fails, the operator needs the six digits re-entered, which is a
     specific instruction, not a generic outcome. Both messages already say plainly that
     nothing has been assigned. */
  form.onsubmit=async e=>{e.preventDefault();const d=collect();const ids=splitIds(d.ids);if(!ids.length){focusField(form,'ids');return toast('Activity IDs — enter at least one. These are the records the assignment below is applied to.','error');}if(ids.length>cap){focusField(form,'ids');return toast(`Activity IDs — you listed ${ids.length} records and this workspace assigns at most ${cap} at a time. Remove ${ids.length-cap} and run them as a second batch.`,'error');}const current=State.get(),known=new Set(current.activities.map(a=>String(a.id))),missing=ids.filter(id=>!known.has(id));if(missing.length){focusField(form,'ids');return toast(`Activity IDs — ${missing.length} of these are not in the register, so nothing was assigned: ${missing.join(', ')}. Correct or remove them and try again.`,'error');}const cascade=AssignmentCascade.cascade({draft:d,state:current,changed:'submit'});const merged={...d,...cascade,ids:d.ids,cascadeSnapshot:cascade.cascadeSnapshot};const draftErrors=AssignmentCascade.validateDraft(merged);if(draftErrors.length){focusField(form,assignmentErrorField(draftErrors));return toast(assignmentErrors(draftErrors).join(' · '),'error');}if(ids.length>OTP_THRESHOLD&&!u.otp){let challenge;try{const res=await ActionRuntime.run('bulk-assignment','request-otp',{purpose:'bulk-assignment',refs:ids.slice(0,5),operation:'BULK_ASSIGNMENT'},{notify:false});challenge={requestId:res?.requestId||crypto.randomUUID(),code:null,backend:true,count:ids.length};toast('We sent a 6-digit code to your registered contact. Enter it below to continue.','success')}catch{const code=String(Math.floor(100000+Math.random()*900000));challenge={requestId:crypto.randomUUID(),code,backend:false,count:ids.length};toast('We could not send a code, so this batch is being confirmed on this device instead. Your code is '+code,'info')}UIState.set('bulk-assignment',{...u,otp:challenge,draft:{...merged,ids:d.ids}});return render(el)} if(u.otp){const entered=String(d.otp||'').trim();if(u.otp.backend){try{await ActionRuntime.run('bulk-assignment','verify-otp',{requestId:u.otp.requestId,otp:entered,operation:'BULK_ASSIGNMENT',refs:ids.slice(0,5)},{notify:false})}catch{focusField(form,'otp');return toast('One-time code — that code was not accepted. Check the 6 digits sent to your registered contact and enter them again. Nothing has been assigned.','error')}}else if(entered!==u.otp.code){focusField(form,'otp');return toast('One-time code — that code does not match. Check the 6 digits and enter them again. Nothing has been assigned.','error')}} const payload=buildBulkAssignmentPayload({ids,form:merged,actor:current.profile,otpVerified:ids.length>OTP_THRESHOLD});const errors=validateBulkAssignmentPayload(payload);if(errors.length){focusField(form,assignmentErrorField(errors));return toast(assignmentErrors(errors).join(' · '),'error');}if(!await confirmAction({title:'Preview & confirm bulk assignment',body:`<p>Assign ${ids.length} record${ids.length===1?'':'s'} to <b>${esc(payload.assignedTo||'no one yet')}</b>? Each one is updated and the assignee is notified.${ids.length>OTP_THRESHOLD?' Your one-time code was accepted.':''}</p>${assignmentPreviewHtml(payload)}`,confirmText:`Assign ${ids.length} record${ids.length===1?'':'s'}`,cancelText:'Cancel'}))return;await executeOwnedAction('bulk-assignment','bulk-assign',()=>{const activities=current.activities.map(a=>ids.includes(String(a.id))?{...a,category:payload.category,subcategory:payload.subcategory,categoryCode:payload.categoryCode,subcategoryCode:payload.subcategoryCode,assignmentStatus:'Assigned',assignedTo:payload.assignedTo,assignedDsu:payload.assignedToDsu,supportingAssignee:payload.supportingAssignee,supportingDsu:payload.supportingDsu,ccRecipients:payload.ccRecipients,priority:payload.priority,due:payload.due,ack:payload.ack,cascadeSnapshot:payload.cascadeSnapshot}:a);State.patch({activities},{module:'bulk-assignment',action:'assignment:bulk-cascaded',ref:ids.length+' record(s)'});invoke('BULK_ASSIGNMENT',payload).catch(()=>toast('Saved on this device — these assignments will be sent to the registry when the connection returns','error'));},{ref:ids.length+' record(s)',meta:{count:ids.length,otp:ids.length>OTP_THRESHOLD,preview:true,cascade:payload.cascadeSnapshot?.rule?.id}});UIState.set('bulk-assignment',{otp:null,draft:null});toast(`${ids.length} record${ids.length===1?'':'s'} assigned to ${payload.assignedTo||'the selected DSU'}`,'success');render(el)};
}

import { hydrateGovernance, executeOwnedAction } from '../core/governed-actions.js';
import { State } from '../core/state.js';
import { head, esc, toast, confirmAction, fmtDateTime, emptyFor, loadFlags } from '../core/ui.js';
import { requestSync } from '../core/data-loader.js';
function scopeRef(s) {
  const a = s.activities.find(x => x.id === s.selectedId) || s.tracking.find(x => x.id === s.selectedId);
  return a ? (a.referenceId || a.id) : null;
}
export async function mount(el){hydrateGovernance();render(el); }
function render(el) {
  const s = State.get(); const ref = scopeRef(s);
  const items = ref ? s.comments.filter(c => c.referenceId === ref) : s.comments;
  /* I-13 — "No comments yet." read the same whether nobody had commented, the thread was
     narrowed to one reference that happens to have none, or nothing had loaded at all. The
     scope is this screen's only filter, so it is the filtered arm; loadFlags() supplies the
     other two from lastLoad.ok, the flag core/data-loader.js writes on a failed load. */
  const thread = items.length
    ? items.map(c => `<div class="msg ${c.author === s.profile.email ? 'mine' : ''}"><span class="who">${esc(c.author)} · ${esc(fmtDateTime(c.ts))} ${c.referenceId ? '· ' + esc(c.referenceId) : ''}</span>${esc(c.body)}</div>`).join('')
    : emptyFor({ filtered: !!ref, ...loadFlags(s.runtime), noun: 'comments', createLabel: 'Write the first comment', createAttr: 'data-write-comment', clearAttr: 'data-clear-scope' });
  el.innerHTML = `<div class="workspace">${head('Comments', ref ? `Only the comments recorded against ${ref}.` : 'Every comment recorded against a record, newest first.')}
    <div class="toolbar"><span class="meta">${ref ? `Reference ${esc(ref)} · ${items.length} comment(s)` : `${items.length} comment(s)`}</span>
      <div>${ref ? '<button class="btn ghost" data-clear-scope>Show comments on every record</button>' : ''}<button class="btn ghost" data-refresh>Refresh</button></div></div>
    <div class="panel"><div class="thread">${thread}</div>
    <form class="grid" id="comment-form">${ref ? '' : '<label class="wide">Reference ID (optional)<input name="referenceId" placeholder="e.g. REF-001"></label>'}
      <label class="wide">Comment<textarea name="body" rows="3" required></textarea></label>
      <div class="wide"><button class="btn">Post Comment</button></div></form></div></div>`;
  el.querySelectorAll('[data-clear-scope]').forEach(b => b.onclick = () => { State.patch({ selectedId: null }); render(el); });
  /* The create arm has nowhere else to go — the form is already on the page — so it puts the
     cursor in it rather than rendering a button that only scrolls. */
  el.querySelectorAll('[data-write-comment]').forEach(b => b.onclick = () => el.querySelector('#comment-form [name="body"]')?.focus());
  el.querySelectorAll('[data-refresh]').forEach(b => b.onclick = () => render(el));
  el.querySelectorAll('[data-retry-load]').forEach(b => b.onclick = async () => {
    b.disabled = true;
    try { await requestSync({ source: 'comments', mode: 'refresh' }); toast('Comments reloaded from the registry', 'success'); }
    catch { toast('The registry could not be reached — nothing was reloaded', 'error'); }
    finally { b.disabled = false; }
    render(el);
  });
  el.querySelector('#comment-form').onsubmit = async e => {
    e.preventDefault(); const d = Object.fromEntries(new FormData(e.target));
    const referenceId = ref || d.referenceId || '';
    if (!await confirmAction({
      title: 'Post this comment',
      body: `<p>${esc(d.body)}</p><p class="meta">${referenceId ? `It is attached to ${esc(referenceId)} and anyone who opens that record will see it, under your name.` : 'It is not attached to any record, and will appear in the general thread under your name.'}</p>`,
      confirmText: 'Post comment', cancelText: 'Cancel',
    })) return;
    await executeOwnedAction('comments', 'add-comment', () => State.patch({ comments: [...s.comments, { id: crypto.randomUUID(), referenceId, body: d.body, author: s.profile.email, ts: new Date().toISOString(), type: 'comment' }] }, { module: 'comments', action: 'comment:add', ref: referenceId }), { ref: referenceId });
    toast('Comment posted', 'success'); render(el);
  };
}

import { hydrateGovernance, executeOwnedAction } from '../core/governed-actions.js';
import { State } from '../core/state.js';
import { UIState } from '../core/ui-state.js';
