function templates(){ return `<section class="panel"><h2>Official templates</h2><div class="dashboard-grid">${Mail.templates().map(t=>`<article class="panel"><div class="eyebrow">${esc(t.category)}</div><h3>${esc(t.label)}</h3><p class="meta">A ${esc(t.tone)} letter, laid out on the official letterhead.</p><span class="pill">${(t.required||[]).length} fields you must fill in</span></article>`).join('')}</div></section>`; }
