function register(rows){ const sent=rows.filter(x=>x.status==='sent'); return `<section class="panel"><h2>Everything sent from this desk</h2>${sent.length?`<div class="tablewrap dgo-table-wrap"><table class="dgo-table"><thead><tr><th>Reference</th><th>Subject</th><th>Recipient</th><th>Template</th><th>Sent</th><th>By</th></tr></thead><tbody>${sent.map(x=>`<tr><td>${esc(x.referenceId)}</td><td>${esc(x.subjectLine||x.subject)}</td><td>${esc(x.recipientEmail)}</td><td>${esc(x.templateId)}</td><td>${esc(fmtDateTime(x.sentAt||''))}</td><td>${esc(x.sentBy||'')}</td></tr>`).join('')}</tbody></table></div>`:emptyFor({...loadFlags(State.get().runtime),noun:'sent emails',createLabel:'Open Drafts / Outbox',createAttr:'data-open-drafts'})}</section>`; }
function workspace(s,u,sources,rows,selected){ const list=u.tab==='sources'?sources:rows.filter(x=>x.status!=='archived'); return `<div class="split" ${mdSwitch(u.md)}><div class="list-col panel">${u.tab==='sources'?sourceList(list,s):draftList(list,selected,s)}</div><div class="detail-col panel-stack">${u.tab==='sources'?composer(sources.find(x=>String(x.id)===String(u.selected))||sources[0]||null,u):selected?detail(selected):`<section class="panel"><div class="empty dgo-empty"><h2 class="dgo-empty__title">No email open</h2><p>Choose an email on the left to read it, send it or archive it. Nothing is open, so there is nothing to show.</p></div></section>`}</div></div>`; }
/* I-13 — both lists stated a fact. Neither is filtered (the tabs switch between two different
