function sourceList(list,s){ return list.length?capRows(list,RenderBudget.listRows).map(r=>`<div class="list-item" data-source="${esc(r.id)}"><div class="meta">${esc(r.kind)} · ${esc(r.referenceId||'No reference')} ${badge(r.classification||'Official')}</div><h4>${esc(r.subject||'Untitled correspondence')}</h4><div class="meta">Suggested recipient: ${esc(r.recipientEmail||r.recipientName||'none on file')}</div></div>`).join(''):emptyFor({...loadFlags(s?.runtime),noun:'letters to reply to'}); }
function draftList(list,selected,s){ return list.length?capRows(list,RenderBudget.listRows).map(x=>`<div class="list-item ${selected&&selected.id===x.id?'active':''}" data-draft="${esc(x.id)}"><div class="meta">${badge(x.status,tone(x))} ${esc(x.referenceId||'—')}</div><h4>${esc(x.subjectLine||x.subject)}</h4><div class="meta">To: ${esc(x.recipientEmail||'—')} · ${esc(fmtDateTime(x.updatedAt||x.createdAt||''))}</div></div>`).join(''):emptyFor({...loadFlags(s?.runtime),noun:'drafts',createLabel:'Start one from a letter',createAttr:'data-open-sources'}); }
