rame"><iframe title="Preview of the email as the recipient will see it" sandbox="" srcdoc="${esc(rendered.html)}"></iframe></div></details></section>`;
}
function detail(x){ return `${mdBack('Back to outbox')}<section class="panel"><div class="eyebrow panel-eyebrow">Correspondence email record</div><div class="status-strip">${badge(x.status,tone(x))} ${badge(x.classification)} ${badge(x.priority)}</div><h2>${esc(x.subjectLine||x.subject)}</h2><dl class="detail-grid"><dt>Reference</dt><dd>${refCode(x.referenceId)}</dd><dt>To</dt><dd>${esc(x.recipientEmail)}</dd><dt>Template</dt><dd>${esc(x.templateId)}</dd><dt>Updated</dt><dd>${esc(fmtDateTime(x.updatedAt||''))}</dd>${x.sentAt?`<dt>Sent</dt><dd>${esc(fmtDateTime(x.sentAt))}</dd>`:''}${x.lastError?`<dt>Why it did not go out</dt><dd>${esc(x.lastError)}</dd>`:''}</dl><div class="form-row">${x.status!=='sent'?'<button class="btn" data-send>Send this email</button>':''}<button class="btn ghost" data-duplicate>Duplicate</button><button class="btn ghost" data-archive>Archive</button></div></section><section class="panel"><details open><summary>How this will look to the recipient</summary><div class="email-frame"><iframe title="Preview of the email as the recipient will see it" sandbox="" srcdoc="${esc(x.html)}"></iframe></div></details></section><section class="panel"><details><summary>Plain-text version, for recipients whose mail cannot show the letterhead</summary><pre class="preview-box">${esc(x.plain||'')}</pre></details></section>`; }
function bind(el){
  el.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{UIState.set('correspondence-email',{tab:b.dataset.tab,selected:'',md:'list'});render(el)});
