async function createRecord(e,base,s,el){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const minted=mintReference(base);const id=minted.reference;const c={id,referenceId:id,referenceProvisional:minted.provisional,subject:d.subject,sender:d.sender,senderEmail:d.contact,receivedAt:new Date(d.receivedDate).toISOString(),eventDate:d.eventDate,correspondenceType:'Incoming',channel:'Document',category:d.category,status:d.status,priority:normalizePriority(d.priority),confidentiality:'Official',description:d.remarks,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};if(!await confirmAction({title:'Confirm new record',body:`<p>${esc(c.subject)}</p>${actionPreview({id,category:c.category,priority:c.priority,status:c.status})}`}))return;await executeOwnedAction('correspondence','create-correspondence',()=>{State.patch({correspondence:[c,...base],audit:[audit('Correspondence Logged','correspondence',id,{},s.profile.email),...s.audit]},{module:'correspondence',action:'tracker:create',ref:id});invoke('DYNAMIC_ACTIONS',{action:'upsert_record',module:'DGCEO_Tracker',data:c}).catch(()=>toast('Saved on this device — it will reach the registry when the connection returns','error'));},{ref:id});UIState.set('correspondence',{creating:false,selected:id});toast('Record saved successfully','success');render(el);}

/* D2 — the AI spine, rendered BESIDE the human form rather than into it.
   Nothing here writes to the record. The officer's form is the only thing that commits, so
   an AI proposal is something to read, agree with or ignore — never the record's default
   state. `Use these values` fills the form and leaves the officer to submit it, which is
   what makes an acceptance evidenced as a person accepting.

   Every branch below renders. An unconfigured, unreachable or nonsense-returning AI produces
   a line of text and no blocker: the Save button is in the human form and this panel cannot
   disable it. */
function aiSpinePanel(r,u){
  const p=u.aiProposal, busy=u.aiBusy;
  const head=`<div class="eyebrow panel-eyebrow">AI proposal · advisory</div>`;
  if(busy) return `<section class="panel"><div class="ai-spine">${head}<p class="meta">Analysing…</p></div></section>`;
  if(!p) return `<section class="panel"><div class="ai-spine">${head}<p class="meta">Not consulted. Triage does not require it.</p><div class="form-row"><button type="button" class="btn ghost" data-ai-triage>Request AI classification</button></div></div></section>`;
  if(!isAiUsable(p)) return `<section class="panel"><div class="ai-spine">${head}<p class="meta">Unavailable${p.reason?` — ${esc(p.reason)}`:''}. <b>Triage continues without it.</b></p><div class="form-row"><button type="button" class="btn ghost" data-ai-triage>Try again</button></div></div></section>`;
  const human=humanProposal({category:r.category,priority:r.priority},{by:'form'});
  const cmp=compareProposals(human,p);
  const rows=Object.entries(p.fields).map(([k,v])=>`<div class="action-row"><span>${esc(k)}</span><b>${esc(v)}</b>${cmp.differ.includes(k)?' <span class="pill warn">differs</span>':cmp.agree.includes(k)?' <span class="pill ok">agrees</span>':''}</div>`).join('');
  const conf=p.confidence==null?'not scored':`${Math.round(p.confidence*100)}%`;
  return `<section class="panel"><div class="ai-spine">${head}<p class="meta">Confidence: <b>${esc(conf)}</b>${p.rationale?` · ${esc(p.rationale)}`:''}</p>${rows}<div class="form-row"><button type="button" class="btn ghost" data-ai-accept>Use these values</button><button type="button" class="btn ghost" data-ai-triage>Re-run</button></div><p class="meta">Filling the form does not save it. You submit.</p></div></section>`;
}

async function runAiTriage(r,el,render){
  UIState.set('correspondence',{aiBusy:true}); render(el);
  let proposal;
  try{
    /* Bounded deliberately, and far below the contract's own 90s. This proposal is
       ADVISORY: an officer who asked for a suggestion and is still waiting a minute later
       has been crippled by it just as surely as if it had thrown, and the panel would sit
       on "Analysing…" while they wondered whether to trust it. Failing fast to
       "unavailable" is the behaviour D2 asks for — the human moves on. */
    const res=await invokeData('AI_DOC_ANALYSIS',{operation:'classify',referenceId:r.referenceId||String(r.id),subject:r.subject,remarks:r.remarks},{timeoutMs:8000,retry:0});
    proposal=aiProposal(res);
  }catch(e){
    /* The catch is the point of the whole decision. An endpoint that is missing, refusing or
       timing out must land the officer in exactly the state they were in before they asked. */
    proposal=aiUnavailable(e.message||'the classification service is unavailable — the record is unchanged');
  }
  UIState.set('correspondence',{aiBusy:false,aiProposal:proposal});
  render(el);
}

