  return s.tracking.filter(t => t.dispatchStatus !== 'closed' && (t["status"] === 'Completed' || t.dispatchStatus))
    .sort((a, b) => (a["dispatchStatus"] ? 1 : 0) - (b["dispatchStatus"] ? 1 : 0));
