el.querySelectorAll('[data-source-view]').forEach(b=>b.onclick=()=>{UIState.set('response-tracking',{source:b.dataset.sourceView,selected:'',md:'list'});render(el)});el.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{UIState.set('response-tracking',{tab:b.dataset.tab});render(el)});debouncedInput(el.querySelector('[data-query]'),v=>{UIState.set('response-tracking',{query:v});render(el)},{refind:()=>el.querySelector('[data-query]')});el.querySelector('[data-export]').onclick=()=>all.length?exportRows(all,cols):toast('There is nothing in this list to export','error');el.querySelectorAll('tbody tr').forEach(tr=>tr.onclick=()=>{if(tab==='matrix'){UIState.set('response-tracking',{selected:tr.dataset.id,md:'detail'});render(el);resetDetailScroll(el)}else{State.patch({selectedId:tr.dataset.id});location.hash='#/'+tr.dataset.route;}});el.querySelector('[data-md-back]')?.addEventListener('click',()=>{UIState.set('response-tracking',{md:'list'});render(el)});
