el.querySelectorAll('[data-date]').forEach(i=>i.onchange=()=>{UIState.set('statistics',i.dataset.date==='start'?{start:i.value}:{end:i.value});render(el)});el.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>{selected.has(b.dataset.template)?selected.delete(b.dataset.template):selected.add(b.dataset.template);UIState.set('statistics',{templates:[...selected]});render(el)});el.querySelector('[data-all]').onclick=()=>{UIState.set('statistics',{templates:[...templates]});render(el)};el.querySelector('[data-none]').onclick=()=>{UIState.set('statistics',{templates:[]});render(el)};el.querySelector('[data-recipient]').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const v=e.target.value.trim();if(v&&/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)&&!recipients.includes(v))UIState.set('statistics',{recipients:[...recipients,v]});render(el)}};el.querySelectorAll('[data-remove-recipient]').forEach(x=>x.onclick=()=>{UIState.set('statistics',{recipients:recipients.filter(r=>r!==x.dataset.removeRecipient)});render(el)});el.querySelector('[data-generate]').onclick=()=>{if(!data||!data.length){toast('No report rows for the selected range/templates','info');return;}download(htmlDoc(s,data),'nitda-stats-report.html','text/html');toast('Report generated and downloaded','success');};el.querySelector('[data-html]').onclick=()=>download(htmlDoc(s,data),'nitda-stats-report.html','text/html');el.querySelector('[data-sp]').onclick=async()=>{if(!await confirmAction({title:'Refresh the report rows',body:`<p>Ask the registry for the current rows and rebuild this report?</p>${actionPreview({From:start||'the earliest record',To:end||'today',Reports:[...selected].join(', ')||'none selected'})}`,confirmText:'Refresh',cancelText:'Cancel'}))return;try{await requestSync({source:'statistics',mode:'endpoint',endpoint:'FETCH_ALL',payload:{action:'lookupTasksReports',start,end}});toast('The registry has been asked for the current rows — they appear here when they arrive','success')}catch{toast('T