/* R11.6.2 pane independence & view switching.
   Defect 3: sections/panes must scroll independently — on desktop each side of a
   master-detail split (and the DG/CEO tri-pane) is its own bounded scroll region,
   so scrolling the item list never drags the detail pane along (and vice versa).
   Defect 1/2: on portrait/narrow viewports a split shows ONE view at a time —
   data-md="list" shows the queue, data-md="detail" shows the selected record with
   an explicit back control; row selection switches the view. Splits without
   selection semantics carry no data-md and keep stacked flow. */
.panel-stack{display:flex;flex-direction:column;gap:10px;min-width:0}
.panel-stack>.panel{min-height:0;flex:0 0 auto}
.md-back{display:none}
.split{--pane-max:calc(100dvh - var(--ministry) - var(--header) - var(--footer) - 28px)}
.dg-layout{--pane-max:calc(100dvh - var(--ministry) - var(--header) - var(--footer) - 28px)}
