/* DGO R11.6 harmonized design-system integration layer. */
:root,
[data-theme="light"],
[data-theme="government"]{
  --dgo-shell-sidebar-w: var(--dgo-sidebar-w, 264px);
  --dgo-shell-topbar-h: calc(var(--dgo-density-row) + var(--dgo-s-4));
  --dgo-card-bg: var(--dgo-color-surface-raised, #fff);
  --dgo-card-border: var(--dgo-color-border-default, rgba(5,88,59,.14));
  --dgo-card-shadow: var(--dgo-shadow-1, 0 1px 2px rgba(5,88,59,.08));
}
[data-theme="hc"], [data-theme="high-contrast"]{ color-scheme: light; }
html, body { min-height:100%; }
body { background:var(--dgo-color-surface-sunken,#f6f8f6); color:var(--dgo-color-fg-default,#1b1a1a); }
.dgo-ministry-bar{height:26px;display:flex;align-items:center;justify-content:center;background:var(--dgo-green-900,#022819);color:#fff;font-weight:700;letter-spacing:.13em;text-transform:uppercase;overflow:hidden;padding:0 12px;}
/* `display:grid;place-items:center` sized its direct text child to its max-content width
   (justify-self defaults to center, not stretch), so the child never shrank to the bar's own
   width and text-overflow:ellipsis — declared on the grid box, not on that child — never had
   anything to apply to: long ministry names were hard-clipped with no ellipsis. A flex row
   with a shrinkable, ellipsing text child fixes both. */
.dgo-ministry-bar__text{min-width:0;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
dgo-shell{height:100vh;background:var(--dgo-color-surface-sunken,#f6f8f6);}
.dgo-shell-grid{height:calc(100vh - 26px);min-height:0}
/* Surface context (Phase 5a). The sidebar is an inverse surface in every theme, so the
   page-level foreground semantics do not describe it. base.css paints `strong, b` with
   --dgo-color-fg-strong, which is #1B1A1A in light and #000000 in hc, so the brand lockup and
   the signed-in identity rendered dark-on-dark: measured 1.09:1 and 1.32:1 on all 24 routes.
   Re-binding the three foreground semantics on the surface itself fixes every descendant that
   reads them — including ones added later — instead of patching each rule.

   `background` is no longer declared here: components.css already gives .dgo-sidebar
   `background: var(--dgo-sidebar-bg)`, which the theme files re-bind (#022819 light,
   #081109 dark, #000000 hc). This rule was overriding it with the raw --dgo-green-900
   primitive from the last layer, which is why neither `dark` nor `hc` reached the sidebar. */
.dgo-sidebar{min-height:0;display:flex;flex-direction:column;color:#fff;
  --dgo-color-fg-strong:var(--dgo-color-fg-on-brand);
  --dgo-color-fg-default:var(--dgo-sidebar-fg);
  --dgo-color-fg-muted:rgba(255,255,255,.62);}
/* H-03 — the sidebar carried a 329-byte placeholder mark while the public portal carried the
   real NITDA lockup, so the two halves of one programme showed different agency identities.
   The real lockup is wider than it is tall, so the brand block stacks instead of sitting the
   image beside the wordmark: agency identity first, product name under it. The sidebar is a
   dark surface, hence the white variant. */
.dgo-brand-lockup{display:flex;flex-direction:column;gap:10px;align-items:flex-start;padding:16px 18px;border-bottom:1px solid rgba(255,255,255,.11);}
.dgo-brand-lockup__agency{height:40px;width:auto;max-width:100%;flex:none;display:block}.dgo-brand-lockup b{display:block;font-family:var(--dgo-family-display,Outfit,system-ui);font-size:16px}.dgo-brand-lockup b span{color:var(--dgo-smart-400,#17B255)}.dgo-brand-lockup small{display:block;font-size:var(--dgo-type-floor);letter-spacing:.16em;text-transform:uppercase;color:rgba(255,255,255,.58)}
/* I-10 — the scrollable region ended above a fixed identity footer with no affordance, so at a 540px-tall viewport five of nine items sat below the fold and the first of them rendered half-cut. A fade at the boundary shows the list continues, and scroll-padding keeps a row from being sliced across. */.dgo-sidebar__nav{flex:1;min-height:0;overflow:auto;padding:8px 12px 14px;scroll-padding-block:8px;overscroll-behavior:contain;-webkit-mask-image:linear-gradient(to bottom,#000 calc(100% - 22px),transparent 100%);mask-image:linear-gradient(to bottom,#000 calc(100% - 22px),transparent 100%)}.dgo-sidebar__nav:not([data-scrollable="true"]){-webkit-mask-image:none;mask-image:none}.dgo-nav-group{margin-top:13px}.dgo-nav-group__label{font-weight:800;letter-spacing:.13em;text-transform:uppercase;color:var(--dgo-color-fg-muted);padding:0 12px 7px}.dgo-sidebar__item{position:relative;display:flex;align-items:center;gap:11px;min-height:var(--dgo-control-target-min);border-radius:9px;padding:8px 12px;color:rgba(255,255,255,.82);text-decoration:none;font-weight:650;font-size:13.5px}.dgo-sidebar__item:hover{background:rgba(255,255,255,.07)}.dgo-sidebar__item.active{background:rgba(23,178,85,.15);color:#fff}.dgo-sidebar__item.active:before{content:"";position:absolute;left:-12px;top:10px;bottom:10px;width:3px;border-radius:0 3px 3px 0;background:var(--dgo-smart-400,#17B255)}.dgo-nav-icon{width:22px;text-align:center;color:var(--dgo-smart-300,#8ff0bb)}
/* SYSTEM · RESTRICTED — the Figma shell sets this group apart visually (a recessed
   background and a top rule) so Administration and System Health read as a different kind
   of destination before a user even opens them. It stays inside .dgo-sidebar__nav, in the
   same scroll flow as every other group: an earlier version docked it as a separate fixed
   panel above the identity footer, which starved the scrollable region of height on short
   viewports and produced exactly the half-cut row I-10 exists to prevent (measured at
   1440x540 — the nav's own content shrank to 61px, well under one row). Height must stay
   owned by one flexible region. */
.dgo-nav-group--system{margin-top:13px;padding-top:11px;border-top:1px solid rgba(255,255,255,.14);background:rgba(0,0,0,.14);border-radius:9px}
.dgo-sidebar__badge{margin-left:auto;flex:none;font-size:9px;font-weight:800;letter-spacing:.04em;color:rgba(255,255,255,.9);background:rgba(255,255,255,.16);border-radius:4px;padding:2px 6px}
.dgo-sidebar__identity{padding:14px 16px;border-top:1px solid rgba(255,255,255,.11)}.dgo-sidebar__identity b{display:block;font-size:13px}.dgo-sidebar__identity small{display:block;color:rgba(255,255,255,.62);font-size:11px;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
