/* z-index:1300, not 1000: a blocking, aria-modal dialog must outrank every non-modal
   overlay it can be triggered behind — the notify panel (z-index:1200) and toast host
   (1100) both sat above it, so a confirm() opened while either was showing rendered
   invisibly underneath. The focus trap only intercepts Tab/Escape, not clicks elsewhere
   on the page, so triggering a dialog with the notify panel still open is reachable in
   normal use, not just synthetically. */
.dgo-dialog-backdrop,.dgo-cmdk:not([hidden]){position:fixed;inset:0;z-index:1300;display:grid;place-items:start center;padding-top:10vh;background:rgba(0,0,0,.36)}.dgo-dialog,.dgo-cmdk__dialog{width:min(640px,calc(100vw - 28px));background:var(--dgo-card-bg);border:1px solid var(--dgo-card-border);border-radius:18px;box-shadow:var(--dgo-shadow-5,0 18px 50px rgba(0,0,0,.18));overflow:hidden}.dgo-dialog header,.dgo-dialog footer{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:14px 16px;border-bottom:1px solid var(--dgo-card-border)}.dgo-dialog footer{border-top:1px solid var(--dgo-card-border);border-bottom:0;justify-content:flex-end}.dgo-dialog h2{margin:0;font-family:var(--dgo-family-display,Outfit,system-ui)}.dgo-dialog__body{padding:16px}.dgo-cmdk__search{padding:12px;border-bottom:1px solid var(--dgo-card-border)}.dgo-cmdk__search input{width:100%;height:44px}.dgo-cmdk__list{max-height:420px;padding:8px}.dgo-cmdk__item{width:100%;display:flex;align-items:center;gap:12px;border:none;background:transparent;border-radius:10px;text-align:left;padding:10px 12px;cursor:pointer;color:inherit}.dgo-cmdk__item:hover,.dgo-cmdk__item:focus{background:var(--dgo-color-surface-sunken,#f4f7f4)}.dgo-cmdk__item small{display:block;color:var(--dgo-color-fg-muted,#626a64)}.dgo-cmdk__footer{padding:10px 14px;border-top:1px solid var(--dgo-card-border);font-size:12px;color:var(--dgo-color-fg-muted,#626a64)}.dgo-cmdk__empty{padding:20px;color:var(--dgo-color-fg-muted,#626a64)}
