/* Screen containment remediation — footer-visible, no page/main scroll, independent bounded panes. */
:root{
  --dgo-shell-ministry-h: 26px;
  --dgo-shell-footer-h: 40px;
}
html,
body,
#app,
dgo-shell{
  inline-size:100%;
  block-size:100dvh;
  max-block-size:100dvh;
  min-block-size:0;
  overflow:hidden !important;
}
dgo-shell{
  display:block;
  contain:layout size;
}
.dgo-ministry-bar{
  block-size:var(--dgo-shell-ministry-h);
  min-block-size:var(--dgo-shell-ministry-h);
  max-block-size:var(--dgo-shell-ministry-h);
  flex:0 0 var(--dgo-shell-ministry-h);
}
.dgo-shell-grid{
  block-size:calc(100dvh - var(--dgo-shell-ministry-h));
  max-block-size:calc(100dvh - var(--dgo-shell-ministry-h));
  min-block-size:0;
  overflow:hidden !important;
  display:grid;
  grid-template-columns:var(--dgo-shell-sidebar-w) minmax(0,1fr);
  grid-template-rows:minmax(0,1fr);
  inline-size:100%;
}
.dgo-workarea{
  min-block-size:0;
  overflow:hidden !important;
  display:grid !important;
  grid-template-rows:var(--dgo-shell-topbar-h) minmax(0,1fr) var(--dgo-shell-footer-h);
}
.dgo-topbar{
  block-size:var(--dgo-shell-topbar-h);
  min-block-size:var(--dgo-shell-topbar-h);
  max-block-size:var(--dgo-shell-topbar-h);
  flex:0 0 var(--dgo-shell-topbar-h);
}
/* THE scroller. The shell has always asked for one — shared/shell.js renders
   `class="dgo-main dgo-scroll"` — and two call sites already assume this element is it:
   core/ui.js `resetWorkspaceScroll()` sets `main.scrollTop=0`, and core/router.js sets
   `out.scrollTop=0` after mounting a route. Neither could ever have had an effect while
   this rule said `overflow:hidden !important`; content taller than the viewport was
   clipped with no scrollbar and no indication anything had been cut.

   The containment above this line is unchanged and still does its job: html/body/#app/
   dgo-shell, .dgo-shell-grid and .dgo-workarea stay contained, so the footer remains
   pinned and visible and the page itself never scrolls. Only this one element inside that
   frame scrolls, which is what "footer-visible, no page scroll" was always meant to buy. */
.dgo-main{
  min-inline-size:0;
  min-block-size:0;
  max-block-size:100%;
  overflow-x:hidden;
  overflow-y:auto;
  overscroll-behavior:contain;
}
/* The class the markup requests. Kept as its own rule rather than folded into .dgo-main so
   any other region can opt into the same behaviour by adding it. */
.dgo-scroll{
  overflow-y:auto;
  min-block-size:0;
  overscroll-behavior:contain;
}
.dgo-footer{
  display:flex !important;
  flex:0 0 var(--dgo-shell-footer-h);
  block-size:var(--dgo-shell-footer-h);
  min-block-size:var(--dgo-shell-footer-h);
  max-block-size:var(--dgo-shell-footer-h);
  overflow:hidden;
  visibility:visible !important;
}
/* Route stage and workspace: `min-block-size:100%` so a short route still fills the frame
   and its footer-adjacent panels sit where they always did, but no `max-block-size` and no
   `overflow:hidden` — a workspace taller than the frame now grows and .dgo-main scrolls it.
   These three declarations were what turned "the pane is bounded" into "the content is
   gone": a workspace pinned to exactly 100% with hidden overflow has nowhere to put its
   overflow and no way to reveal it. */
.dgo-main>.route-stage,
.dgo-main>.route-stage>.workspace,
.dgo-main>.workspace{
  min-inline-size:0;
  min-block-size:100%;
}
.dgo-main>.route-stage{display:flex;flex-direction:column;}
.dgo-main>.route-stage>.workspace,
.dgo-main>.workspace{display:flex;flex-direction:column;gap:10px;}

/* The visible page header (core/ui.js head()). The Figma exemplars — Command Center 2:43 and
   Intake & Assignment 2:44 — set the title at 28px Outfit Bold in fg-strong and the subtitle
   at 13px Inter Regular in fg-muted, stacked with a 2px gap, sitting 32px in from the content
   edge with 16px of air below. The workspace flex column already contributes 10px of that
   gap, so only the remainder is declared here.

   This must live in the `overrides` layer: brand-type.css sets `h1{font-size:var(--fs-h1)}`
   in `brand`, and app.css's own `h1{font-size:23px}` sits earlier in this same sheet. Both
   would otherwise decide the title's size instead of the exemplar. */
.dgo-page-head{display:flex;flex-direction:column;gap:2px;margin:0 0 6px;min-inline-size:0}
.dgo-page-head__eyebrow{margin:0 0 2px;font:700 var(--dgo-type-floor,11px) var(--dgo-family-sans,Inter,system-ui);letter-spacing:.12em;text-transform:uppercase;color:var(--dgo-color-fg-muted,#5f5c5d)}
.dgo-page-head__title{margin:0;font-family:var(--dgo-family-display,Outfit,system-ui);font-size:28px;font-weight:700;line-height:1.25;letter-spacing:-.01em;color:var(--dgo-color-fg-strong,#1b1a1a);overflow-wrap:break-word}
.dgo-page-head__subtitle{margin:0;font-family:var(--dgo-family-sans,Inter,system-ui);font-size:13px;font-weight:400;line-height:1.35;color:var(--dgo-color-fg-muted,#5f5c5d);max-inline-size:78ch;text-wrap:pretty}
/* Small viewports: the 28px title is the largest thing on a 360px screen and wraps to three
   lines on the longer names ("DGCEO Correspondence & Decision Hub"). One step down keeps the
   header to two lines without changing the hierarchy. */
@media (max-width:640px){
  .dgo-page-head__title{font-size:22px}
  .dgo-page-head__subtitle{font-size:12px}
}
.dgo-main>.route-stage>.workspace>.split,
.dgo-main>.workspace>.split,
.dgo-main>.route-stage>.workspace>.dgo-master-detail,
.dgo-main>.workspace>.dgo-master-detail,
.dgo-main>.route-stage>.workspace>.dg-layout,
.dgo-main>.workspace>.dg-layout,
.dgo-main>.route-stage>.workspace>.dashboard-grid,
.dgo-main>.workspace>.dashboard-grid,
.dgo-main>.route-stage>.workspace>.panel-stack,
.dgo-main>.workspace>.panel-stack{flex:1 1 auto;min-block-size:0;}
/* Multi-pane layouts stay bounded — that is the point of the pane model, and their
   children below opt into their own scrollbars. But bounded must mean "scrolls within its
   bound", never "clips at its bound": `auto` shows a scrollbar exactly when there is
   something to reach and is otherwise indistinguishable from `hidden`. */
.split,
.dgo-master-detail,
.dg-layout,
.dashboard-grid{
  min-inline-size:0;
  min-block-size:0;
  overflow:auto;
}
/* Equal-height panes only where the layout is a true 2-pane master-detail
   (has a data-md list/detail toggle) or an explicit dashboard/detail grid.
   Generic .split (e.g. collapsible guidance panels) keeps align-items:start
   so a collapsed <details> never inflates to its sibling's height. */
.split[data-md],
.dgo-master-detail,
.dg-layout,
.dashboard-grid{ align-items:stretch; }
.split>* ,
.dgo-master-detail__list,
.dgo-master-detail__detail,
.dg-layout>.panel,
.panel-stack,
.list-col,
.detail-col,
.tablewrap,
.dgo-table-wrap,
.dgo-table-scroll,
.command-results,
.dgo-cmdk__list,
.dgo-dialog__body,
.pane{
  min-inline-size:0;
  min-block-size:0;
  max-block-size:100%;
  overflow:auto !important;
  overscroll-behavior:contain;
}
.record-body{max-block-size:min(42vh,520px);overflow:auto !important;overscroll-behavior:contain;}
