dgo-shell[data-route="correspondence"] .list-col{
  min-block-size:0;
  max-block-size:100%;
  overflow:auto !important;
  overscroll-behavior:contain;
}
dgo-shell[data-route="correspondence"] .record-action-grid{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:8px;
}
dgo-shell[data-route="correspondence"] .record-action-grid .btn{
  min-inline-size:0;
  inline-size:100%;
  white-space:normal;
  min-block-size:42px;
}
dgo-shell[data-route="correspondence"] .record-body{
  max-block-size:clamp(120px,24vh,260px);
  overflow:auto !important;
}
@media (max-width:900px){
  dgo-shell[data-route="response-tracking"] .rt-workspace{grid-template-rows:auto auto minmax(0,1fr);gap:10px;}
  dgo-shell[data-route="response-tracking"] .kpis{grid-template-columns:repeat(2,minmax(0,1fr));}
  dgo-shell[data-route="response-tracking"] .rt-split{grid-template-columns:1fr;}
  dgo-shell[data-route="response-tracking"] .rt-split[data-md="list"]>[data-runtime-detail]{display:none!important;}
  dgo-shell[data-route="response-tracking"] .rt-split[data-md="detail"]>.matrix-list{display:none!important;}
  dgo-shell[data-route="correspondence"] .correspondence-split{grid-template-columns:1fr;}
  dgo-shell[data-route="correspondence"] .correspondence-split[data-md="list"]>.detail-col{display:none!important;}
  dgo-shell[data-route="correspondence"] .correspondence-split[data-md="detail"]>div:first-child{display:none!important;}
  dgo-shell[data-route="correspondence"] .record-action-grid{grid-template-columns:1fr;}
}
@media (orientation:landscape) and (max-height:720px){
  dgo-shell[data-route="response-tracking"] .kpis{grid-template-columns:repeat(4,minmax(0,1fr));}
  dgo-shell[data-route="response-tracking"] .kpi{min-block-size:86px;padding:10px 14px;}
  dgo-shell[data-route="response-tracking"] .source-view-chips{padding-block:6px;}
  dgo-shell[data-route="correspondence"] .record-action-grid{grid-template-columns:repeat(3,minmax(0,1fr));}
}


/* ============================================================
   R11.6 CONSOLIDATION — data-independent layout corrections
   (verified via headless render; no !important, single-owner)
   ============================================================ */
/* Kill the collapsed-panel stretch void: a collapsed <details> must not
   inflate to its open sibling's height. */
.cc-support-panels{align-items:start}
.cc-progressive:not([open]){min-height:0}
/* Fluid action grid: however many cards are visible (RBAC may hide some),
   they fill the row instead of leaving a large empty panel. */
.cc-action-grid{grid-template-columns:repeat(auto-fit,minmax(min(100%,230px),1fr))}
/* KPI / metric labels must break only at spaces, never mid-word
   (fixes "REFER ENCES" / "DISPAT CHED" on narrow cards). */
.kpi small,.cc-kpi-band .kpi small,.dgo-kpi-card__top>span:first-child,.dgo-stat__label{overflow-wrap:normal;word-break:keep-all;hyphens:none}
/* Mobile KPI band: two equal columns that fill the row so uppercase
   labels have room and never clip. */
@media(max-width:640px){
  .cc-kpi-band .kpis{grid-template-columns:repeat(2,minmax(0,1fr))}
  .cc-kpi-band .kpi{min-width:0}
}
/* .cc-kpi-band is a wrapper, not a metrics grid. A grouped rule
   (.kpis,.stat-row,.cc-kpi-band{display:grid;...}) wrongly made it a
   multi-column grid, so on narrow widths .kpis was trapped in the first
   track and the band's right half went empty. The band is block; only its
   inner .kpis is the grid. */
.cc-kpi-band{display:block}
/* R11.6 P0-3 — single canonical KPI grid (deterministic, width-following).
   One auto-fit rule for every .kpis (incl. .cc-kpi-band); overrides the prior
   non-monotonic fixed-column @media/@container rules by specificity + order,
   so column count follows available width consistently across all routes. */
.kpis,.cc-kpi-band .kpis{grid-template-columns:repeat(auto-fit,minmax(min(100%,150px),1fr))}
/* R11.6 §E — KPI metric cards: 3px smart-green left accent (flat brand). */
.kpi,.dgo-metric{border-left:3px solid var(--dgo-color-action-accent,#17B255)}
/* R11.6 fix (data-surfaced) — the workspace is a fixed-height flex column; sticky toolbars/
   filter bars must NOT shrink or clip when the record list is tall, otherwise their controls
   (search, filters, action buttons) get compressed and hidden. Keep natural height; the list
   pane owns the scroll. */
.toolbar,.dgo-toolbar,.dgo-filterbar,.filterbar{flex:0 0 auto;min-block-size:max-content;overflow:visible}
/* R11.6 §C — focus-visible parity: every clickable surface with a hover-only affordance
   must present the same state to keyboard users, plus the canonical focus ring. */
.action-card:focus-visible{transform:translateY(-1px);box-shadow:var(--dgo-shadow-3,0 8px 22px rgba(5,88,59,.12)),var(--focus)}
.list-item:focus-visible{border-color:var(--a);box-shadow:var(--focus)}
.command-item:focus-visible{background:var(--sunken);box-shadow:var(--focus)}
.navlink:focus-visible{background:#A2E0BB20;color:#fff;box-shadow:var(--focus)}
.dgo-sidebar__item:focus-visible{background:rgba(255,255,255,.07);box-shadow:var(--focus)}
.dgo-iconbtn:focus-visible{background:var(--dgo-color-surface-sunken,#f4f7f4);box-shadow:var(--focus)}
.dgo-search-trigger:focus-visible{border-color:var(--dgo-color-border-default,#dfe7e2);box-shadow:var(--focus)}
tr.row-link:focus-visible>td{background:var(--sunken)}

/* ============================================================
   R11.6 Phase-2 — layout / responsiveness / a11y fixes
   ============================================================ */

/* 2.1 — Reference-ID overflow-wrap: long IDs (e.g. "DGO-2024-R11-123456") must
   wrap rather than force horizontal page scroll on narrow viewports. */
.dgo-record-row__ref{
  min-inline-size:0;
  overflow-wrap:anywhere;
  word-break:break-word;
  max-inline-size:min(100%,22ch);
}

/* 2.2 — 320 px topbar containment.
   At 480 px and below the topbar width (320 px device = 300 px content after
   padding) cannot fit 7 icon-sized flex items plus the route title simultaneously.
   Hiding only workspace-guide and data-sync still left hamburger, search, density,
   theme, notify and persona — six flex:0 0 auto controls (~300px) — competing with
   .dgo-route-title for what's left of a 390px row, which measured out at a 42px box:
   the operator's "where am I" label was reduced to two or three letters and an
   ellipsis on every route. Density (spacing comfort) is also dropped here; it has no
   contrast/legibility consequence the way theme does (kept, per the a11y concern
   below) and the same control already lives on the Administration screen.
   Scoped to button[data-density], not the bare [data-density] attribute selector: boot.js
   and design-system-adapter.js both set data-density on <html> itself to drive the density
   theme, and a bare attribute selector matched that too — hiding the entire document. */
@media (max-width:640px){
  [data-guide],[data-sync],button[data-density]{display:none !important;}
}

/* 2.3 — Mobile touch-target floor (WCAG 2.2 SC 2.5.8).
   Icon buttons render at 38 × 38 px by design on desktop. On touch viewports
   (≤ 900 px) the tap target must be at least 44 × 44 px via padding rather than
   by growing the visible icon, so the visual design is preserved. */
@media (max-width:900px){
  .dgo-iconbtn{
    min-inline-size:44px;
    min-block-size:44px;
  }
}

/* 2.4 — dvh: the max-height:640px fallback block (line ~195) overrides the
   authoritative dvh block (lines ~399-403). Re-assert dvh here so the
   non-dvh rule cannot leak through if the cascade order is ever reorganised. */
@media (max-height:640px){
  .dgo-shell-grid{block-size:100dvh;max-block-size:100dvh;height:100dvh;}
}

/* 2.5 — Sidebar drawer top offset: when ministry bar is hidden (max-height:640px),
   the drawer inset-top must be 0, not 26px, so it fills to the viewport top.
   (Already set at line ~195 but also guarded here for specificity robustness.) */
@media (max-height:640px){
  .dgo-sidebar{inset-block-start:0;}
}

/* Dual-spine triage (D2) and intake feed inventory (D4).
   The AI panel is deliberately quieter than the form beside it: a left rule and a recessed
   surface mark it as something to read, not the thing that acts. Making it look like a peer
   of the human form is how a design that says "advisory" reads as "authoritative". */
.ai-spine{border-left:3px solid var(--bd);padding-left:12px}
.ai-spine .action-row:last-of-type{border-bottom:0}
.feed-group{padding:6px 0}
.feed-group + .feed-group{border-top:1px solid var(--bd);margin-top:8px}
.feed-group .eyebrow{color:var(--mut);font-weight:700;margin-bottom:4px}

/* ── Route pending indicator (finding 06) ────────────────────────────────────────────
   Set by core/router.js only once a mount has taken longer than PENDING_AFTER_MS, so a
   route that resolves from state never flashes a bar. Anchored to .dgo-workarea rather
   than to .dgo-main because .dgo-main is now the scroller — a bar inside it would scroll
   away from the top of the viewport as soon as the user moved. */
.dgo-workarea{position:relative;}
dgo-shell[data-route-pending] .dgo-workarea::after{
  content:"";
  position:absolute;
  inset-block-start:var(--dgo-shell-topbar-h);
  inset-inline:0;
  block-size:3px;
  z-index:var(--dgo-z-sticky,100);
  background:linear-gradient(90deg,
    transparent 0%,
    var(--dgo-color-action-primary,#05583B) 40%,
    var(--dgo-color-action-accent,#17B255) 60%,
    transparent 100%);
  background-size:40% 100%;
  background-repeat:no-repeat;
  animation:dgoRoutePending 1s linear infinite;
}
@keyframes dgoRoutePending{from{background-position:-40% 0}to{background-position:140% 0}}
@media (prefers-reduced-motion:reduce){
  dgo-shell[data-route-pending] .dgo-workarea::after{
    animation:none;
    background:var(--dgo-color-action-accent,#17B255);
    opacity:.85;
  }
}
/* The skeleton overlay itself — hidden until the shell carries data-route-pending, then
   covers the stale outlet completely so a fast-acting operator cannot read (or act on) a
   number that belongs to the route being left. Sits above .dgo-main, below the topbar. */
.dgo-route-loading{display:none;position:absolute;inset-block:var(--dgo-shell-topbar-h) 0;inset-inline:0;z-index:4;background:var(--dgo-color-surface-page,#fff);padding:26px;overflow:hidden}
dgo-shell[data-route-pending] .dgo-route-loading{display:block}
.dgo-route-loading__bar{width:220px;height:22px;border-radius:var(--dgo-radius-control,6px);background:var(--dgo-color-surface-sunken,#f4f7f4);margin-bottom:22px;animation:dgoSkeletonPulse 1.4s ease-in-out infinite}
.dgo-route-loading__row{display:flex;align-items:center;gap:14px;margin-bottom:18px}
.dgo-route-loading__row>span{flex:none;width:40px;height:40px;border-radius:var(--dgo-radius-card,10px);background:var(--dgo-color-surface-sunken,#f4f7f4);animation:dgoSkeletonPulse 1.4s ease-in-out infinite}
.dgo-route-loading__row>div{flex:1;min-width:0;display:flex;flex-direction:column;gap:8px}
.dgo-route-loading__row>div>i{display:block;height:12px;border-radius:4px;background:var(--dgo-color-surface-sunken,#f4f7f4);font-style:normal;animation:dgoSkeletonPulse 1.4s ease-in-out infinite}
.dgo-route-loading__row>div>i:first-child{width:60%}
.dgo-route-loading__row>div>i:last-child{width:88%}
@keyframes dgoSkeletonPulse{0%,100%{opacity:.55}50%{opacity:1}}
@media (prefers-reduced-motion:reduce){.dgo-route-loading__bar,.dgo-route-loading__row>span,.dgo-route-loading__row>div>i{animation:none;opacity:.75}}

/* ── Notification centre (finding 03) ────────────────────────────────────────────────
   The durable half of the feedback channel. The toast host above is unchanged and still
   carries the at-a-glance signal; this is where every message is kept afterwards. */
.dgo-notify-trigger{position:relative;}
.dgo-notify-badge{
  position:absolute;
  inset-block-start:2px;
  inset-inline-end:2px;
  min-inline-size:16px;
  block-size:16px;
  padding:0 4px;
  border-radius:999px;
  background:var(--dgo-color-danger-strong-bg,#b3261e);
  color:var(--dgo-color-danger-strong-fg,#fff);
  font:800 10px/16px var(--dgo-family-sans,Inter,system-ui);
  text-align:center;
}
.dgo-notify-panel{
  position:fixed;
  inset-block-start:calc(var(--dgo-shell-ministry-h) + var(--dgo-shell-topbar-h) + 6px);
  inset-inline-end:14px;
  z-index:1200;
  inline-size:min(400px,calc(100vw - 28px));
  max-block-size:min(60vh,560px);
  display:flex;
}
.dgo-notify-panel[hidden]{display:none;}
.dgo-notify-panel>section{
  display:flex;
  flex-direction:column;
  min-block-size:0;
  inline-size:100%;
  background:var(--dgo-card-bg,#fff);
  border:1px solid var(--dgo-card-border,#dfe7e2);
  border-radius:16px;
  box-shadow:var(--dgo-shadow-5,0 18px 50px rgba(0,0,0,.18));
  overflow:hidden;
}
.dgo-notify-panel header{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  padding:12px 14px;
  border-bottom:1px solid var(--dgo-card-border,#dfe7e2);
  flex:0 0 auto;
}
.dgo-notify-panel header h2{margin:0;font-family:var(--dgo-family-display,Outfit,system-ui);font-size:15px;}
.dgo-notify-panel header div{display:flex;align-items:center;gap:8px;}
.dgo-notify-panel ol{
  margin:0;
  padding:6px;
  list-style:none;
  overflow-y:auto;
  overscroll-behavior:contain;
  min-block-size:0;
}
.dgo-notify-item{
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  gap:10px;
  align-items:start;
  padding:10px 12px;
  border-radius:10px;
  border-inline-start:3px solid var(--dgo-color-border-default,#dfe7e2);
}
.dgo-notify-item + .dgo-notify-item{margin-block-start:4px;}
.dgo-notify-item p{margin:0;font-size:13px;line-height:1.45;overflow-wrap:anywhere;}
.dgo-notify-item small{display:block;margin-block-start:4px;font-size:11px;color:var(--dgo-color-fg-muted,#626a64);}
.dgo-notify-item--success{border-inline-start-color:var(--dgo-color-action-accent,#17B255);}
.dgo-notify-item--warn{border-inline-start-color:var(--dgo-color-warning-strong-bg,#a87500);}
.dgo-notify-item--error{border-inline-start-color:var(--dgo-color-danger-strong-bg,#b3261e);}
.dgo-notify-item.is-unread{background:var(--dgo-color-surface-sunken,#f4f7f4);}
.dgo-notify-item.is-unread p{font-weight:700;}
.dgo-notify-empty{padding:22px 14px;color:var(--dgo-color-fg-muted,#626a64);font-size:13px;line-height:1.5;}
@media (max-width:640px){
  .dgo-notify-panel{inset-inline:10px;inline-size:auto;}
}
/* Overflow menu (D-6) — same fixed-popover pattern as .dgo-notify-panel just above
   (same anchor calc, card tokens, shadow token), sized and z-indexed to match since
   the two are mutually exclusive and never visible together. */
.dgo-more-menu{
  position:fixed;
  inset-block-start:calc(var(--dgo-shell-ministry-h) + var(--dgo-shell-topbar-h) + 6px);
  inset-inline-end:14px;
  z-index:1200;
  inline-size:min(268px,calc(100vw - 24px));
  background:var(--dgo-card-bg,#fff);
  border:1px solid var(--dgo-card-border,#dfe7e2);
  border-radius:12px;
  box-shadow:var(--dgo-shadow-5,0 18px 50px rgba(0,0,0,.18));
  overflow:hidden;
}
.dgo-more-menu[hidden]{display:none;}
.dgo-more-menu__item{
  width:100%;
  display:flex;
  align-items:center;
  gap:10px;
  min-height:44px;
  padding:10px 14px;
  border:0;
  border-bottom:1px solid var(--dgo-card-border,#dfe7e2);
  background:transparent;
  color:inherit;
  font:500 12.5px/1.3 var(--dgo-family-sans,Inter,system-ui);
  cursor:pointer;
  text-align:left;
}
.dgo-more-menu__item:last-child{border-bottom:0;}
.dgo-more-menu__item:hover{background:var(--dgo-color-surface-sunken,#f4f7f4);}
.dgo-more-menu__item span{flex:1 1 auto;min-width:0;}
.dgo-more-menu__item small{
  font:600 10px/1 Outfit,sans-serif;
  letter-spacing:.08em;
  text-transform:uppercase;
  color:var(--dgo-color-fg-muted,#626a64);
  white-space:nowrap;
}

/* I-01 — related-workspace strip. The twenty guided routes are declared as handoffs of a
   visible workspace; this is where that declaration becomes a link the user can see. It
   sits between the work area and the footer so it is present on every screen without any
   module having to render it. */
.dgo-related{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:8px 16px;border-top:1px solid var(--bd);background:var(--sunken,var(--s));min-height:var(--dgo-control-target-min,44px)}
.dgo-related[hidden]{display:none}
.dgo-related__label{font:700 var(--dgo-type-floor) var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--mut);margin-right:2px}
/* Phase 6 measured 8 of 54 controls below the comfortable-density touch-target floor, and
   all eight were these links — the only interactive elements on the platform that set their
   own 32px height instead of --dgo-control-target-min. They sit in a wrap-friendly flex
   strip, so raising the floor costs nothing in layout: the strip grows by one row of
   padding, and the links keep wrapping as before. */
.dgo-related__link{display:inline-flex;align-items:center;gap:6px;min-height:var(--dgo-control-target-min,44px);padding:0 12px;border:1px solid var(--bd);border-radius:var(--rc,8px);font:600 11px var(--sans);color:var(--fg);text-decoration:none;background:var(--s)}
.dgo-related__link:hover,.dgo-related__link:focus-visible{border-color:var(--a);color:var(--p)}

/* I-20 — a filter with a visible name. Two adjacent selects both reading "All" told a
   registry officer nothing about what they filtered; a user cannot filter by something
   they cannot identify. */
.cc-filter{display:inline-flex;align-items:center;gap:6px;min-width:0}
.cc-filter>span{font:700 var(--dgo-type-floor) var(--sans);color:var(--mut);white-space:nowrap}
.cc-filter select{width:auto;min-width:110px}

/* Figma "Screens — Intake & Assignment" (2:44) page header, and the parent half of I-01.
   The exemplar splits this row: the screen's identity on the left, and on the right the two
   assignment modes that are sub-views of this workspace rather than sidebar destinations.
   It wraps to two rows below the 900px breakpoint rather than letting the pair squash against
   the note, which is the same seam the toolbar below wraps on. */
.cc-pagehead{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;margin:0 0 8px;min-width:0}
.cc-pagehead__note{margin:0;min-width:0;font-size:var(--dgo-type-floor);color:var(--mut);line-height:1.35}
.cc-subviews{display:flex;flex-wrap:wrap;align-items:center;gap:10px;flex-shrink:0}
@media (max-width:900px){
  .cc-pagehead{align-items:flex-start}
  .cc-pagehead__note,.cc-subviews{flex:1 1 100%}
}

/* I-09 — the intake toolbar wraps on a seam it chooses, not one the browser picks.
   The controls are two named groups. Above 900px they share one row, filters left and
   actions right. Below it the groups each claim a full row — filters first, then actions —
   so the primary "Log New Memo" can never be pushed against the pane edge the way it was at
   700px. `.cc-controls>*{flex-shrink:0}` earlier in this file exists to stop chips and
   buttons squashing; the two groups are containers, not controls, and must shrink. */
.cc-controls__filters,
.cc-controls__actions{display:flex;flex-wrap:wrap;align-items:center;gap:6px;min-inline-size:0;flex-shrink:1}
.cc-controls__filters{flex:1 1 min(340px,100%)}
.cc-controls__actions{flex:0 1 auto;margin-inline-start:auto;justify-content:flex-end}
@media (max-width:900px){
  .cc-controls{flex-wrap:wrap}
  .cc-controls__filters,
  .cc-controls__actions{flex:1 1 100%;margin-inline-start:0;justify-content:flex-start}
}
/* The record views. Two tabs that always carry their own labels — they used to be plain ghost
   buttons that collapsed behind an unnamed "···", which is what I-20 objects to. */
.cc-tabs{display:inline-flex;align-items:center;gap:2px;padding:2px;background:var(--sunken,var(--s));border:1px solid var(--bd);border-radius:999px;min-inline-size:0;flex-shrink:1}
.cc-tab{display:inline-flex;align-items:center;height:24px;padding:0 10px;border:0;border-radius:999px;background:none;color:var(--mut);font:700 11px var(--sans);white-space:nowrap;cursor:pointer;min-inline-size:0}
.cc-tab.active{background:var(--s);color:var(--strong);box-shadow:0 1px 3px #0b2a1f14}
.cc-tab:hover:not(.active),.cc-tab:focus-visible{color:var(--fg)}

/* H-02 — sprite icons replace the Unicode glyphs. Sized and coloured from the text they sit
   beside, which is the thing a typographic character could never be made to do reliably. */
.dgo-icon{width:1.15em;height:1.15em;flex:0 0 auto;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;vertical-align:-.15em}
.dgo-nav-icon{display:inline-flex;align-items:center;justify-content:center;width:20px;color:currentColor}
.dgo-cmdk__icon{display:inline-flex;align-items:center;justify-content:center;width:22px;color:var(--mut)}
.dgo-iconbtn .dgo-icon,.dgo-search-trigger .dgo-icon{width:16px;height:16px}

/* ============================================================
   Mobile shell tier (EXECUTION DIRECTIVE — Mobile Shell Remediation).
   Ported from "Root Platform — DGO Digital Operations.dc.html" (the shell's own
   design source, which already implements this tier against its own --topbar/--kpi/
   .dgo-row prototype markup) onto this runtime's real .dgo-ministry-bar/.dgo-topbar/
   .dgo-route-title classes and --dgo-shell-ministry-h/--dgo-shell-topbar-h tokens —
   those two feed calc() elsewhere (.dgo-shell-grid, .dgo-notify-panel), so the mobile
   tier below overrides them with new fixed values rather than `auto`.
   R-D2 (mobile shell remediation, closing pass): `(min-height:641px)` used to gate
   this tier disjoint from the existing short-landscape tier at `@media(max-height:640px)`
   above (line ~505). That left a dead zone: at e.g. 640x360, the 320px-containment rule
   below (2.2, un-height-gated) still hides [data-guide]/[data-sync]/button[data-density],
   but this tier's `--tb-more:inline-flex` never activated because min-height:641px didn't
   match — the overflow trigger that would have surfaced those controls never appeared, so
   they were simply unreachable. Removing the height guard closes that gap: the tier now
   matches everywhere the hide rule does. The one property this tier and the short-landscape
   tier both set (`--dgo-shell-ministry-h`) is resolved just below the tier's closing brace,
   without reordering either block (see the comment there).
   Breakpoint is 640px, not the directive's 620px: "2.2 — 320px topbar containment"
   (line ~944, pre-existing) already force-hides [data-guide],[data-sync] and
   button[data-density] with !important at max-width:640px. Since guide/sync are
   inline-styled (display:var(--tb-ctl)) rather than !important, a 620px tier would
   leave 621-640px where that pre-existing rule still hides them but --tb-more
   hasn't appeared yet - guide and sync would be unreachable in that band. Matching
   640px keeps every mechanism flipping at the same edge. ============================================================ */
:root{
  --tb-ctl:inline-flex;
  --tb-more:none;
}
/* Desktop bug fix (F-2): the title column was shrink-to-fit (flex:0 1 220px, app.css:529),
   which is why the route title ellipsised with ~330px of free space beside it at 1440px.
   Two things had to change together, found by testing in a real browser:
   - flex-basis:0% (not auto): with auto, the mobile topbar's flex-wrap line-fit decision
     used the title's max-content hypothetical size (~291px for the longest route label)
     rather than its post-shrink size, so it wrapped onto its own row even when there was
     room beside the hamburger once shrunk.
   - .dgo-topbar__spacer (app.css:530) is flex:1 1 auto - a second growable item that, at
     an equal flex-grow of 1, split the reclaimed space with the title roughly in half
     (title stalled back around 180px, re-ellipsizing on the "fixed" desktop case) and,
     at mobile widths, contributed a gap that alone was enough to push the title off the
     hamburger's row. It has had nothing to distribute since the title itself absorbs the
     row's leftover space; flex:0 0 0 here (unconditional - it never needs to grow at any
     width) removes it from the growth split entirely.
   With the spacer no longer competing, the title's own flex-grow does not need to be
   large - 1 is enough once it is the only growable sibling. min-width:0 still lets it
   shrink below content size when the row is genuinely tight.
   This unconditional block must come BEFORE the max-width:640px block below: same
   specificity (.dgo-route-title b[data-tb-title], 0-2-1) means source order decides,
   and a later plain rule beats an earlier conditionally-matching one regardless of
   viewport - placing it after the media query silently won the cascade at every width. */
.dgo-route-title{flex:1 1 0%;min-width:200px;max-width:none;}
.dgo-route-title b[data-tb-title]{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0;max-width:100%;}
.dgo-topbar__spacer{flex:0 0 0;}
@media(max-width:640px){
  :root{
    --dgo-shell-ministry-h:40px;
    --dgo-shell-topbar-h:106px;
    --tb-ctl:none;
    --tb-more:inline-flex;
  }
  .dgo-ministry-bar{white-space:normal;padding:5px 12px;}
  .dgo-ministry-bar__text{white-space:normal;overflow:visible;text-overflow:clip;}
  /* R-D3: !important removed. The only other declaration of .dgo-topbar's flex-wrap is the
     unconditional `flex-wrap:nowrap` in the "mobile landscape horizontal containment" block
     (line ~583 above), same specificity (0-1-0) and not !important - source order alone
     decides, and this rule sits later in the file, so it still wins at <=640px without the
     escalation. Verified in-browser: wrapping is unchanged at 320/390/640px. */
  .dgo-topbar{flex-wrap:wrap;padding:5px 12px;}
  .dgo-route-title b[data-tb-title]{white-space:normal;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;text-overflow:clip;min-width:0;max-width:100%;}
  /* F-7 (search field renders ~340px tall): height ceiling for real form fields
     stretched by a flex-column ancestor. .dgo-input__field/.dgo-select__field named
     in the directive don't exist here (D-1c selector audit) - .dgo-select__field
     does, .dgo-input is the real base-input equivalent of .dgo-input__field.
     R-D2/R-5: this used to sit inside the min-height:641px-gated tier, so short-landscape
     viewports (640x360, 600x480) never got the 44px field ceiling either. Now ungated
     with the rest of this tier, it applies at every height once width<=640px. */
  .dgo-input,.dgo-select,.dgo-select__field,input,select{min-height:36px;max-height:44px;}
  /* R-D5: .toolbar/.action-row/.form-row already wrap at this breakpoint (line ~21); these
     two never got the same rule. .dgo-toolbar has no current renderer (Toolbar() in
     shared/components.js and figmaToolbar() in core/ui.js both build it, but neither is
     called anywhere in the module set at this commit) - additive and inert today, kept for
     parity with any future consumer. .rt-toolbar is real (response-tracking's filter bar)
     but is already deliberately horizontal-scrolling, not wrapping: dgo-shell[data-route=
     "response-tracking"] .rt-toolbar sets flex-wrap:nowrap;overflow-x:auto !important
     unconditionally (line ~745), at higher specificity (0-2-1) than the bare class here
     (0-1-0), so it continues to win there by design - this rule does not override that
     route's intentional scroll behaviour, only applies where .rt-toolbar has no such
     override. */
  .dgo-toolbar,.rt-toolbar{flex-wrap:wrap;}
}
/* R-D2 4.2 — property overlap between this tier and the short-landscape tier at
   `@media(max-height:640px)` (line ~505). Only one property is set by both:
   `--dgo-shell-ministry-h` (this tier: 40px, to fit the wrapped ministry-bar text;
   short-landscape: 0px, to reclaim the row entirely). Both consumers that read the var
   directly (`.dgo-notify-panel`, `.dgo-more-menu` inset-block-start calc) need the
   short-landscape value to win whenever height<=640px, regardless of width. `.dgo-shell-grid`
   itself is not at risk — the short-landscape tier pins its block-size to a literal 100dvh
   rather than going through the var. Rule 4 (additive CSS; no reordering except the two
   named exceptions) rules out moving the earlier @media(max-height:640px) block down here,
   so the same outcome is reached additively: this new block sits after the tier above and
   is scoped to max-height:640px, so at any viewport matching both conditions it is the
   last declaration of `--dgo-shell-ministry-h` in source order and wins without reordering
   or !important. */
@media(max-height:640px){
  :root{--dgo-shell-ministry-h:0px;}
}
/* R-D1 — KPI/metric strips scroll horizontally instead of shearing their content at narrow
   widths. `data-strip` is now emitted on every element carrying class `kpis` or `cc-kpi-band`
   at this commit: core/ui.js's `kpis()` helper (the shared builder used by 14 modules),
   modules/response-tracking.js's hand-rolled `.kpis` (the one caller that doesn't go through
   the helper), and modules/home.js's `.cc-kpi-band` wrapper. Three call sites, marked.
   §3.4 fallback: `.kpis` (and `.cc-kpi-band .kpis`) computes `display:flex` at this commit
   (line 230's `.kpis,.stat-row{display:flex;flex-wrap:wrap;gap:14px}` - confirmed via a real
   browser's computed style, not just reading the cascade), never `display:grid` - every
   grid-template-columns rule elsewhere in this file targeting `.kpis` is inert dead CSS,
   left as-is per rule 4. The `div[data-strip]{grid-auto-flow:column;...}` rule below is
   therefore also inert for `.kpis`; the flex equivalent directly below it is what actually
   applies: nowrap plus a flex-basis on children, matching the 64%-partial-next-card intent
   without grid.
   `.cc-kpi-band` itself also carries `data-strip` per the directive's literal "kpis or
   cc-kpi-band" scope, but it wraps a single `.kpis` child and is `display:block` (line
   ~907) - the rules below are inert on it (nothing to scroll at that level) and harmless. */
@media(max-width:640px){
  [data-strip]{overflow-x:auto;overflow-y:hidden;scrollbar-width:none;-webkit-overflow-scrolling:touch;padding-bottom:2px}
  [data-strip]::-webkit-scrollbar{display:none}
  [data-strip]>*{flex:0 0 auto}
  div[data-strip]{grid-auto-flow:column;grid-template-columns:none;grid-auto-columns:minmax(150px,64%)}
  .kpis[data-strip]{flex-wrap:nowrap}
  .kpis[data-strip]>*{flex:0 0 64%;min-width:150px}
}
.dgo-related__link .dgo-icon{width:14px;height:14px}

/* Chip colour contrast (deferred item, mobile shell directive §1).
   Checked every chip/pill/status pairing that reads the *-subtle-bg/*-subtle-fg tokens
   (.dgo-status, .pill, .chip, .tag, .dgo-pill--success, .dgo-alert--success, .cc-stat,
   .dgo-metric__delta--up - grep confirms this is the complete consumer set) against WCAG
   2.2 AA (4.5:1) in every theme this platform ships:
     light   success 5.44:1 · info 8.37:1 · warning 8.70:1 · danger 9.56:1  - all pass
     dark    success 7.75:1 · info 6.74:1 · warning 8.09:1 · danger 6.84:1  - all pass
     (dark bg is rgba(...,0.18-0.20) composited over surface-page/-raised/-sunken;
     checked against all three - none drop below 6.7:1)
     hardcoded .dgo-source--* (not token-driven): 5.02-6.93:1 across the board - all pass
   No pairing fails AA anywhere. There is nothing to fix at the ratio level.

   What IS broken: tokens.theme-hc.css declares its own bold status colours
   (--dgo-color-status-{pending,routed,replied,action}-{bg,fg}, targeting AAA per that
   file's own header comment) but every consumer above reads --dgo-color-{success,
   warning,danger,info}-subtle-{bg,fg} instead - a token HC theme never overrides. HC mode
   silently inherits light theme's values rather than its own. Three of the four are
   byte-identical to light anyway (warning/info/danger), so only success is a measurable
   change: light's pair passes AA at 5.44:1; HC's own status-replied pair reaches AAA at
   9.35:1, which is the whole point of a theme whose stated target is AAA where possible.
   styles/dgo-design-system/** stays frozen (per the mobile shell directive's own rule 3,
   followed here too) - wired here instead of by editing tokens.theme-hc.css. */
[data-theme="hc"]{
  --dgo-color-success-subtle-bg: #C2EED2;
  --dgo-color-success-subtle-fg: #07401D;
  --dgo-color-warning-subtle-bg: #FBF1D8;
  --dgo-color-warning-subtle-fg: #5A3F00;
  --dgo-color-info-subtle-bg:    #E6F0F8;
  --dgo-color-info-subtle-fg:    #054871;
  --dgo-color-danger-subtle-bg:  #FBE7EB;
  --dgo-color-danger-subtle-fg:  #780820;
}

/* R3-D1 — bound the topbar to one control row (closes O-1 / R-D4).
   shared/shell.js now wraps the seven trailing controls (guide, sync, overflow, density,
   theme, notify, persona) in .dgo-topbar__controls, so .dgo-topbar's own flex-wrap can only
   ever wrap that whole group to a second row — never one control at a time onto a third or
   later row, which is how the topbar's fixed --dgo-shell-topbar-h could be exceeded.
   Baseline (unconditional) rules recreate exactly the spacing the seven controls had as
   direct .dgo-topbar children, at every width .dgo-topbar itself sets a gap for (12px
   default, 8px <=1200px, 6px <=640px) — the wrapper is transparent to desktop layout. */
.dgo-topbar__controls{display:flex;flex-wrap:nowrap;align-items:center;gap:12px;min-inline-size:0;}
@media(max-width:1200px){
  .dgo-topbar__controls{gap:8px;}
}
@media(max-width:640px){
  .dgo-topbar__controls{gap:6px;}
}
/* Approach chosen for 3.3 (guarantee reachability under compression): .dgo-topbar itself
   carries an unconditional `overflow:hidden !important` (line ~528) that a non-!important
   overflow-x:auto on .dgo-topbar could never beat without adding a second !important, which
   this brief's rule 5 forbids. .dgo-topbar__controls is a class that rule does not name, so
   scrolling it instead is unopposed - the wrapper approach was chosen for this reason, not
   arbitrarily. Each child gets flex:0 0 auto so the scroll container is horizontal reachability,
   not shrink-to-clip. */
@media(max-width:640px){
  .dgo-topbar__controls{overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch;scrollbar-width:none;max-inline-size:100%;}
  .dgo-topbar__controls::-webkit-scrollbar{display:none;}
  .dgo-topbar__controls>*{flex:0 0 auto;}
}

/* R3-D3 — persona popover (closes O-3). Reuses .dgo-more-menu/.dgo-more-menu__item for the
   panel chrome and its one action (Close); this rule is only the identity row's own layout,
   which those classes don't already provide. */
.dgo-persona-panel__identity{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--dgo-card-border,#dfe7e2);}
.dgo-persona-panel__identity b,.dgo-persona-panel__identity small{display:block;text-align:left;}
.dgo-persona-panel__identity small{font-size:11px;color:var(--dgo-color-fg-muted,#626a64);overflow-wrap:anywhere;}

/* R3-D4 — touch targets (closes O-4). .dgo-btn already carries an unconditional literal
   min-height:44px (line ~229) and .dgo-iconbtn already carries a literal 44px floor at
   <=900px (2.3, line ~965) - both measured and confirmed at or above 40px already, so
   neither is touched here (see the R3-D4 report for the rule-already-satisfies-it
   citations). What IS live and under 40px on its smallest axis in the mobile shell:
   platform-authority.css (frozen) sizes .dgo-search-trigger/.dgo-persona-button/
   .dgo-sidebar__item/.dgo-related__link/summary/button.chip/a.chip/a.skip off
   --dgo-control-target-min, and tokens.enhanced.css (frozen) sets that token to
   --dgo-control-target-compact (36px) whenever [data-density="compact"]. Measured
   live: .dgo-persona-button renders 36x40px in compact density at 390px width - 4px
   under the floor this directive sets. Scoped to <=640px only (rule 6.3: "do not alter
   desktop sizing"); the identical gap exists above 640px too but fixing it there would be
   a desktop change this brief does not authorise, so it is reported, not fixed here. */
@media(max-width:640px){
  [data-density="compact"]{--dgo-control-target-min:40px;}
}

/* ============================================================
   DGO v2.0 — Base typography + page chrome
   ============================================================ */

/* External Google Fonts @import removed: a render-/script-blocking external stylesheet stalled
   boot ~13s on any network that cannot reach fonts.googleapis.com (offline / air-gapped / firewalled).
   Typography falls back to the system stack in --dgo-family-*; self-host Outfit/Inter in /fonts/ to
   restore exact brand faces without an external dependency. */

html, body {
  font-family: var(--dgo-family-sans);
  font-size: var(--dgo-type-body);
  line-height: var(--dgo-lh-150);
  color: var(--dgo-color-fg-default);
  background: var(--dgo-color-surface-page);
}

/* Colour scheme is the one non-token declaration the theme sheets used to carry, and
   platform-authority.css declared it a second time from the `overrides` layer — so the theme
   files never actually decided it. Phase 1 gives it a single owner here: one rule per scheme,
   in `base`, where element styling belongs. The values are unchanged, including `hc`, which
   resolved to `light` before because the overrides copy outranked it. */
:root, [data-theme="light"], [data-theme="hc"] { color-scheme: light; }
[data-theme="dark"] { color-scheme: dark; }

/* Headings */
h1, h2, h3, h4, h5, h6,
.dgo-h1, .dgo-h2, .dgo-h3, .dgo-h4, .dgo-h5, .dgo-h6,
.dgo-display, .dgo-display-xl, .dgo-display-xxl {
  font-family: var(--dgo-family-display);
  font-weight: var(--dgo-wt-700);
  letter-spacing: var(--dgo-tr-tight);
  line-height: var(--dgo-lh-120);
  color: var(--dgo-color-fg-strong);
  text-wrap: balance;
}

.dgo-display-xxl { font-size: var(--dgo-type-display-xxl); font-weight: var(--dgo-wt-800); letter-spacing: var(--dgo-tr-tightest); }
.dgo-display-xl  { font-size: var(--dgo-type-display-xl);  font-weight: var(--dgo-wt-800); letter-spacing: var(--dgo-tr-tightest); }
.dgo-display     { font-size: var(--dgo-type-display);     font-weight: var(--dgo-wt-700); letter-spacing: var(--dgo-tr-tight); }
h1, .dgo-h1 { font-size: var(--dgo-type-h1); }
h2, .dgo-h2 { font-size: var(--dgo-type-h2); }
h3, .dgo-h3 { font-size: var(--dgo-type-h3); }
h4, .dgo-h4 { font-size: var(--dgo-type-h4); }
h5, .dgo-h5 { font-size: var(--dgo-type-body-lg); }
h6, .dgo-h6 { font-size: var(--dgo-type-body); letter-spacing: var(--dgo-tr-wide); text-transform: uppercase; }

/* Body */
p, .dgo-body { font-size: var(--dgo-type-body); line-height: var(--dgo-lh-150); text-wrap: pretty; }
.dgo-body-lg { font-size: var(--dgo-type-body-lg); line-height: var(--dgo-lh-150); }
.dgo-body-sm { font-size: var(--dgo-type-body-sm); line-height: var(--dgo-lh-140); }
.dgo-caption { font-size: var(--dgo-type-caption); line-height: var(--dgo-lh-140); color: var(--dgo-color-fg-muted); }
.dgo-overline {
  font-size: var(--dgo-type-caption);
  font-weight: var(--dgo-wt-600);
  letter-spacing: var(--dgo-tr-widest);
  text-transform: uppercase;
  color: var(--dgo-color-fg-muted);
}

a, .dgo-link {
  color: var(--dgo-color-fg-link);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  text-decoration-color: color-mix(in srgb, currentColor 40%, transparent);
  transition: color var(--dgo-motion-state),
              text-decoration-color var(--dgo-motion-state);
}
a:hover, .dgo-link:hover {
  color: var(--dgo-color-fg-link-hover);
  text-decoration-color: currentColor;
}
/* Keyboard parity: mirror the hover affordance for focus-visible. */
.dgo-link:focus-visible {
  color: var(--dgo-color-fg-link-hover);
  text-decoration-color: currentColor;
}

strong, b { font-weight: var(--dgo-wt-600); color: var(--dgo-color-fg-strong); }
small { font-size: var(--dgo-type-caption); color: var(--dgo-color-fg-muted); }

code, kbd, samp, pre {
  font-family: var(--dgo-family-mono);
  font-size: 0.92em;
}

/* Selection */
::selection {
  background: color-mix(in srgb, var(--dgo-smart-400) 35%, transparent);
  color: var(--dgo-color-fg-strong);
}

/* Accessibility utilities */
.dgo-visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.dgo-skip-link {
  position: absolute;
  inset-inline-start: var(--dgo-s-3);
  inset-block-start: var(--dgo-s-3);
  padding: var(--dgo-s-2) var(--dgo-s-3);
  background: var(--dgo-color-surface-page);
  color: var(--dgo-color-fg-link);
  border: 2px solid var(--dgo-color-border-focus);
  border-radius: var(--dgo-radius-control);
  font-weight: var(--dgo-wt-600);
  transform: translateY(-200%);
  transition: transform var(--dgo-motion-state);
  z-index: var(--dgo-z-toast);
}
.dgo-skip-link:focus { transform: translateY(0); }

/* Print-friendly defaults */
@media print {
  body { background: #fff; color: #000; }
  a { color: #000; text-decoration: underline; }
  a[href^="http"]::after { content: " (" attr(href) ")"; font-size: 0.85em; }
  .dgo-no-print { display: none !important; }
}

/* Container */
.dgo-container {
  width: 100%;
  max-width: var(--dgo-c-wide);
  margin-inline: auto;
  padding-inline: var(--dgo-s-6);
}
.dgo-container--narrow  { max-width: var(--dgo-c-narrow); }
.dgo-container--text    { max-width: var(--dgo-c-text); }
.dgo-container--content { max-width: var(--dgo-c-content); }
.dgo-container--full    { max-width: var(--dgo-c-full); }

@media (max-width: 640px) {
  .dgo-container { padding-inline: var(--dgo-s-4); }
}

/* =========================================================
   NITDA Design System — Brand element styling
   Source: NITDA Brand Guidelines 2020 (uploads/NITDA Brand Manual ...)

   Split out of colors_and_type.css by Phase 1. That file is imported into the `tokens` layer,
   the lowest in the cascade, so every element rule it carried was outranked by `base` and
   above and could never take effect on its own terms. The rules were not deleted — some of
   them are the only declaration of their property — so they live here instead, in a `brand`
   layer that sits directly above `tokens` and directly below `base`.

   Nothing in `tokens` styles elements, so raising these rules out of it changes no outcome:
   the sheets that beat them before (base, layout, components, overrides) still beat them, and
   the sheets they never competed with still contain no element styling. colors_and_type.css
   keeps the custom properties; this sheet keeps the styling that uses them.

   The DGO design system (`base.css` and below) remains authoritative wherever the two meet.
   ========================================================= */

/* H-04 — the brand monospace, self-hosted. The internal platform shipped no fonts at all, so a
   reference code that the public portal renders in Cascadia Mono fell through to whatever
   `ui-monospace` resolves to on the operator's machine: the same design system, the same
   reference, two different faces on two screens of the same programme. The file here is the
   portal's own document-portal/ds/fonts/CascadiaMono-Regular.woff2, byte for byte.
   No CDN — this runtime has a no-runtime-dependency commitment; the face is served from
   assets/fonts/ alongside everything else the package carries. `font-display:swap` so a slow
   decode never blanks a reference code. The URL is relative to this stylesheet
   (styles/dgo-design-system/), hence the two levels up. */
@font-face {
  font-family: "Cascadia Mono";
  src: url("../../assets/fonts/CascadiaMono-Regular.woff2") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

/* H-04, the other half — the faces exist, but nothing on this platform asked for them. Every
   reference number, tracking ID and idempotency key is a string an operator reads aloud, types
   into another system, or compares character by character against a paper file: 0/O and 1/l
   have to be distinguishable, and the digits have to line up in a column. The portal already
   sets its reference codes in the brand monospace; `.dgo-ref` is the same contract here, and
   the shared helpers that emit references (core/ui.js table/badge callers, the reference
   minter's output) carry it so the two platforms print the same code the same way. */
.dgo-ref, .dgo-mono {
  font-family: var(--dgo-family-mono, var(--font-mono));
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
}

/* =========================================================
   SEMANTIC TYPE STYLES
   Use these directly on elements for consistent typography.
   ========================================================= */

html { font-family: var(--font-body); color: var(--fg-default); background: var(--bg-default); }
body { margin: 0; font-size: var(--fs-body); line-height: var(--lh-normal); -webkit-font-smoothing: antialiased; }

h1, .h1 {
  font-family: var(--font-display);
  font-size: var(--fs-h1);
  font-weight: var(--fw-bold);
  line-height: var(--lh-tight);
  letter-spacing: var(--tr-tight);
  color: var(--nitda-deep-green);
  margin: 0 0 var(--space-4);
}

h2, .h2 {
  font-family: var(--font-display);
  font-size: var(--fs-h2);
  font-weight: var(--fw-semibold);
  line-height: var(--lh-snug);
  letter-spacing: var(--tr-tight);
  color: var(--nitda-deep-green);
  margin: 0 0 var(--space-3);
}

h3, .h3 {
  font-family: var(--font-display);
  font-size: var(--fs-h3);
  font-weight: var(--fw-semibold);
  line-height: var(--lh-snug);
  color: var(--nitda-ink-900);
  margin: 0 0 var(--space-3);
}

h4, .h4 {
  font-family: var(--font-display);
  font-size: var(--fs-h4);
  font-weight: var(--fw-semibold);
  line-height: var(--lh-snug);
  color: var(--nitda-ink-900);
  margin: 0 0 var(--space-2);
}

.display, .display-l, .display-xl {
  font-family: var(--font-display);
  font-weight: var(--fw-bold);
  line-height: var(--lh-tight);
  letter-spacing: var(--tr-tight);
  color: var(--nitda-deep-green);
}
.display    { font-size: var(--fs-display); }
.display-l  { font-size: var(--fs-display-l); }
.display-xl { font-size: var(--fs-display-xl); font-weight: var(--fw-black); }

p, .body {
  font-family: var(--font-body);
  font-size: var(--fs-body);
  line-height: var(--lh-relaxed);
  color: var(--fg-default);
  margin: 0 0 var(--space-3);
  text-wrap: pretty;
}
.body-lg { font-size: var(--fs-body-lg); line-height: var(--lh-relaxed); }
.body-sm { font-size: var(--fs-body-sm); line-height: var(--lh-normal); }

.caption {
  font-family: var(--font-body);
  font-size: var(--fs-caption);
  color: var(--fg-muted);
  line-height: var(--lh-normal);
}

.overline {
  font-family: var(--font-sans);
  font-size: var(--fs-overline);
  font-weight: var(--fw-semibold);
  text-transform: uppercase;
  letter-spacing: var(--tr-overline);
  color: var(--nitda-smart-green);
}

.eyebrow {
  font-family: var(--font-sans);
  font-size: var(--fs-body-sm);
  font-weight: var(--fw-semibold);
  text-transform: uppercase;
  letter-spacing: var(--tr-wide);
  color: var(--nitda-deep-green);
}

a, .link {
  color: var(--fg-link);
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-thickness: 1px;
  transition: color var(--dur-fast) var(--ease-standard);
}
a:hover, .link:hover { color: var(--fg-link-hover); }
/* Keyboard parity (SC 2.4.7/2.4.11): the pointer affordance must also be a focus affordance. */
.link:focus-visible { color: var(--fg-link-hover); }

code, kbd, samp, pre {
  font-family: var(--font-mono);
  font-size: 0.92em;
}
code {
  background: var(--bg-muted);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
}

hr {
  border: 0;
  border-top: 1px solid var(--border-default);
  margin: var(--space-6) 0;
}

::selection { background: var(--nitda-smart-green-40); color: var(--nitda-deep-green); }

/* =========================================================
   NITDA Design System — Colors & Type
   Source: NITDA Brand Guidelines 2020 (uploads/NITDA Brand Manual ...)
   ========================================================= */

/* ---- Webfonts ----
   Brand fonts:
     • Alwyn New (Light, Regular, Bold, Light Italic) — Mark Simonson Studio (commercial).
       Substituted with "Outfit" from Google Fonts (geometric sans, similar
       proportions, full weight range). Replace with the licensed Alwyn New
       webfont in /fonts/ when available.
     • Verdana — system font, used for body/long-form content.
*/
/* External Google Fonts @import removed (blocking boot on restricted networks) — see base.css note.
   Brand faces fall back to the system stack; self-host Outfit in /fonts/ to restore exact typography. */

/* Element styling and the @font-face rule moved to brand-type.css (`brand` layer) by Phase 1:
   this sheet is imported into `tokens`, the lowest layer, where no element rule can win.
   Custom properties are all that belong here. */

:root {
  /* =====================================================
     COLORS
     ===================================================== */

  /* --- Primary: Deep Green (PANTONE 7484C) --- */
  --nitda-deep-green:        #05583B;   /* R5 G88 B59 — flagship brand color */
  --nitda-deep-green-80:     #377962;   /* 80% tint */
  --nitda-deep-green-40:     #9BBCAE;   /* 40% tint */
  --nitda-deep-green-20:     #CDDDD7;   /* derived for surfaces */
  --nitda-deep-green-10:     #E6EEEB;   /* derived for surfaces */
  --nitda-deep-green-deep:   #033F2A;   /* derived hover/press, ~10% darker */

  /* --- Secondary: Smart Green (PANTONE 354C) --- */
  --nitda-smart-green:       #17B255;   /* R23 G178 B85 — accent, CTAs, success */
  --nitda-smart-green-80:    #45C176;   /* 80% tint */
  --nitda-smart-green-40:    #A2E0BB;   /* 40% tint */
  --nitda-smart-green-deep:  #119143;   /* derived hover/press */

  /* --- Neutrals --- */
  --nitda-black:             #373435;   /* brand black, R55 G52 B53 */
  --nitda-black-80:          #5F5C5D;
  --nitda-black-40:          #AFADAE;
  --nitda-white:             #FFFFFF;

  /* Extended neutrals for UI work (derived).

     Phase 5a removed levels 50-800. They were a second, unthemed neutral ladder alongside
     --dgo-ink-*, and once the semantic aliases below were bound to the DGO semantics nothing
     referenced any of them: 400, 700 and 800 were already carried in tests/baseline.json as
     `css-token-orphan`, and the rest joined them. Level 900 stays because brand-type.css still
     paints h3/h4 with it. Use --dgo-ink-* for new UI neutrals; the brand neutrals above
     (--nitda-black*, --nitda-white) remain the brand-manual reference. */
  --nitda-ink-900:           #1B1A1A;

  /* --- Tertiary (Coat of Arms only — DO NOT use in general design) --- */
  --nitda-coa-red:           #C8102E;
  --nitda-coa-yellow:        #FFD200;

  /* --- Semantic --- */
  --nitda-success:           var(--nitda-smart-green);
  --nitda-warning:           #E1A100;
  --nitda-danger:            #C8102E;
  --nitda-info:              #0B6BB0;

  /* --- Surface / Foreground tokens ---

     These are SEMANTIC aliases, not brand constants, and brand-type.css paints bare elements
     with them: `html` reads --bg-default/--fg-default, `p` reads --fg-default, `a` reads
     --fg-link, `code` reads --bg-muted, `hr` reads --border-default.

     They used to resolve to the --nitda-* primitives above, which are fixed by the brand
     guideline and are therefore the same value in every theme. Nothing re-bound them for
     `dark` or `hc`, so every paragraph in the runtime rendered #1B1A1A regardless of theme —
     1.03:1 on the dark card, i.e. invisible. They are bound to the DGO semantics here for the
     same reason tokens.legacy-bridge.css binds the legacy short vars: two vocabularies that
     mean the same thing must not be able to diverge.

     Every binding below is byte-identical in `light` to the --nitda-* value it replaces except
     the four marked, which are recorded in tests/README.md. The --nitda-* brand primitives
     themselves are untouched: they remain the brand palette. */
  --bg-default:              var(--dgo-color-surface-page);      /* #FFFFFF */
  --bg-subtle:               var(--dgo-color-surface-muted);     /* #FAF9F9 -> #FAFAF9, 0 consumers */
  --bg-muted:                var(--dgo-color-surface-sunken);    /* #F4F2F3 -> #F5F4F4, see README */
  --bg-inverse:              var(--dgo-color-surface-brand);     /* #05583B */
  /* No DGO counterpart: the semantics stop at surface-brand, so this alias keeps the brand
     primitive and stays unthemed. It has no consumer; adding one needs a DGO token first. */
  --bg-inverse-strong:       var(--nitda-deep-green-deep);

  --fg-default:              var(--dgo-color-fg-default);        /* #1B1A1A */
  --fg-muted:                var(--dgo-color-fg-muted);          /* #5F5C5D */
  --fg-subtle:               var(--dgo-color-fg-subtle);         /* #807D7E */
  --fg-on-green:             var(--nitda-white);                 /* white on green is white in
                                                                    every theme; keeps the brand
                                                                    white referenced */
  --fg-on-light:             var(--dgo-color-fg-brand);          /* #05583B */
  --fg-link:                 var(--dgo-color-fg-link);           /* #05583B */
  --fg-link-hover:           var(--dgo-color-fg-link-hover);     /* #17B255 -> #119143, see README */

  --border-default:          var(--dgo-color-border-default);    /* #E8E6E7 */
  --border-strong:           var(--dgo-color-border-strong);     /* #D6D4D5 -> #807D7E, 0 consumers */
  --border-on-green:         var(--dgo-color-border-on-brand);   /* .18 -> .20 alpha, 0 consumers */

  /* =====================================================
     TYPE
     ===================================================== */

  /* Families */
  --font-display:  "Outfit", "Alwyn New", "Helvetica Neue", Arial, sans-serif;
  --font-sans:     "Outfit", "Alwyn New", "Helvetica Neue", Arial, sans-serif;
  --font-body:     Verdana, Geneva, "DejaVu Sans", sans-serif;
  --font-mono:     ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;

  /* Type scale — aligned to the Figma foundations scale (Foundations — Type & Spacing):
     Display XXL 60/66, Display XL 48/53, Display 40/44, H1 33/40 (page heading — matches
     nav label + tab title), H2 28/34, H3 23/30, H4 19/25. Was 72/56/44/36/28/22/18, an
     unrelated scale nothing else in the design system referenced. */
  --fs-display-xl:  60px;
  --fs-display-l:   48px;
  --fs-display:     40px;
  --fs-h1:          33px;
  --fs-h2:          28px;
  --fs-h3:          23px;
  --fs-h4:          19px;
  --fs-body-lg:     18px;
  --fs-body:        16px;
  --fs-body-sm:     14px;
  --fs-caption:     12px;
  --fs-overline:    11px;

  /* Line heights */
  --lh-tight:       1.1; /* @kind font */
  --lh-snug:        1.25; /* @kind font */
  --lh-normal:      1.4; /* @kind font */
  --lh-relaxed:     1.6; /* @kind font */

  /* Weights */
  --fw-light:       300; /* @kind font */
  --fw-regular:     400; /* @kind font */
  --fw-medium:      500; /* @kind font */
  --fw-semibold:    600; /* @kind font */
  --fw-bold:        700; /* @kind font */
  --fw-black:       800; /* @kind font */

  /* Tracking (typographic letter-spacing) */
  --tr-tight:       -0.02em; /* @kind font */
  --tr-normal:       0em; /* @kind font */
  --tr-wide:         0.04em; /* @kind font */
  --tr-overline:     0.12em; /* @kind font */

  /* =====================================================
     SPACING & RADIUS
     ===================================================== */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;
  --space-8: 64px;
  --space-9: 96px;

  --radius-xs: 2px;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-pill: 999px;

  /* =====================================================
     ELEVATION
     ===================================================== */
  --shadow-xs: 0 1px 2px rgba(5, 88, 59, 0.06);
  --shadow-sm: 0 1px 3px rgba(5, 88, 59, 0.08), 0 1px 2px rgba(5, 88, 59, 0.06);
  --shadow-md: 0 4px 12px rgba(5, 88, 59, 0.10), 0 2px 4px rgba(5, 88, 59, 0.06);
  --shadow-lg: 0 12px 28px rgba(5, 88, 59, 0.14), 0 4px 8px rgba(5, 88, 59, 0.06);
  --shadow-xl: 0 24px 48px rgba(5, 88, 59, 0.18);
  --shadow-focus: 0 0 0 3px rgba(23, 178, 85, 0.35);

  /* =====================================================
     MOTION
     ===================================================== */
  --ease-standard: cubic-bezier(0.2, 0, 0, 1); /* @kind other */
  --ease-emphasis: cubic-bezier(0.3, 0, 0, 1.2); /* @kind other */
  --dur-fast:   120ms; /* @kind other */
  --dur-base:   200ms; /* @kind other */
  --dur-slow:   320ms; /* @kind other */
}

/* ============================================================
   DGO Design System v2.0 — Component Library
   ============================================================
   Organised by family; BEM under `.dgo-` namespace.
   Every value references a token — no hard-coded hex/px/ms.
   ------------------------------------------------------------
   Index:
   1.  Button             7.  Pill / Badge / Tag      13. Sidebar
   2.  Input / Textarea   8.  Avatar                  14. Topbar
   3.  Select             9.  Card                    15. Tabs
   4.  Checkbox / Radio   10. Alert / Banner          16. Breadcrumb
   5.  Switch             11. Toast                   17. Stepper / Pagination
   6.  Search             12. Modal / Drawer          18. Table / Data grid
                          19. Tooltip / Popover       20. Menu / Dropdown
                          21. Empty / Error state     22. Progress / Spinner
                          23. Skeleton                24. Metric / Stat
                          25. Kbd / Code              26. Chip / Filter bar
   ============================================================ */

@layer dgo-reset, dgo-base, dgo-component, dgo-utility;

/* ============================================================
   1 · BUTTON
   ============================================================
   States: default · hover · focus-visible · active · disabled · loading
   Variants: primary · secondary · tertiary · ghost · danger
   Sizes: sm · md · lg
   ============================================================ */
.dgo-btn {
  --_h: var(--dgo-btn-h-md);
  --_px: var(--dgo-btn-px-md);
  --_fs: var(--dgo-type-body);

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--dgo-s-2);
  block-size: var(--_h);
  padding-inline: var(--_px);
  font-family: var(--dgo-family-sans);
  font-size: var(--_fs);
  font-weight: var(--dgo-btn-fw);
  line-height: 1;
  border: 1px solid transparent;
  border-radius: var(--dgo-btn-radius);
  cursor: pointer;
  user-select: none;
  text-decoration: none;
  white-space: nowrap;
  transition:
    background-color var(--dgo-motion-state),
    border-color var(--dgo-motion-state),
    color var(--dgo-motion-state),
    box-shadow var(--dgo-motion-state),
    transform var(--dgo-dur-instant) var(--dgo-ease-sharp);
  min-inline-size: var(--_h); /* hit area floor */
}

.dgo-btn:focus-visible { box-shadow: var(--dgo-focus-ring); }
.dgo-btn:active:not(:disabled) { transform: translateY(1px); }
.dgo-btn:disabled,
.dgo-btn[aria-disabled="true"] {
  opacity: 0.55;
  cursor: not-allowed;
  pointer-events: none;
}

.dgo-btn--sm {
  block-size: var(--dgo-btn-h-sm);
  min-inline-size: var(--dgo-btn-h-sm);
  padding-inline: var(--dgo-btn-px-sm);
  font-size: var(--dgo-type-body-sm);
}
.dgo-btn--lg {
  block-size: var(--dgo-btn-h-lg);
  min-inline-size: var(--dgo-btn-h-lg);
  padding-inline: var(--dgo-btn-px-lg);
  font-size: var(--dgo-type-body-lg);
}
.dgo-btn--block { inline-size: 100%; }

/* Primary */
.dgo-btn--primary {
  background: var(--dgo-color-action-primary);
  color: var(--dgo-color-fg-on-brand);
}
.dgo-btn--primary:hover:not(:disabled) { background: var(--dgo-color-action-primary-hover); box-shadow: var(--dgo-shadow-2); }
.dgo-btn--primary:active:not(:disabled) { background: var(--dgo-color-action-primary-press); }

/* Secondary — outline */
.dgo-btn--secondary {
  background: transparent;
  color: var(--dgo-color-action-primary);
  border-color: var(--dgo-color-border-strong);
}
.dgo-btn--secondary:hover:not(:disabled) {
  border-color: var(--dgo-color-action-primary);
  background: var(--dgo-color-action-secondary-hover);
}
.dgo-btn--secondary:active:not(:disabled) { background: var(--dgo-color-action-secondary-press); }

/* Tertiary — text + subtle hover */
.dgo-btn--tertiary,
.dgo-btn--ghost {
  background: transparent;
  color: var(--dgo-color-fg-brand);
}
.dgo-btn--tertiary:hover:not(:disabled),
.dgo-btn--ghost:hover:not(:disabled) { background: var(--dgo-color-action-secondary-hover); }

/* Danger */
.dgo-btn--danger {
  background: var(--dgo-color-action-danger);
  color: var(--dgo-color-fg-on-brand);
}
.dgo-btn--danger:hover:not(:disabled) { background: var(--dgo-color-action-danger-hover); }

/* Accent */
.dgo-btn--accent {
  background: var(--dgo-color-action-accent);
  color: var(--dgo-color-fg-on-accent);
}
.dgo-btn--accent:hover:not(:disabled) { background: var(--dgo-color-action-accent-hover); }

/* Icon button */
.dgo-btn--icon { padding-inline: 0; inline-size: var(--_h); }

/* Loading */
.dgo-btn[data-loading="true"] { color: transparent; position: relative; }
.dgo-btn[data-loading="true"]::after {
  content: "";
  position: absolute;
  inline-size: 1em; block-size: 1em;
  border: 2px solid currentColor;
  border-block-start-color: transparent;
  border-radius: 50%;
  color: var(--dgo-color-fg-on-brand);
  animation: dgo-spin 0.6s linear infinite;
}
.dgo-btn--secondary[data-loading="true"]::after,
.dgo-btn--tertiary[data-loading="true"]::after,
.dgo-btn--ghost[data-loading="true"]::after { color: var(--dgo-color-action-primary); }

@keyframes dgo-spin { to { transform: rotate(360deg); } }

/* Button group */
.dgo-btn-group { display: inline-flex; }
.dgo-btn-group .dgo-btn {
  border-radius: 0;
}
.dgo-btn-group .dgo-btn:first-child { border-start-start-radius: var(--dgo-btn-radius); border-end-start-radius: var(--dgo-btn-radius); }
.dgo-btn-group .dgo-btn:last-child  { border-start-end-radius:   var(--dgo-btn-radius); border-end-end-radius:   var(--dgo-btn-radius); }
.dgo-btn-group .dgo-btn + .dgo-btn { margin-inline-start: -1px; }

/* ============================================================
   2 · INPUT / TEXTAREA
   ============================================================ */
.dgo-input,
.dgo-textarea,
.dgo-select__field {
  display: block;
  inline-size: 100%;
  block-size: var(--dgo-input-h);
  padding-inline: var(--dgo-input-px);
  padding-block: 0;
  font-family: var(--dgo-family-sans);
  font-size: var(--dgo-type-body);
  color: var(--dgo-color-fg-default);
  background: var(--dgo-input-bg);
  border: 1px solid var(--dgo-input-border);
  border-radius: var(--dgo-input-radius);
  transition: border-color var(--dgo-motion-state), box-shadow var(--dgo-motion-state), background-color var(--dgo-motion-state);
}
.dgo-input::placeholder,
.dgo-textarea::placeholder { color: var(--dgo-input-placeholder); }

.dgo-input:hover:not(:disabled),
.dgo-textarea:hover:not(:disabled),
.dgo-select__field:hover:not(:disabled) { border-color: var(--dgo-input-border-hover); }

.dgo-input:focus-visible,
.dgo-textarea:focus-visible,
.dgo-select__field:focus-visible {
  outline: none;
  border-color: var(--dgo-input-border-focus);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--dgo-color-action-primary) 22%, transparent);
}

.dgo-input:disabled,
.dgo-textarea:disabled,
.dgo-select__field:disabled {
  background: var(--dgo-input-bg-disabled);
  color: var(--dgo-color-fg-disabled);
  cursor: not-allowed;
}

.dgo-input[aria-invalid="true"],
.dgo-textarea[aria-invalid="true"],
.dgo-select__field[aria-invalid="true"] { border-color: var(--dgo-input-border-error); }

.dgo-textarea {
  block-size: auto;
  min-block-size: calc(var(--dgo-input-h) * 2.5);
  padding-block: var(--dgo-s-2);
  resize: vertical;
  line-height: var(--dgo-lh-150);
}

/* Form field wrapper */
.dgo-field { display: flex; flex-direction: column; gap: var(--dgo-s-1_5); }
.dgo-field__label {
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-600);
  color: var(--dgo-color-fg-default);
}
.dgo-field__label--req::after { content: " *"; color: var(--dgo-color-action-danger); }
.dgo-field__help { font-size: var(--dgo-type-caption); color: var(--dgo-color-fg-muted); }
.dgo-field__error {
  font-size: var(--dgo-type-caption);
  color: var(--dgo-color-danger-subtle-fg);
  display: flex; align-items: center; gap: var(--dgo-s-1);
}

/* Input with leading/trailing affordance */
.dgo-input-group {
  display: flex; align-items: stretch;
  border: 1px solid var(--dgo-input-border);
  border-radius: var(--dgo-input-radius);
  background: var(--dgo-input-bg);
  overflow: hidden;
}
.dgo-input-group:focus-within {
  border-color: var(--dgo-input-border-focus);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--dgo-color-action-primary) 22%, transparent);
}
.dgo-input-group > .dgo-input,
.dgo-input-group > .dgo-select__field {
  border: 0; border-radius: 0;
}
.dgo-input-group > .dgo-input:focus-visible { box-shadow: none; }
.dgo-input-group__addon {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  padding-inline: var(--dgo-s-3);
  color: var(--dgo-color-fg-muted);
  background: var(--dgo-color-surface-sunken);
  font-size: var(--dgo-type-body-sm);
}

/* ============================================================
   3 · SELECT (native styled)
   ============================================================ */
.dgo-select { position: relative; display: block; }
.dgo-select__field {
  appearance: none;
  -webkit-appearance: none;
  padding-inline-end: calc(var(--dgo-input-px) + 24px);
  cursor: pointer;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='12' height='8' viewBox='0 0 12 8' fill='none'><path d='M1 1.5L6 6.5L11 1.5' stroke='%235F5C5D' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round'/></svg>");
  background-repeat: no-repeat;
  background-position: right var(--dgo-s-3) center;
}
[dir="rtl"] .dgo-select__field {
  background-position: left var(--dgo-s-3) center;
}

/* ============================================================
   4 · CHECKBOX / RADIO
   ============================================================ */
.dgo-check, .dgo-radio {
  display: inline-flex; align-items: center; gap: var(--dgo-s-2);
  cursor: pointer; user-select: none;
  font-size: var(--dgo-type-body);
}
.dgo-check input[type="checkbox"],
.dgo-radio input[type="radio"] {
  inline-size: 18px; block-size: 18px;
  margin: 0;
  accent-color: var(--dgo-color-action-primary);
  cursor: pointer;
}
.dgo-check input:focus-visible,
.dgo-radio input:focus-visible {
  outline: 2px solid var(--dgo-color-border-focus);
  outline-offset: 2px;
}

/* ============================================================
   5 · SWITCH
   ============================================================ */
.dgo-switch {
  position: relative;
  display: inline-flex;
  inline-size: 38px; block-size: 22px;
  border-radius: var(--dgo-r-pill);
  background: var(--dgo-ink-200);
  cursor: pointer;
  transition: background-color var(--dgo-motion-state);
  flex-shrink: 0;
}
.dgo-switch::before {
  content: "";
  position: absolute;
  inset-inline-start: 2px;
  inset-block-start: 2px;
  inline-size: 18px; block-size: 18px;
  border-radius: 50%;
  background: var(--dgo-color-surface-page);
  box-shadow: var(--dgo-shadow-1);
  transition: transform var(--dgo-motion-state);
}
.dgo-switch input { position: absolute; opacity: 0; inset: 0; cursor: pointer; }
.dgo-switch:has(input:checked) { background: var(--dgo-color-action-primary); }
.dgo-switch:has(input:checked)::before { transform: translateX(16px); }
[dir="rtl"] .dgo-switch:has(input:checked)::before { transform: translateX(-16px); }
.dgo-switch:has(input:focus-visible) {
  outline: 2px solid var(--dgo-color-border-focus);
  outline-offset: 2px;
}

/* ============================================================
   6 · SEARCH
   ============================================================ */
.dgo-search {
  display: flex; align-items: center; gap: var(--dgo-s-2);
  block-size: var(--dgo-input-h);
  padding-inline: var(--dgo-s-3);
  border: 1px solid var(--dgo-input-border);
  border-radius: var(--dgo-input-radius);
  background: var(--dgo-input-bg);
  color: var(--dgo-color-fg-muted);
  transition: border-color var(--dgo-motion-state);
}
.dgo-search:focus-within { border-color: var(--dgo-color-action-primary); box-shadow: 0 0 0 3px color-mix(in srgb, var(--dgo-color-action-primary) 22%, transparent); }
.dgo-search input {
  flex: 1; border: 0; background: transparent;
  font-size: var(--dgo-type-body);
  color: var(--dgo-color-fg-default);
  outline: none;
}

/* ============================================================
   7 · PILL / BADGE / TAG / CHIP
   ============================================================ */
.dgo-pill {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  block-size: var(--dgo-badge-h);
  padding-inline: var(--dgo-badge-px);
  font-size: var(--dgo-badge-fs);
  font-weight: var(--dgo-badge-fw);
  line-height: 1;
  border-radius: var(--dgo-badge-radius);
  white-space: nowrap;
  background: var(--dgo-color-surface-sunken);
  color: var(--dgo-color-fg-default);
}
.dgo-pill__dot { inline-size: 6px; block-size: 6px; border-radius: 50%; background: currentColor; }

/* Fallback tone: statusClass() emits dgo-pill--neutral for any unmapped status string. */
.dgo-pill--neutral   { background: var(--dgo-color-surface-sunken);      color: var(--dgo-color-fg-muted); }
.dgo-pill--pending   { background: var(--dgo-color-status-pending-bg);   color: var(--dgo-color-status-pending-fg); }
.dgo-pill--routed    { background: var(--dgo-color-status-routed-bg);    color: var(--dgo-color-status-routed-fg); }
.dgo-pill--replied   { background: var(--dgo-color-status-replied-bg);   color: var(--dgo-color-status-replied-fg); }
.dgo-pill--action    { background: var(--dgo-color-status-action-bg);    color: var(--dgo-color-status-action-fg); }
.dgo-pill--draft     { background: var(--dgo-color-status-draft-bg);     color: var(--dgo-color-status-draft-fg); }
.dgo-pill--archived  { background: var(--dgo-color-status-archived-bg);  color: var(--dgo-color-status-archived-fg); }
.dgo-pill--escalated { background: var(--dgo-color-status-escalated-bg); color: var(--dgo-color-status-escalated-fg); }
.dgo-pill--info      { background: var(--dgo-color-info-subtle-bg);      color: var(--dgo-color-info-subtle-fg); }
.dgo-pill--success   { background: var(--dgo-color-success-subtle-bg);   color: var(--dgo-color-success-subtle-fg); }
.dgo-pill--warning   { background: var(--dgo-color-warning-subtle-bg);   color: var(--dgo-color-warning-subtle-fg); }
.dgo-pill--danger    { background: var(--dgo-color-danger-subtle-bg);    color: var(--dgo-color-danger-subtle-fg); }

/* Counter badge (numeric) */
.dgo-badge {
  display: inline-flex; align-items: center; justify-content: center;
  min-inline-size: 18px; block-size: 18px; padding-inline: 5px;
  font-size: 11px; font-weight: var(--dgo-wt-700); line-height: 1;
  border-radius: var(--dgo-r-pill);
  background: var(--dgo-color-action-danger);
  color: var(--dgo-color-fg-on-brand);
}

/* Tag (square) */
.dgo-tag {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  block-size: var(--dgo-tag-h);
  padding-inline: var(--dgo-s-2);
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-500);
  border-radius: var(--dgo-tag-radius);
  background: var(--dgo-color-surface-sunken);
  color: var(--dgo-color-fg-default);
  border: 1px solid var(--dgo-color-border-default);
}

/* Chip (interactive tag with × close) */
.dgo-chip {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1_5);
  block-size: 28px;
  padding-inline-start: var(--dgo-s-3);
  padding-inline-end: var(--dgo-s-1);
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-500);
  border-radius: var(--dgo-r-pill);
  background: var(--dgo-color-action-primary-soft);
  color: var(--dgo-color-action-primary);
  transition: background var(--dgo-motion-state);
}
.dgo-chip__close {
  display: inline-flex; align-items: center; justify-content: center;
  inline-size: 20px; block-size: 20px;
  border-radius: 50%;
  color: var(--dgo-color-action-primary);
  cursor: pointer;
}
.dgo-chip__close:hover,
.dgo-chip__close:focus-visible { background: color-mix(in srgb, var(--dgo-color-action-primary) 20%, transparent); }

/* ============================================================
   8 · AVATAR
   ============================================================ */
.dgo-avatar {
  display: inline-flex; align-items: center; justify-content: center;
  inline-size: 36px; block-size: 36px;
  border-radius: 50%;
  background: var(--dgo-color-action-primary-soft);
  color: var(--dgo-color-action-primary);
  font-weight: var(--dgo-wt-600);
  font-size: var(--dgo-type-body-sm);
  letter-spacing: var(--dgo-tr-tight);
  overflow: hidden;
  flex-shrink: 0;
}
.dgo-avatar--sm { inline-size: 24px; block-size: 24px; font-size: 11px; }
.dgo-avatar--lg { inline-size: 48px; block-size: 48px; font-size: var(--dgo-type-body-lg); }
.dgo-avatar--xl { inline-size: 72px; block-size: 72px; font-size: var(--dgo-type-h3); }
.dgo-avatar img { inline-size: 100%; block-size: 100%; object-fit: cover; }
.dgo-avatar-stack { display: inline-flex; }
.dgo-avatar-stack .dgo-avatar { box-shadow: 0 0 0 2px var(--dgo-color-surface-page); }
.dgo-avatar-stack .dgo-avatar + .dgo-avatar { margin-inline-start: -10px; }

/* ============================================================
   9 · CARD
   ============================================================ */
.dgo-card {
  background: var(--dgo-card-bg);
  border: 1px solid var(--dgo-card-border);
  border-radius: var(--dgo-card-radius);
  padding: var(--dgo-card-pad);
  transition: box-shadow var(--dgo-motion-state), border-color var(--dgo-motion-state), transform var(--dgo-motion-state);
}
.dgo-card--flat   { box-shadow: var(--dgo-elevation-flat); }
.dgo-card--raised { box-shadow: var(--dgo-elevation-card); }
.dgo-card--hoverable { cursor: pointer; }
.dgo-card--hoverable:hover,
.dgo-card--hoverable:focus-visible {
  box-shadow: var(--dgo-card-shadow-hover);
  border-color: var(--dgo-color-border-strong);
}
.dgo-card--accent {
  border-inline-start: 4px solid var(--dgo-color-action-accent);
}
.dgo-card__header {
  display: flex; align-items: center; justify-content: space-between;
  gap: var(--dgo-s-3);
  margin-block-end: var(--dgo-s-3);
}
.dgo-card__title {
  font-family: var(--dgo-family-display);
  font-size: var(--dgo-type-h4);
  font-weight: var(--dgo-wt-700);
  line-height: var(--dgo-lh-120);
  margin: 0;
}
.dgo-card__sub { font-size: var(--dgo-type-body-sm); color: var(--dgo-color-fg-muted); margin: 2px 0 0; }
.dgo-card__footer {
  margin-block-start: var(--dgo-s-4);
  padding-block-start: var(--dgo-s-3);
  border-block-start: 1px solid var(--dgo-color-border-default);
  display: flex; align-items: center; gap: var(--dgo-s-2);
}

/* Frame — large container shell */
.dgo-frame {
  background: var(--dgo-color-surface-page);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-radius-frame);
  overflow: clip;
  box-shadow: var(--dgo-elevation-card);
}

/* ============================================================
   10 · ALERT / BANNER
   ============================================================ */
.dgo-alert {
  display: flex; gap: var(--dgo-s-3); align-items: flex-start;
  padding: var(--dgo-alert-pad);
  border: var(--dgo-alert-border-w) solid;
  border-radius: var(--dgo-alert-radius);
  font-size: var(--dgo-type-body);
  background: var(--dgo-color-surface-raised);
}
.dgo-alert__icon { flex-shrink: 0; margin-block-start: 2px; }
.dgo-alert__title { font-weight: var(--dgo-wt-600); margin-block-end: 2px; }
.dgo-alert__body  { color: var(--dgo-color-fg-default); }
.dgo-alert--info    { background: var(--dgo-color-info-subtle-bg);    color: var(--dgo-color-info-subtle-fg);    border-color: color-mix(in srgb, var(--dgo-color-info-subtle-fg) 30%, transparent); }
.dgo-alert--success { background: var(--dgo-color-success-subtle-bg); color: var(--dgo-color-success-subtle-fg); border-color: color-mix(in srgb, var(--dgo-color-success-subtle-fg) 30%, transparent); }
.dgo-alert--warning { background: var(--dgo-color-warning-subtle-bg); color: var(--dgo-color-warning-subtle-fg); border-color: color-mix(in srgb, var(--dgo-color-warning-subtle-fg) 30%, transparent); }
.dgo-alert--danger  { background: var(--dgo-color-danger-subtle-bg);  color: var(--dgo-color-danger-subtle-fg);  border-color: color-mix(in srgb, var(--dgo-color-danger-subtle-fg) 30%, transparent); }

/* Restricted zone — I-08. Administration's connection-address editor was presented as an
   ordinary settings form, so a field that can take the whole workspace offline looked the
   same as the theme picker. This gives that disclosure a warning surface and a left rule,
   so it reads as a different class of control before anything inside it is opened. */
.danger-zone {
  border-color: color-mix(in srgb, var(--dgo-color-danger-subtle-fg) 40%, transparent);
  border-inline-start: 4px solid var(--dgo-color-danger-subtle-fg);
  background: var(--dgo-color-danger-subtle-bg);
}
.danger-zone > summary { font-weight: var(--dgo-wt-600); color: var(--dgo-color-danger-subtle-fg); cursor: pointer; }
.danger-zone > summary > .dgo-pill { margin-inline-start: var(--dgo-s-2); }

/* Banner — full-width page-level */
.dgo-banner {
  display: flex; align-items: center; justify-content: space-between; gap: var(--dgo-s-4);
  padding: var(--dgo-s-3) var(--dgo-s-5);
  background: var(--dgo-color-surface-brand);
  color: var(--dgo-color-fg-on-brand);
  font-size: var(--dgo-type-body-sm);
}

/* ============================================================
   11 · TOAST / SNACKBAR
   ============================================================ */
.dgo-toast-region {
  position: fixed;
  inset-block-end: var(--dgo-s-6);
  inset-inline-end: var(--dgo-s-6);
  display: flex; flex-direction: column; gap: var(--dgo-s-3);
  z-index: var(--dgo-z-toast);
  max-inline-size: 380px;
  pointer-events: none;
}
.dgo-toast {
  display: flex; gap: var(--dgo-s-3); align-items: flex-start;
  padding: var(--dgo-s-4);
  background: var(--dgo-color-surface-raised);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-radius-card);
  box-shadow: var(--dgo-elevation-overlay);
  pointer-events: auto;
  animation: dgo-toast-in var(--dgo-motion-enter);
}
@keyframes dgo-toast-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: none; }
}

/* ============================================================
   12 · MODAL / DRAWER
   ============================================================ */
.dgo-modal-backdrop {
  position: fixed; inset: 0;
  background: var(--dgo-color-surface-overlay);
  z-index: var(--dgo-z-modal);
  display: grid; place-items: center;
  padding: var(--dgo-s-4);
  animation: dgo-fade-in var(--dgo-motion-enter);
}
.dgo-modal {
  inline-size: 100%;
  max-inline-size: var(--dgo-modal-w);
  max-block-size: 90vh;
  display: flex; flex-direction: column;
  background: var(--dgo-color-surface-raised);
  border-radius: var(--dgo-modal-radius);
  box-shadow: var(--dgo-modal-shadow);
  overflow: clip;
  animation: dgo-modal-in var(--dgo-motion-enter);
}
.dgo-modal--lg { max-inline-size: var(--dgo-modal-w-lg); }
.dgo-modal__header {
  display: flex; align-items: flex-start; justify-content: space-between; gap: var(--dgo-s-4);
  padding: var(--dgo-s-5) var(--dgo-s-6);
  border-block-end: 1px solid var(--dgo-color-border-default);
}
.dgo-modal__title { font-size: var(--dgo-type-h3); font-weight: var(--dgo-wt-700); margin: 0; }
.dgo-modal__body { padding: var(--dgo-s-6); overflow-y: auto; }
.dgo-modal__footer {
  padding: var(--dgo-s-4) var(--dgo-s-6);
  border-block-start: 1px solid var(--dgo-color-border-default);
  display: flex; justify-content: flex-end; gap: var(--dgo-s-2);
}
@keyframes dgo-fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes dgo-modal-in { from { opacity: 0; transform: translateY(8px) scale(0.98); } to { opacity: 1; transform: none; } }

.dgo-drawer {
  position: fixed; inset-block: 0; inset-inline-end: 0;
  inline-size: var(--dgo-drawer-w); max-inline-size: 100vw;
  background: var(--dgo-color-surface-raised);
  box-shadow: var(--dgo-elevation-modal);
  display: flex; flex-direction: column;
  animation: dgo-drawer-in var(--dgo-motion-enter);
  z-index: var(--dgo-z-modal);
}
@keyframes dgo-drawer-in { from { transform: translateX(100%); } to { transform: none; } }
[dir="rtl"] .dgo-drawer { inset-inline-end: auto; inset-inline-start: 0; }

/* ============================================================
   13 · SIDEBAR
   ============================================================ */
.dgo-sidebar {
  display: flex; flex-direction: column; gap: var(--dgo-s-5);
  padding: var(--dgo-s-5) var(--dgo-s-3);
  background: var(--dgo-sidebar-bg);
  color: var(--dgo-sidebar-fg);
  block-size: 100vh;
  position: sticky;
  inset-block-start: 0;
}
.dgo-sidebar__brand { padding-inline: var(--dgo-s-2); padding-block-end: var(--dgo-s-4); border-block-end: 1px solid var(--dgo-color-border-on-brand); }
.dgo-sidebar__nav { display: flex; flex-direction: column; gap: 2px; flex: 1; }
.dgo-sidebar__group-label {
  font-size: var(--dgo-type-floor);
  font-weight: var(--dgo-wt-700);
  letter-spacing: var(--dgo-tr-widest);
  text-transform: uppercase;
  color: rgba(255,255,255,0.45);
  padding-inline: var(--dgo-s-3);
  padding-block: var(--dgo-s-3) var(--dgo-s-1);
}

.dgo-sidebar__item {
  display: flex; align-items: center; gap: var(--dgo-s-3);
  padding: var(--dgo-s-2) var(--dgo-s-3);
  border-radius: var(--dgo-radius-control);
  color: rgba(255,255,255,0.78);
  text-decoration: none;
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-500);
  transition: background var(--dgo-motion-state), color var(--dgo-motion-state);
  position: relative;
  min-block-size: 36px;
}
.dgo-sidebar__item:hover { color: #fff; background: rgba(255,255,255,0.06); }
.dgo-sidebar__item[aria-current="page"],
.dgo-sidebar__item--active {
  background: rgba(255,255,255,0.10);
  color: #fff;
}
.dgo-sidebar__item[aria-current="page"]::before,
.dgo-sidebar__item--active::before {
  content: "";
  position: absolute;
  inset-inline-start: 0;
  inset-block: 8px;
  inline-size: 3px;
  background: var(--dgo-color-action-accent);
  border-radius: 2px;
}
.dgo-sidebar__count {
  margin-inline-start: auto;
  font-size: 11px;
  padding: 2px 6px;
  border-radius: var(--dgo-r-pill);
  background: rgba(255,255,255,0.10);
}
.dgo-sidebar__footer {
  padding-block-start: var(--dgo-s-4);
  border-block-start: 1px solid var(--dgo-color-border-on-brand);
}

/* ============================================================
   14 · TOPBAR
   ============================================================ */
.dgo-topbar {
  display: flex; align-items: center; gap: var(--dgo-s-4);
  block-size: var(--dgo-topbar-h);
  padding-inline: var(--dgo-s-5);
  background: var(--dgo-topbar-bg);
  border-block-end: 1px solid var(--dgo-topbar-border);
  position: sticky; inset-block-start: 0;
  z-index: var(--dgo-z-sticky);
}

/* ============================================================
   15 · TABS
   ============================================================ */
.dgo-tabs { display: flex; flex-direction: column; gap: var(--dgo-s-5); }
.dgo-tabs__list {
  display: flex; gap: var(--dgo-s-1);
  border-block-end: 1px solid var(--dgo-color-border-default);
}
.dgo-tabs__tab {
  display: inline-flex; align-items: center; gap: var(--dgo-s-2);
  padding: var(--dgo-s-3) var(--dgo-s-4);
  font-size: var(--dgo-type-body);
  font-weight: var(--dgo-wt-500);
  color: var(--dgo-color-fg-muted);
  border: 0; background: transparent;
  border-block-end: var(--dgo-tabs-indicator-h) solid transparent;
  margin-block-end: -1px;
  cursor: pointer;
  transition: color var(--dgo-motion-state), border-color var(--dgo-motion-state);
}
.dgo-tabs__tab:hover,
.dgo-tabs__tab:focus-visible { color: var(--dgo-color-fg-default); }
.dgo-tabs__tab[aria-selected="true"] {
  color: var(--dgo-color-action-primary);
  border-block-end-color: var(--dgo-tabs-indicator);
  font-weight: var(--dgo-wt-600);
}

/* ============================================================
   16 · BREADCRUMB
   ============================================================ */
.dgo-crumbs { display: flex; align-items: center; gap: var(--dgo-s-2); font-size: var(--dgo-type-body-sm); color: var(--dgo-color-fg-muted); }
.dgo-crumbs__sep { color: var(--dgo-color-fg-subtle); }
.dgo-crumbs a { color: var(--dgo-color-fg-muted); text-decoration: none; }
.dgo-crumbs a:hover,
.dgo-crumbs a:focus-visible { color: var(--dgo-color-action-primary); }
.dgo-crumbs__current { color: var(--dgo-color-fg-default); font-weight: var(--dgo-wt-600); }

/* ============================================================
   17 · STEPPER / PAGINATION
   ============================================================ */
.dgo-stepper { display: flex; align-items: center; gap: var(--dgo-s-3); }
.dgo-stepper__step {
  display: flex; align-items: center; gap: var(--dgo-s-2);
  color: var(--dgo-color-fg-muted);
  font-size: var(--dgo-type-body-sm);
}
.dgo-stepper__bullet {
  inline-size: 28px; block-size: 28px;
  border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--dgo-color-surface-sunken);
  color: var(--dgo-color-fg-muted);
  font-weight: var(--dgo-wt-600);
  font-size: var(--dgo-type-body-sm);
  border: 1px solid var(--dgo-color-border-default);
}
.dgo-stepper__step[data-state="current"] .dgo-stepper__bullet {
  background: var(--dgo-color-action-primary);
  color: var(--dgo-color-fg-on-brand);
  border-color: var(--dgo-color-action-primary);
}
.dgo-stepper__step[data-state="done"] .dgo-stepper__bullet {
  background: var(--dgo-color-action-accent);
  color: var(--dgo-color-fg-on-accent);
  border-color: var(--dgo-color-action-accent);
}
.dgo-stepper__step[data-state="current"], .dgo-stepper__step[data-state="done"] { color: var(--dgo-color-fg-default); }
.dgo-stepper__line { flex: 1; block-size: 2px; background: var(--dgo-color-border-default); border-radius: 2px; }
.dgo-stepper__step[data-state="done"] + .dgo-stepper__line { background: var(--dgo-color-action-accent); }

.dgo-pagination { display: inline-flex; align-items: center; gap: var(--dgo-s-1); }
.dgo-pagination__btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-inline-size: var(--dgo-pagination-h); block-size: var(--dgo-pagination-h);
  padding-inline: var(--dgo-s-2);
  border-radius: var(--dgo-pagination-radius);
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-500);
  color: var(--dgo-color-fg-default);
  background: transparent;
  border: 1px solid transparent;
}
.dgo-pagination__btn:hover,
.dgo-pagination__btn:focus-visible { background: var(--dgo-color-surface-sunken); }
.dgo-pagination__btn[aria-current="page"] {
  background: var(--dgo-color-action-primary);
  color: var(--dgo-color-fg-on-brand);
}
.dgo-pagination__btn:disabled { color: var(--dgo-color-fg-disabled); cursor: not-allowed; }

/* ============================================================
   18 · TABLE / DATA GRID
   ============================================================ */
.dgo-table-wrap {
  border: 1px solid var(--dgo-table-border);
  border-radius: var(--dgo-radius-card);
  overflow: clip;
  background: var(--dgo-color-surface-raised);
}
.dgo-table {
  inline-size: 100%;
  border-collapse: collapse;
  font-size: var(--dgo-type-body-sm);
}
.dgo-table thead { background: var(--dgo-table-header-bg); }
.dgo-table th {
  text-align: start;
  padding: 0 var(--dgo-table-cell-px);
  block-size: var(--dgo-table-row-h);
  font-size: var(--dgo-type-caption);
  font-weight: var(--dgo-wt-600);
  letter-spacing: var(--dgo-tr-wide);
  text-transform: uppercase;
  color: var(--dgo-table-header-fg);
  border-block-end: 1px solid var(--dgo-table-border);
  white-space: nowrap;
}
.dgo-table td {
  padding: 0 var(--dgo-table-cell-px);
  block-size: var(--dgo-table-row-h);
  color: var(--dgo-color-fg-default);
  border-block-end: 1px solid var(--dgo-table-border);
  vertical-align: middle;
}
.dgo-table tbody tr:hover td { background: var(--dgo-table-row-hover); }
.dgo-table tbody tr:last-child td { border-block-end: 0; }
.dgo-table--striped tbody tr:nth-child(even) td { background: var(--dgo-color-surface-sunken); }

.dgo-table__num { text-align: end; font-variant-numeric: tabular-nums; }
.dgo-table__sort {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  color: inherit; cursor: pointer;
}

/* ============================================================
   19 · TOOLTIP / POPOVER
   ============================================================ */
.dgo-tooltip {
  display: inline-block;
  padding: 6px 10px;
  background: var(--dgo-tooltip-bg);
  color: var(--dgo-tooltip-fg);
  font-size: var(--dgo-type-caption);
  font-weight: var(--dgo-wt-500);
  border-radius: var(--dgo-tooltip-radius);
  box-shadow: var(--dgo-shadow-3);
  max-inline-size: 280px;
}
.dgo-popover {
  background: var(--dgo-color-surface-raised);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-popover-radius);
  padding: var(--dgo-popover-pad);
  box-shadow: var(--dgo-popover-shadow);
  min-inline-size: 220px;
}

/* ============================================================
   20 · MENU / DROPDOWN
   ============================================================ */
.dgo-menu {
  background: var(--dgo-color-surface-raised);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-radius-card);
  padding: var(--dgo-s-1);
  box-shadow: var(--dgo-popover-shadow);
  min-inline-size: 200px;
}
.dgo-menu__item {
  display: flex; align-items: center; gap: var(--dgo-s-2);
  padding: var(--dgo-s-2) var(--dgo-s-3);
  border-radius: var(--dgo-r-6);
  font-size: var(--dgo-type-body-sm);
  color: var(--dgo-color-fg-default);
  text-decoration: none;
  cursor: pointer;
}
.dgo-menu__item:hover, .dgo-menu__item:focus-visible {
  background: var(--dgo-color-surface-sunken);
  outline: none;
}
.dgo-menu__item--danger { color: var(--dgo-color-action-danger); }
.dgo-menu__item--danger:hover,
.dgo-menu__item--danger:focus-visible { background: var(--dgo-color-danger-subtle-bg); }
.dgo-menu__sep { block-size: 1px; background: var(--dgo-color-border-default); margin: var(--dgo-s-1) 0; }
.dgo-menu__label {
  font-size: var(--dgo-type-caption);
  text-transform: uppercase;
  letter-spacing: var(--dgo-tr-wide);
  color: var(--dgo-color-fg-muted);
  padding: var(--dgo-s-2) var(--dgo-s-3) var(--dgo-s-1);
}

/* ============================================================
   21 · EMPTY / ERROR / ONBOARDING STATE
   ============================================================ */
.dgo-empty {
  display: flex; flex-direction: column; align-items: center; text-align: center;
  gap: var(--dgo-s-3);
  padding: var(--dgo-s-12) var(--dgo-s-6);
  color: var(--dgo-color-fg-muted);
}
.dgo-empty__title { font-size: var(--dgo-type-h4); font-weight: var(--dgo-wt-700); color: var(--dgo-color-fg-default); }
.dgo-empty__body { max-inline-size: 42ch; }

/* ============================================================
   22 · PROGRESS / SPINNER
   ============================================================ */
.dgo-progress {
  inline-size: 100%;
  block-size: var(--dgo-progress-h);
  background: var(--dgo-progress-track);
  border-radius: var(--dgo-r-pill);
  overflow: hidden;
}
.dgo-progress__fill {
  block-size: 100%;
  background: var(--dgo-progress-fill);
  border-radius: inherit;
  transition: inline-size var(--dgo-motion-state);
}
.dgo-progress--accent .dgo-progress__fill { background: var(--dgo-color-action-accent); }

.dgo-progress-ring {
  inline-size: 56px; block-size: 56px;
  display: inline-grid; place-items: center;
  --_p: 0; /* @kind other */
  background:
    conic-gradient(var(--dgo-color-action-primary) calc(var(--_p) * 1%), var(--dgo-progress-track) 0);
  border-radius: 50%;
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-700);
  color: var(--dgo-color-fg-default);
  position: relative;
}
.dgo-progress-ring::before {
  content: ""; position: absolute; inset: 5px;
  background: var(--dgo-color-surface-page);
  border-radius: 50%;
}
.dgo-progress-ring > span { position: relative; }

.dgo-spinner {
  inline-size: 24px; block-size: 24px;
  border: 2.5px solid var(--dgo-color-surface-sunken);
  border-block-start-color: var(--dgo-color-action-primary);
  border-radius: 50%;
  animation: dgo-spin 0.8s linear infinite;
}

/* ============================================================
   23 · SKELETON
   ============================================================ */
.dgo-skeleton {
  display: block;
  background:
    linear-gradient(90deg,
      var(--dgo-skeleton-base) 0%,
      var(--dgo-skeleton-shine) 50%,
      var(--dgo-skeleton-base) 100%);
  background-size: 200% 100%;
  border-radius: var(--dgo-r-6);
  animation: dgo-skeleton 1.4s linear infinite;
  min-block-size: 12px;
}
@keyframes dgo-skeleton {
  from { background-position: 200% 0; }
  to { background-position: -200% 0; }
}
.dgo-skeleton--circle { border-radius: 50%; }

/* ============================================================
   24 · METRIC / STAT TILE
   ============================================================ */
.dgo-metric {
  background: var(--dgo-card-bg);
  border: 1px solid var(--dgo-card-border);
  border-radius: var(--dgo-card-radius);
  padding: var(--dgo-card-pad);
  display: flex; flex-direction: column; gap: var(--dgo-s-2);
}
.dgo-metric__label {
  font-size: var(--dgo-type-caption);
  font-weight: var(--dgo-wt-600);
  letter-spacing: var(--dgo-tr-wide);
  text-transform: uppercase;
  color: var(--dgo-color-fg-muted);
}
.dgo-metric__value {
  font-family: var(--dgo-family-display);
  font-size: var(--dgo-type-h1);
  font-weight: var(--dgo-wt-700);
  letter-spacing: var(--dgo-tr-tightest);
  line-height: var(--dgo-lh-110);
  font-variant-numeric: tabular-nums;
  color: var(--dgo-color-fg-strong);
}
.dgo-metric__delta {
  display: inline-flex; align-items: center; gap: var(--dgo-s-1);
  font-size: var(--dgo-type-body-sm);
  font-weight: var(--dgo-wt-600);
}
.dgo-metric__delta--up { color: var(--dgo-color-success-subtle-fg); }
.dgo-metric__delta--down { color: var(--dgo-color-danger-subtle-fg); }

/* ============================================================
   25 · KBD / CODE
   ============================================================ */
.dgo-kbd {
  display: inline-flex; align-items: center;
  min-inline-size: 22px; block-size: 22px;
  padding-inline: 6px;
  font-family: var(--dgo-family-mono);
  font-size: 11px;
  font-weight: var(--dgo-wt-600);
  background: var(--dgo-kbd-bg);
  color: var(--dgo-color-fg-default);
  border: 1px solid var(--dgo-kbd-border);
  border-block-end-width: 2px;
  border-radius: var(--dgo-r-4);
}

.dgo-code-block {
  display: block;
  font-family: var(--dgo-family-mono);
  font-size: var(--dgo-type-body-sm);
  line-height: var(--dgo-lh-150);
  background: var(--dgo-code-bg);
  color: var(--dgo-code-fg);
  padding: var(--dgo-s-4);
  border-radius: var(--dgo-radius-card);
  border: 1px solid var(--dgo-color-border-default);
  overflow-x: auto;
  white-space: pre;
}

.dgo-inline-code {
  font-family: var(--dgo-family-mono);
  font-size: 0.88em;
  padding: 2px 6px;
  border-radius: var(--dgo-r-4);
  background: var(--dgo-code-bg);
  color: var(--dgo-code-fg);
}

/* ============================================================
   26 · FILTER BAR / BULK-ACTION BAR
   ============================================================ */
.dgo-filter-bar {
  display: flex; align-items: center; gap: var(--dgo-s-3); flex-wrap: wrap;
  padding: var(--dgo-s-3) var(--dgo-s-4);
  background: var(--dgo-color-surface-raised);
  border: 1px solid var(--dgo-color-border-default);
  border-radius: var(--dgo-radius-card);
}
.dgo-bulk-bar {
  display: flex; align-items: center; gap: var(--dgo-s-3);
  padding: var(--dgo-s-3) var(--dgo-s-4);
  background: var(--dgo-color-action-primary);
  color: var(--dgo-color-fg-on-brand);
  border-radius: var(--dgo-radius-card);
}
.dgo-bulk-bar .dgo-btn--ghost { color: var(--dgo-color-fg-on-brand); }
.dgo-bulk-bar .dgo-btn--ghost:hover,
.dgo-bulk-bar .dgo-btn--ghost:focus-visible { background: rgba(255,255,255,0.12); }

/* ============================================================
   Utilities
   ============================================================ */
.dgo-divider { block-size: 1px; background: var(--dgo-color-border-default); border: 0; margin-block: var(--dgo-s-5); }

/* Tabular numerals helper */
.dgo-tnum { font-variant-numeric: tabular-nums; }

/* ============================================================
   DGO v2.0 — Layout primitives
   stack · cluster · grid · sidebar · split
   ============================================================ */

/* Stack — vertical flow with consistent spacing */
.dgo-stack { display: flex; flex-direction: column; gap: var(--dgo-density-gap); }
.dgo-stack--1 { gap: var(--dgo-s-1); }
.dgo-stack--2 { gap: var(--dgo-s-2); }
.dgo-stack--3 { gap: var(--dgo-s-3); }
.dgo-stack--4 { gap: var(--dgo-s-4); }
.dgo-stack--5 { gap: var(--dgo-s-5); }
.dgo-stack--6 { gap: var(--dgo-s-6); }
.dgo-stack--8 { gap: var(--dgo-s-8); }
.dgo-stack--12 { gap: var(--dgo-s-12); }

/* Cluster — wrapping horizontal flow */
.dgo-cluster {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--dgo-density-gap);
}
.dgo-cluster--2 { gap: var(--dgo-s-2); }
.dgo-cluster--3 { gap: var(--dgo-s-3); }
.dgo-cluster--4 { gap: var(--dgo-s-4); }
.dgo-cluster--end { justify-content: flex-end; }
.dgo-cluster--between { justify-content: space-between; }

/* Row — horizontal flex, non-wrapping by default */
.dgo-row {
  display: flex;
  gap: var(--dgo-density-gap);
  align-items: center;
}
.dgo-row--top    { align-items: flex-start; }
.dgo-row--bottom { align-items: flex-end; }
.dgo-row--baseline { align-items: baseline; }
.dgo-row--stretch { align-items: stretch; }
.dgo-row--between { justify-content: space-between; }
.dgo-row--end     { justify-content: flex-end; }
.dgo-row--center  { justify-content: center; }

.dgo-spacer { flex: 1 1 auto; }

/* Grid */
.dgo-grid {
  display: grid;
  gap: var(--dgo-density-gap);
}
.dgo-grid--2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.dgo-grid--3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.dgo-grid--4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.dgo-grid--6 { grid-template-columns: repeat(6, minmax(0, 1fr)); }
.dgo-grid--12 { grid-template-columns: repeat(12, minmax(0, 1fr)); }
.dgo-grid--auto { grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); }

@media (max-width: 900px) {
  .dgo-grid--3, .dgo-grid--4, .dgo-grid--6 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dgo-grid--12 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@media (max-width: 640px) {
  .dgo-grid--2, .dgo-grid--3, .dgo-grid--4, .dgo-grid--6 { grid-template-columns: 1fr; }
  .dgo-grid--12 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* Sidebar layout — fixed-width sidebar + fluid content */
.dgo-sidebar-layout {
  display: grid;
  grid-template-columns: var(--dgo-sidebar-w) minmax(0, 1fr);
  min-height: 100vh;
}
.dgo-sidebar-layout--collapsed {
  grid-template-columns: var(--dgo-sidebar-w-collapsed) minmax(0, 1fr);
}

@media (max-width: 900px) {
  .dgo-sidebar-layout { grid-template-columns: 1fr; }
}

/* Split — two columns, prefer space-between */
.dgo-split {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--dgo-s-4);
}

/* App shell scaffold */
.dgo-app {
  display: grid;
  grid-template-rows: auto 1fr;
  min-height: 100vh;
}
.dgo-app__topbar { grid-row: 1; }
.dgo-app__body   { grid-row: 2; min-height: 0; }

/* Container queries (component-level reflow) */
.dgo-cq { container-type: inline-size; }

/* DGO R11.2 revised design-system authority layer.
   Non-destructive, viewport-safe, runtime-safe. It uses the revised DGO 2.2 tokens
   and component contracts while preserving the R11.1 route, viewport and shell contracts. */

/* color-scheme now has a single owner in base.css; the legacy short-var bridge is owned by
   tokens.legacy-bridge.css. This sheet declares nothing on the page root. */

/* Revised DGO button contract for the runtime's compact button API. */
.btn,.iconbtn,.entry-btn,.dgo-btn {
  min-block-size: var(--dgo-control-target-min,44px);
  min-inline-size: var(--dgo-control-target-min,44px);
  border-radius: var(--dgo-btn-radius,var(--dgo-radius-control));
  border: 1px solid transparent;
  font-family: var(--dgo-family-sans);
  font-weight: var(--dgo-wt-600);
  transition: background-color var(--dgo-motion-state), border-color var(--dgo-motion-state), color var(--dgo-motion-state), box-shadow var(--dgo-motion-state), transform var(--dgo-dur-instant) var(--dgo-ease-sharp);
}
.btn:not(.ghost),.entry-btn,.dgo-btn--primary { background: var(--dgo-color-action-primary); color: var(--dgo-color-fg-on-brand); border-color: var(--dgo-color-action-primary); }
.btn:not(.ghost):hover,.entry-btn:hover,.dgo-btn--primary:hover { background: var(--dgo-color-action-primary-hover); border-color: var(--dgo-color-action-primary-hover); }
.entry-btn:focus-visible { background: var(--dgo-color-action-primary-hover); border-color: var(--dgo-color-action-primary-hover); }
.btn.ghost,.iconbtn,.dgo-btn--ghost { background: var(--dgo-color-surface-raised); color: var(--dgo-color-fg-brand); border-color: var(--dgo-color-border-default); }
.btn.ghost:hover,.iconbtn:hover,.dgo-btn--ghost:hover { background: var(--dgo-color-action-secondary-hover); border-color: var(--dgo-color-action-primary); }
.btn:disabled,.iconbtn:disabled,.btn[aria-disabled="true"] { opacity:.55; cursor:not-allowed; pointer-events:none; }
.btn:active:not(:disabled),.iconbtn:active:not(:disabled){ transform:translateY(1px); }

/* Forms use revised field/input sizing, focus and error affordances.
   The field height is the larger of the density height and the target-size floor, so a field is
   never smaller than the minimum this sheet declares for every other control. */
input,select,textarea,.dgo-input,.dgo-select,.dgo-textarea {
  min-block-size: max(var(--dgo-input-h,40px), var(--dgo-control-target-min));
  border: 1px solid var(--dgo-input-border,var(--dgo-color-border-strong));
  border-radius: var(--dgo-input-radius,var(--dgo-radius-control));
  background: var(--dgo-input-bg,var(--dgo-color-surface-page));
  color: var(--dgo-color-fg-default);
  padding-inline: var(--dgo-input-px,var(--dgo-s-3));
}
textarea { padding-block: var(--dgo-s-2); }
/* The outline is the only part of this ring that survives forced-colors mode, so every focusable
   element type has to be listed here — box-shadow alone leaves a Windows high-contrast user
   with no visible focus at all. */
input:focus-visible,select:focus-visible,textarea:focus-visible,button:focus-visible,summary:focus-visible,.btn:focus-visible,.iconbtn:focus-visible,a:focus-visible,[tabindex]:focus-visible {
  outline: var(--dgo-focus-width,3px) solid var(--dgo-color-border-focus);
  outline-offset: var(--dgo-focus-offset,3px);
  box-shadow: var(--dgo-focus-ring);
}
/* Focus parity: the keyboard state mirrors the hover affordance of the same control, which means
   it must also mirror its contrast. Painting every focused .btn with --a put white label text on
   #17B255 (2.79:1) and gave a focused ghost button a brand-green fill under brand-green text. */
.btn:not(.ghost):focus-visible,.dgo-btn--primary:focus-visible { background: var(--dgo-color-action-primary-hover); border-color: var(--dgo-color-action-primary-hover); }
.btn.ghost:focus-visible,.iconbtn:focus-visible,.dgo-btn--ghost:focus-visible { background: var(--dgo-color-action-secondary-hover); border-color: var(--dgo-color-action-primary); }
.grid label,.dgo-field { gap: var(--dgo-s-1_5,var(--dgo-s-1)); color: var(--dgo-color-fg-default); }

/* Target size (WCAG 2.5.5): --dgo-control-target-min is the declared minimum for anything that
   receives pointer input. It was declared for .btn only, so chips, disclosure summaries, the
   topbar controls and the skip link fell through to whatever literal app.css happened to set.
   Pills and badges are deliberately excluded: they are read, not pressed. */
/* .dgo-sidebar__item was missing from this list, so the floor for the 29 navigation links —
   the controls every user presses on every visit — was owned by whatever app.css last said.
   app.css set the token and then overrode it to 36px in a landscape breakpoint 300 lines
   later, and nothing here disagreed because nothing here claimed them. */
summary,button.chip,a.chip,.dgo-iconbtn,.dgo-search-trigger,.dgo-persona-button,.dgo-sidebar__item,a.skip {
  min-block-size: var(--dgo-control-target-min);
}
.dgo-iconbtn,.dgo-search-trigger,.dgo-persona-button,button.chip,a.chip { min-inline-size: var(--dgo-control-target-min); }

/* Cards, panels, workspaces and shell surfaces. */
.panel,.record,.empty,.tablewrap,.kpi,.toolbar,.dgo-card,.dgo-panel,.dgo-metric,.dgo-kpi-card {
  background: var(--dgo-card-bg,var(--dgo-color-surface-raised));
  border-color: var(--dgo-card-border,var(--dgo-color-border-default));
  border-radius: var(--dgo-card-radius,var(--dgo-radius-card));
  box-shadow: var(--dgo-card-shadow,var(--dgo-elevation-card));
}
.workspace { container-type: inline-size; }
.pagehead,.dgo-module-view__head { gap: var(--dgo-s-3); }
.eyebrow,.dgo-overline { color: var(--dgo-color-action-accent); font-weight: var(--dgo-wt-700); letter-spacing: var(--dgo-tr-widest); }
h1,h2,h3,h4 { font-family: var(--dgo-family-display); color: var(--dgo-color-fg-strong); }
.subtitle,.meta { color: var(--dgo-color-fg-muted); }

/* KPI/metric contract: only modules that call kpis() render this component. */
.kpis,.dgo-dashboard__metrics { grid-template-columns: repeat(auto-fit,minmax(min(100%,13rem),1fr)); gap: var(--dgo-s-4); }
.kpi,.dgo-metric { padding: var(--dgo-card-pad,var(--dgo-s-5)); border-left-color: var(--dgo-color-action-accent); }
.kpi small,.dgo-metric__label { color: var(--dgo-color-fg-muted); font-size: var(--dgo-type-caption); letter-spacing: var(--dgo-tr-wide); text-transform: uppercase; }
.kpi b,.dgo-metric__value { color: var(--dgo-color-fg-strong); font-family: var(--dgo-family-display); font-size: var(--dgo-type-h1); line-height: var(--dgo-lh-110); }

/* Status, pills, chips and badges. */
.pill,.chip,.badge { /* .dgo-pill* owned solely by components.css */
  display:inline-flex; align-items:center; justify-content:center; gap:var(--dgo-s-1);
  min-block-size: var(--dgo-badge-h,22px);
  padding-inline: var(--dgo-badge-px,var(--dgo-s-2));
  border-radius: var(--dgo-badge-radius,var(--dgo-r-pill));
  font-size: var(--dgo-badge-fs,var(--dgo-type-caption));
  font-weight: var(--dgo-badge-fw,var(--dgo-wt-600));
  background: var(--dgo-color-surface-sunken);
  color: var(--dgo-color-fg-default);
  border: 1px solid transparent;
}
.pill.ok,.chip.ok { background: var(--dgo-color-success-subtle-bg); color: var(--dgo-color-success-subtle-fg); }
.pill.danger,.chip.danger { background: var(--dgo-color-danger-subtle-bg); color: var(--dgo-color-danger-subtle-fg); }
.pill.info,.chip.info { background: var(--dgo-color-info-subtle-bg); color: var(--dgo-color-info-subtle-fg); }
.pill:not(.ok):not(.danger):not(.info) { background: var(--dgo-color-status-pending-bg); color: var(--dgo-color-status-pending-fg); }
.chip:not(.active) { background: var(--dgo-color-action-primary-soft); color: var(--dgo-color-action-primary); border-color: color-mix(in srgb,var(--dgo-color-action-primary) 24%,transparent); }

/* Tables and data grids. */
.tablewrap,.dgo-table-wrap { overflow:auto; overscroll-behavior:inline contain; }
.tablewrap table,.dgo-table { border-collapse: collapse; inline-size: 100%; font-size: var(--dgo-type-body-sm); }
th { color: var(--dgo-table-header-fg); font-weight: var(--dgo-wt-600); text-transform: uppercase; }
td,th { border-block-end: 1px solid var(--dgo-table-border,var(--dgo-color-border-default)); }
tbody tr:hover td { background: var(--dgo-table-row-hover); }
.navlink { min-block-size: var(--dgo-control-target-min,44px); }
.navlink.active,.navlink:hover { background: color-mix(in srgb,var(--dgo-color-action-accent) 16%,transparent); color: var(--dgo-color-fg-on-brand); }
.footer { border-color: var(--dgo-color-border-default); }
dialog::backdrop { backdrop-filter: blur(var(--dgo-backdrop-blur,4px)); }

/* New revised design-system components used by enriched modules. */
.dgo-timeline,.timeline { position:relative; display:grid; gap:var(--dgo-s-4); padding-inline-start:var(--dgo-s-7); }
.dgo-timeline::before,.timeline::before { content:""; position:absolute; inset-block:var(--dgo-s-1); inset-inline-start:var(--dgo-s-2); inline-size:2px; background:var(--dgo-color-border-default); }
.timeline li { position:relative; list-style:none; }
.timeline li::before { content:""; position:absolute; inset-inline-start:calc(-1 * var(--dgo-s-6)); inset-block-start:.35rem; inline-size:var(--dgo-s-3); block-size:var(--dgo-s-3); border-radius:50%; background:var(--dgo-color-action-accent); box-shadow:0 0 0 3px var(--dgo-color-surface-raised); }
.thread { max-block-size:min(56vh,34rem); overflow:auto; }
.msg { padding:var(--dgo-s-3); border:1px solid var(--dgo-color-border-default); border-radius:var(--dgo-radius-card); background:var(--dgo-color-surface-sunken); }
.msg.mine { background:var(--dgo-color-action-primary-soft); color:var(--dgo-color-action-primary); }
.msg .who { display:block; color:var(--dgo-color-fg-muted); font-size:var(--dgo-type-caption); font-weight:var(--dgo-wt-700); margin-block-end:var(--dgo-s-1); }
.welcome__card,.welcome__item { border-color:var(--dgo-color-border-default); border-radius:var(--dgo-radius-card); }

@media (forced-colors:active) {
  .panel,.record,.empty,.tablewrap,.kpi,.toolbar,.btn,.iconbtn,dialog { border-color: CanvasText; box-shadow:none; }
  .navlink.active { outline: 2px solid Highlight; }
}
@media (prefers-reduced-motion:reduce) {
  *,*::before,*::after { scroll-behavior:auto !important; animation-duration:.01ms !important; animation-iteration-count:1 !important; transition-duration:.01ms !important; }
}
@media print {
  .nav,.top,.ministry,.feedback,.pane,.welcome { display:none !important; }
  html,body,.shell,.content,main { overflow:visible !important; height:auto !important; }
  .panel,.record,.kpi,.tablewrap { box-shadow:none; break-inside:avoid; }
}

/* ============================================================
   DGO v2.0 — Modern Reset
   ============================================================ */

*, *::before, *::after { box-sizing: border-box; }

html {
  -webkit-text-size-adjust: 100%;
  -moz-text-size-adjust: 100%;
  text-size-adjust: 100%;
  text-rendering: optimizeLegibility;
}

body {
  margin: 0;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6, p, figure, blockquote, dl, dd { margin: 0; }
ul[role="list"], ol[role="list"] { list-style: none; padding: 0; margin: 0; }
img, picture, video, canvas, svg { display: block; max-width: 100%; }
input, button, textarea, select { font: inherit; color: inherit; }

button {
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
}

table { border-collapse: collapse; }
[hidden] { display: none !important; }

/* Focus outline replaced everywhere with semantic focus ring */
:focus { outline: none; }
:focus-visible { outline: none; }

/* Logical-only margin reset for RTL safety */
ul, ol {
  padding-inline-start: 1.5rem;
}

/* H-01 — one breakpoint scale, expressed as design-system tokens beside the colour and
   type tokens, and shared by both platforms.
 *
 * Measured before this file existed:
 *
 *   internal platform  480 520 560 600 720 768 820 900 980 1000 1024 1100 1180 1280 1500
 *                      — fifteen width values, several within 24px of each other
 *   document portal    600 640 900 960 1080
 *                      — five, of which two (600, 900) were shared, and both of those only
 *                        because the two packages ship the same base.css and layout.css
 *
 * The same shared component reflowed at a different width in each platform, so no reflow
 * behaviour could be reasoned about or tested once. Four values now, one meaning each:
 *
 *   sm  640   phone            below this, one column and the compact chrome
 *   md  900   tablet           below this, the sidebar becomes a drawer and the portal nav
 *                              becomes a menu control
 *   lg  1200  laptop           below this, two-pane and multi-column layouts collapse
 *   xl  1536  wide desktop     above this, layouts stop growing and centre
 *
 * CSS custom properties cannot be used inside a media query's condition, so these tokens do
 * not enforce themselves — tests/breakpoint-scale.test.mjs does. It reads every stylesheet in
 * both packages and fails on any width-based media query that is not one of these four
 * values. Add a fifth here and to that test, deliberately, or not at all.
 *
 * Height and orientation rules are a separate axis and are not governed by this scale.
 */
:root {
  --dgo-bp-sm: 640px;
  --dgo-bp-md: 900px;
  --dgo-bp-lg: 1200px;
  --dgo-bp-xl: 1536px;

  /* The min-width side of each boundary, so a pair of rules cannot overlap by a pixel. */
  --dgo-bp-sm-up: 641px;
  --dgo-bp-md-up: 901px;
  --dgo-bp-lg-up: 1201px;
  --dgo-bp-xl-up: 1537px;
}

