  --dgo-cmdk-w:               clamp(320px, 90vw, 640px); /* @kind spacing */
  --dgo-cmdk-bg:              var(--dgo-color-surface-raised);
  --dgo-cmdk-border:          var(--dgo-color-border-default);
  --dgo-cmdk-radius:          var(--dgo-radius-frame);
